/* Importado integralmente dos PDFs de provas Revalida INEP enviados pelo usuário. Saneado e deduplicado. */
window.TRYCKTRACK_QUESTION_BANK = (window.TRYCKTRACK_QUESTION_BANK || []).concat([{"id":"revalida-2025-2-001","number":1,"area":"Reumatologia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Paciente do sexo masculino, 71 anos, aposentado, ex-trabalhador rural durante 35 anos, procura atendimento médico na Unidade Básica de Saúde (UBS) com dor lombar, predominante no período noturno, associada à perda de peso há cerca de 15 dias. Apresenta dores em região cervical, ombros e joelhos, exacerbadas aos esforços físicos. Relata transplante hepático há 2 anos, por câncer de fígado, fazendo uso regular de medicamento imunossupressor. Exame físico: bom estado geral, eupneico, acianótico, anictérico, afebril e normocorado. Ausculta cardíaca e respiratória sem alterações. Abdome normotenso, indolor à palpação, sem visceromegalias. Extremidades aquecidas e perfundidas, sem edema. Dorso: acentuada lordose lombar e dor à mobilização da coluna lombossacra. Avaliação neuromuscular: força muscular preservada, sensibilidade sem alterações e reflexos normais. Diante desse caso, qual é o exame e a conduta adequada, respectivamente?","options":{"A":"Tomografia abdominal com contraste; indicar fisioterapia.","B":"Cintilografia óssea; prescrever anti-inflamatórios e repouso.","C":"Radiografia de coluna lombossacra; prescrever opioides e corticoides.","D":"Ultrassom do aparelho urinário; prescrever analgésicos e anti-inflamatórios."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Doenças sistêmicas com manifestações reumatológicas","topico":"Artropatias associadas a neoplasias"},{"id":"revalida-2025-2-014","number":14,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Lactente de 9 meses foi admitido em Unidade de Pronto Atendimento (UPA) com quadro de diarreia; febre de 38,5 °C; diminuição do volume urinário; sonolência alternada com períodos de irritabilidade; apatia; palidez de pele. Ao exame físico: peso de 9 kg; temperatura axilar de 38 °C; frequência cardíaca e 130 bpm; frequência respiratória de 34 rpm; pressão arterial de 80 x 50 mmHg; mau estado geral; sonolento; reagindo com irritabilidade aos estímulos; palidez de pele; tecido subcutâneo com turgor pastoso; mucosas ressecadas; olhos encovados; extremidades frias; pulsos fracos. Tempo de enchimento capilar de 4 segundos. Respiração gemente, com aumento da amplitude e tiragens intercostais. O diagnóstico e a hidratação endovenosa indicada para o caso são, respectivamente,","options":{"A":"choque hipovolêmico; solução fisiológica 180 mL em 15 minutos.","B":"choque hipovolêmico; solução glicofisiológica 270 mL em 30 minutos.","C":"desidratação grave; solução fisiológica 270 mL em 60 minutos.","D":"desidratação grave; solução glicofisiológica 900 mL em 120 minutos."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Gastrologia Pediátrica","topico":"Diarreia Aguda ","subtopico":"Manejo da hidratação"},{"id":"revalida-2025-2-016","number":16,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Diagnóstico do Autismo Ao ser avaliado em consulta de puericultura, lactente apresenta alterações dos marcos de desenvolvimento em relação a comunicação, comportamento e socialização. Nesse caso, o médico deve fazer triagem específica para transtorno do espectro autista (TEA)","options":{"A":"aos 2, 4 e 10 meses, independentemente se o quadro é associado à epilepsia, distúrbios do sono ou deficiência intelectual.","B":"aos 9, 18 e 30 meses, independentemente se o quadro é associado à epilepsia, distúrbio do sono ou deficiência intelectual.","C":"aos 12, 24 e 36 meses, principalmente se o quadro é associado à história familiar de TEA ou à deficiência intelectual.","D":"aos 2, 4 e 6 anos, principalmente se o quadro é associado à história familiar de TEA ou à deficiência intelectual."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"DNPM (Desenvolvimento Neuro-Psico-Motor)","subtopico":"Avaliando o desenvolvimento"},{"id":"revalida-2025-2-023","number":23,"area":"Cirurgia Geral","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Álcool Homem de 43 anos, dependente de álcool há 23 anos (20 doses de aguardente/dia), teve queda da própria altura com fratura fechada de tíbia, sem traumatismo cranioencefálico. Levado ao pronto-socorro, constata-se, além da fratura, nível de consciência e atenção Flutuantes, desorientação temporoespacial parcial. Glicemia capilar de 45 mg/dL. Prescreve-se imediatamente reposição de glicose e hidratação. Paciente evolui com melhora inicial do estado mental e piora nas horas seguintes, passando a apresentar confusão mental, rebaixamento do nível de consciência, alterações oculares e ataxia. Encontra-se, então, hidratado, com glicemia capilar de 90 mg/dL e eletrólitos dentro da faixa de normalidade. Para tratar o quadro atual desse paciente, a seguinte conduta medicamentosa deve ser realizada imediatamente:","options":{"A":"biperideno, solução injetável 5 mg/mL, 1 ampola intravenosa lentamente.","B":"diazepam, solução injetável 10 mg/mL, 1 ampola intravenosa lentamente.","C":"haloperidol, solução injetável 5 mg/mL, 1 ampola intramuscular em região glútea.","D":"tiamina, solução injetável 100 mg/mL, 5 ampolas diluídas em soro fisiológico durante 30 minutos."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Politrauma Ortopédico","subtopico":"Politrauma Ortopédico"},{"id":"revalida-2025-2-046","number":46,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Criança de 7 meses é levada pela mãe à Unidade Básica de Saúde (UBS), com história de febre há 2 dias e recusa alimentar. Ao exame físico, foi identificada erupção papulovesicular, principalmente em mãos e pés, além de vesículas e úlceras em língua, mucosa jugal e pilares tonsilares. O médico deverá orientar os familiares que","options":{"A":"a evolução da doença é benigna, mas está indicada internação, pela frequência elevada de complicações.","B":"as complicações neurológicas e cardiológicas, como encefalite, miocardite e pericardite, podem ocorrer.","C":"a localização das lesões descrita no caso é atípica, sendo mais comum em nádegas e região perianal.","D":"o desaparecimento da febre e das lesões de pele costuma ocorrer após 5 a 7 dias do início do quadro."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infectologia Pediátrica","topico":"Doenças exantemáticas","subtopico":"Herpangina (Doença Mão-Pé-Boca) "},{"id":"revalida-2025-2-057","number":57,"area":"Psiquiatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Homem de 20 anos, com diagnóstico de esquizofrenia, chega à Unidade de Pronto Atendimento (UPA) acompanhado de familiares, que descrevem que o paciente acordou “torto”. Há 5 dias, foi realizada a troca de risperidona por haloperidol, pois aquela estava em falta na farmácia. Paciente nega outras queixas clínicas. Ao exame, apresenta contratura de região cervical e fácies de dor. Quais são, respectivamente, a hipótese diagnóstica mais provável e a conduta mais adequada?","options":{"A":"Distonia; biperideno intramuscular.","B":"Acatisia; haloperidol intramuscular.","C":"Discinesia tardia; diazepam intramuscular.","D":"Síndrome extrapiramidal; prometazina intramuscular."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Psicofarmacologia","topico":"Síndrome Extrapiraminal (SEP)"},{"id":"revalida-2025-2-059","number":59,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Paciente de 7 anos, na 4ª semana de tratamento quimioterápico para leucemia linfocítica aguda, é admitido em hospital terciário com história de febre há 12 horas (temperatura axilar de 39 °C), tosse e dispneia. Após 24 horas da admissão, segue febril, apesar de ter usado dipirona há 1 hora, e mantém diurese de 2 mL/kg/h. Exame físico: hidratado; pálido; orientado no tempo e no espaço; frequência cardíaca de 130 bpm; temperatura axilar de 39 °C; frequência respiratória de 36 irpm; pressão arterial de 90 x 60 mmHg; boa perfusão periférica; murmúrio vesicular diminuído em base de hemitórax à direita, com crepitações; bulhas taquicárdicas; fígado a 4 cm do rebordo costal direito e 5 cm do apêndice xifoide; baço a 4 cm do rebordo costal esquerdo. Os exames laboratoriais evidenciam lactato aumentado, acidose metabólica e hemograma com leucocitose com desvio à esquerda. Com base no quadro descrito, o diagnóstico é","options":{"A":"sepse.","B":"choque séptico.","C":"disfunção de múltiplos órgãos.","D":"síndrome da resposta inflamatória sistêmica."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Emergências Pediátricas","topico":"Choque em Pediatria","subtopico":"Fisiopatologia"},{"id":"revalida-2025-2-060","number":60,"area":"Cirurgia Geral","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Paciente feminina de 78 anos, com 24 horas de evolução de dor e abaulamento progressivo em região inguinal direita. Apresentou também alguns episódios de vômitos e diminuição da eliminação de Tatos. Antecedentes: neoplasia de mama há 30 anos, diabetes mellitus há 20 anos e tabagista de 40 maços/ ano. Ao exame estava normotensa, eucárdica, afebril, eupneica. Índice de massa corporal de 3 5 kg/m². Abdome globoso, depressível, com abaulamento não redutível e desconforto à palpação em região inguinal direita, com discreta hiperemia local e sem sinais de irritação peritoneal. Resultados dos exames laboratoriais: A hipótese diagnóstica mais provável é","options":{"A":"isquemia mesentérica.","B":"hérnia inguinal indireta.","C":"hérnia femoral encarcerada.","D":"neoplasia de cólon obstrutiva."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Hérnias da Parede Abdominal","topico":"Hérnias Inguinocrurais","subtopico":"Hérnia Femoral"},{"id":"revalida-2025-2-061","number":61,"area":"Obstetrícia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Paciente de 25 anos, com duas gestações e um parto, no segundo trimestre de gestação, compareceu à primeira consulta de pré-natal sem queixas. Após orientações e realização dos testes rápidos, verificou-se que o teste para sífilis foi positivo e imediatamente a paciente recebeu 2,4 milhões UI de penicilina benzatina intramuscular. Paciente nega diagnóstico e tratamento prévios para sífilis. Em relação ao acompanhamento da paciente, é correto afirmar que","options":{"A":"com o tratamento instituído, o feto não terá sequelas.","B":"titulações menores ou iguais a um quarto indicarão cicatriz sorológica.","C":"a queda de duas titulações do VDRL indicará efetividade de tratamento.","D":"o exame de FTA-Abs reagente indicará doença ativa."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Doenças associadas à gestação","topico":"Doenças infecciosas na gestação – HIV, sífilis, hepatites, herpes","subtopico":"Sifilis na gestação"},{"id":"revalida-2025-2-062","number":62,"area":"Cardiologia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Homem de 52 anos, branco, solteiro, comparece à consulta agendada na Unidade Básica de Saúde (UBS) desejando realizar revisão clínica e exames laboratoriais. Desde os 35 anos não faz acompanhamento de saúde. Relata história familiar de diabetes e hipertensão, e a mãe faleceu com câncer de pulmão. Sem história familiar de câncer de próstata. Fuma cerca de 2 maços por dia há 21 anos. Exame físico: pressão arterial de 120 x 80 mmHg, índice de massa corporal de 23 kg/m² , sem outras alterações. Considerando as recomendações de rastreamento para esse paciente, o médico de família e comunidade deve","options":{"A":"solicitar exames de colesterol total e frações, hemograma, glicemia de jejum, creatinina, PSA, radiografia de tórax, colonoscopia, realizar toque retal; orientar sobre a prática de atividade física regular.","B":"solicitar exames de colesterol total, glicemia de jejum, pesquisa de sangue oculto nas fezes, PSA, ofertar anti-HIV e HBsAg, realizar toque retal; orientar sobre participação no grupo na UBS para abandono do tabagismo.","C":"abordar mudanças no estilo de vida e cessação do tabagismo; acompanhar, e m consultas longitudinais, as futuras possibilidades de exames complementares, quando o paciente atingir faixa etária para investigações adicionais","D":"solicitar exames de colesterol total, HDL e triglicerídeos, glicemia de jejum, pesquisa de sangue oculto nas fezes, ofertar testes rápidos para HIV, sífilis e hepatites B e C; realizar abordagem sobre possibilidade de cessação do tabagismo."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Aterosclerose e Doença Arterial Coronariana","topico":"Abordagem das dislipidemias e estratificação de risco cardiovascular"},{"id":"revalida-2025-2-064","number":64,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"um menino de 10 anos levam a criança para avaliação médica em Unidade Básica de Saúde (UBS). Relatam que seu Filho se dá bem com a família até que não lhe seja permitido fazer algo que deseja. Quando isso ocorre, ele Bca irritado, impulsivamente agressivo e agitado por várias horas. Assim que se acalma ou consegue o que quer, Bca feliz e agradável novamente. Os pais entendem que o Filho parece agir deliberadamente para aborrecer os outros e nunca assume a culpa por seus próprios erros ou mau comportamento. Relatam ainda que ele discute com adultos ou Bguras de autoridade e em várias situações não aceita as regras de boa convivência com os familiares. Considerando o caso descrito, qual é o diagnóstico mais provável?","options":{"A":"Transtorno afetivo bipolar.","B":"Transtorno de oposição desafiante.","C":"Transtorno disruptivo da desregulação do humor.","D":"Transtorno do déficit de atenção e hiperatividade."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Hebiatria","subtopico":"Desenvolvimento psicossocial do adolescente"},{"id":"revalida-2025-2-065","number":65,"area":"Nefrologia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Homem de 50 anos, queixando-se de astenia e constipação com fezes em Bta. Há 15 dias, apresenta edema de membros inferiores até a raiz da região crural, bilateralmente, com pouca melhora à elevação dos membros. Ele perdeu 10 kg em 6 meses. Nega hipertensão arterial e diabetes mellitus e não faz uso de medicamento. Os exames do paciente apresentaram os seguintes resultados: Dentre esses achados laboratoriais, quais são necessários para a definição da síndrome renal do paciente?","options":{"A":"Proteína urinária de 24 horas = 3,6 g e albumina sérica = 1,8 g/dL.","B":"Proteína urinária de 24 horas = 3,6 g e triglicerídeos = 200 mg/dL.","C":"Hematúria e triglicerídeos = 200 mg/dL.","D":"Hematúria e albumina sérica = 1,8 g/dL."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Glomerulopatias","topico":"As grandes síndromes glomerulares"},{"id":"revalida-2025-2-077","number":77,"area":"Reumatologia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Homem de 48 anos, auxiliar de pedreiro, procura Unidade Básica de Saúde (UBS) com queixa de dor lombar iniciada há 3 semanas, de instalação insidiosa, sem irradiação. Relata que a dor piora ao Final do dia e melhora parcialmente com repouso e uso de paracetamol. Nega perda de peso, febre, traumas, incontinência ou fraqueza nos membros inferiores. Ao exame físico, apresenta dor à palpação paravertebral em região lombar, sem alterações neurológicas. Com base na história clínica e no exame físico, qual o próximo passo na condução desse caso?","options":{"A":"Solicitar ressonância magnética da coluna lombar e encaminhar para a ortopedia.","B":"Solicitar radiografia lombar, prescrever corticoide oral e agendar o retorno após 10 dias.","C":"Orientar repouso, fornecer atestado de 7 dias e otimizar a analgesia com antidepressivo tricíclico.","D":"Explicar a natureza benigna, orientar analgesia e atividade física leve, com reavaliação em 4 a 6 semanas."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Artropatias inflamatórias","topico":"Espondiloartrites"},{"id":"revalida-2025-2-080","number":80,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Fimose Menino de 6 anos é levado à Unidade Básica de Saúde (UBS) com queixa de Fimose. Mãe relata balanopostites frequentes, sendo o primeiro episódio com 1 ano de vida. Nega infecções do trato urinário. Ao exame físico, apresenta prepúcio cobrindo toda a glande que, quando tracionado, expõe meato uretral e anel fibrótico prepucial. Sobre o caso, assinale a alternativa correta.","options":{"A":"Trata-se de fimose fisiológica, necessitando de exercícios de redução e higiene do prepúcio.","B":"Há indicação cirúrgica na adolescência, pois já está apresentando exposição de meato uretral.","C":"Há indicação cirúrgica, pois a criança apresenta balanopostites recorrentes com fibrose prepucial.","D":"Indica-se uso de creme de betametasona e hialuronidase por 4 semanas, uma vez que apresenta exposição de meato uretral."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Puericultura Geral","subtopico":"Consultas em Pediatria"},{"id":"revalida-2025-2-084","number":84,"area":"Infectologia","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Sensibilidade Especificidade Uma instituição de saúde está pesquisando um novo teste de triagem para hanseníase, com sensibilidade de 92% e especificidade de 65%, aplicado em uma população com baixa prevalência da doença. Nesse contexto, é correto afirmar que","options":{"A":"quase todos os testes positivos indicarão verdadeiros casos de hanseníase, diante da elevada sensibilidade do teste.","B":"o número de falsos-positivos será elevado, devido à baixa especificidade do teste e à baixa prevalência da doença.","C":"o número de falsos-negativos será elevado, reduzindo a capacidade do teste em detectar casos reais.","D":"a elevada sensibilidade do teste o torna ideal para a confirmação do diagnóstico de hanseníase."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"HIV/Aids","topico":"Diagnóstico"},{"id":"revalida-2025-2-087","number":87,"area":"Pediatria","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Fisiopatologia Diagnóstico Diagnóstico Diferencial Menino, 10 anos, morador de área urbana, está em avaliação no pronto-atendimento por apresentar dor em cotovelo direito há 1 dia. Há 1 semana, iniciou quadro de febre de 38,5 °C, 1 a 2 picos ao dia, associada à dificuldade de deambular devido ao joelho direito apresentar-se “doloroso e inchado”. Após 4 dias, percebeu melhora da dor no joelho, porém o tornozelo direito começou a Bcar “inchado e um pouco avermelhado”, doloroso, com melhora em 2 dias. Há 3 semanas, havia se queixado de dor de garganta. Sem outras queixas. Nega contato com animais domésticos. No momento do atendimento, está com dificuldade para movimentar o cotovelo direito por causa da dor e do edema, frequência cardíaca de 110 bpm e 2 bulhas rítmicas normofonéticas, com sopro sistólico de 3+/6+. Restante do exame físico sem anormalidades. Considerando o quadro clínico apresentado, o agente etiológico e o tratamento de escolha são, respectivamente,","options":{"A":"Borrelia burgdorferi; doxiciclina.","B":"Staphylococcus aureus; oxacilina.","C":"Treponema pallidum; penicilina G benzatina.","D":"Streptococcus pyogenes; penicilina G benzatina."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Reumatologia Pediátrica","topico":"Febre Reumática (FR)","subtopico":"Tratamento e prevenção"},{"id":"revalida-2025-2-093","number":93,"area":"Cirurgia Geral","source":"Revalida INEP 2025.2","examId":"revalida-2025-2","examName":"Revalida INEP: 2025.2","stem":"Homem de 66 anos, em pós-operatório precoce de revascularização cardíaca, é encaminhado ao pronto-socorro, com queixa de dor abdominal progressiva em quadrante inferior esquerdo há 5 dias e piora há 1 dia, com aumento do número de evacuações para 3 vezes ao dia. Relata febre não aferida. Exame físico: bom estado geral, eupneico, pressão arterial de 110 x 60 mmHg, temperatura axilar de 38 °C e frequência cardíaca de 100 bpm. Ao exame abdominal, defesa voluntária da musculatura e dor à palpação superficial e profunda, com massa em quadrante inferior esquerdo. Ao toque retal, presença de uma massa Flutuante dolorosa à esquerda. Tomografia de abdome com contraste: densificação dos planos gordurosos adjacente ao sigmoide, associada a coleção de 100 mm³ no local. Após iniciada a antibioticoterapia sistêmica, qual é a conduta mais adequada para esse paciente?","options":{"A":"Laparotomia para drenagem.","B":"Tratamento clínico conservador.","C":"Drenagem guiada por colonoscopia.","D":"Drenagem percutânea guiada por tomografia."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Urgências Abdominais","topico":"Abdome Agudo Inflamatório","subtopico":"Diverticulite Aguda"},{"id":"revalida-2024-1-007","number":7,"stem":"Um paciente com 68 anos, submetido a hemicolectomia esquerda por neoplasia com anastomose terminoterminal, sem intercorrências, refere, no quinto dia de pós-operatório, dor leve abdominal.\n\nAo exame físico, apresenta-se hidratado, com temperatura axilar de 38,1 °C, frequência cardíaca de 96 bpm, pressão arterial de 100 X 70 mmHg, frequência respiratória de 20 irpm. Abdome distendido 1+/4+, ruídos hidroaéreos presentes, timpanismo generalizado à percussão e levemente doloroso à palpação profunda generalizada. Aparelhos cardiovascular e respiratório sem alterações. Ferida operatória limpa, sem sinais flogísticos.\n\nNesse caso, qual é a origem mais provável do quadro de febre apresentado pelo paciente?","options":{"A":"Atelectasia.","B":"Infecção urinária.","C":"Abcesso subfrênico.","D":"Infecção do sítio cirúrgico profundo."},"answer":"A","area":"Cirurgia Geral","assunto":"Complicações Pós-Operatórias","topico":"Febre Pós-operatória","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Principais Causas"},{"id":"revalida-2024-1-017","number":17,"stem":"Uma paciente com 32 anos refere mal-estar geral, febrícula e coriza há 10 dias. Refere também hábito frequente de lavar e assoar o nariz com soro fisiológico. Há dois dias, após uma sessão prolongada de natação, relata sentir o ouvido direito obstruído, dor localizada e piora da sensação de febre. A paciente trata de lúpus eritematoso sistêmico há dois anos. Ao exame físico geral, apresenta dor em joelhos bilateralmente. Realizam-se os exames de: rinoscopia, em que se verifica hiperemia leve de epitélio nasal; e otoscopia, em que se observa leve hiperemia de membrana timpânica bilateral, demostrando membrana timpânica imóvel bilateralmente à otoscopia pneumática.\n\nNesse caso, o diagnóstico e o tratamento indicados são, respectivamente:","options":{"A":"otite média crônica lúpica; antibioticoterapia tópica por 7 dias, corticoterapia sistêmica.","B":"otite média aguda fúngica; claritromicina e fluconazol por 21 dias, timpanotomia direita.","C":"otite externa subaguda viral; antibioticoterapia tópica por 15 dias, anti-inflamatórios sistêmicos.","D":"otite média aguda bacteriana; amoxacilina e clavulanato por 10 dias; descongestionantes e anti-histamínicos."},"answer":"D","area":"Otorrinolaringologia","assunto":"Infecções das Vias Aéreas Superiores","topico":"Otites","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1"},{"id":"revalida-2024-1-020","number":20,"stem":"Uma criança com 2 anos é levada por sua mãe à unidade básica de saúde a fim de verificar se a criança está com peso e altura adequados para a idade.\n\nAo realizar o exame clínico da criança, o médico observa os seguintes dados.\n\nINDICADOR ESCORE-Z\nEstatura para idade: -0,7\nPeso para idade: 2,6\nÍndice de Massa Corporal para idade: 2,8\n\nA partir dos dados observados, a conduta médica correta para dar prosseguimento ao cuidado com a criança é","options":{"A":"tranquilizar a mãe, pois a criança apresenta peso e estatura adequados para sua idade.","B":"solicitar radiografia de punho e mão, pois a criança apresenta baixa estatura para sua idade.","C":"realizar encaminhamento para endocrinopediatra, pois a criança apresenta sobrepeso e baixa estatura.","D":"orientar acerca de estilo de vida, pois a criança se encontra com sobrepeso, apesar de estar com estatura adequada."},"answer":"D","area":"Pediatria","assunto":"Puericultura ","topico":"Crescimento","annulled":false,"images":["assets/revalida/img/revalida-2024-1-020-1.png"],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Curvas de Crescimento"},{"id":"revalida-2024-1-043","number":43,"stem":"Um lactente com 2 anos, previamente hígido, é levado à unidade de pronto atendimento com quadro de diarreia, com fezes líquidas sem muco ou sangue. Além disso, apresenta vômitos e febre há 48 horas.\n\nAo exame físico, o paciente está sonolento, hipotônico, com olhos fundos, mucosas secas e ausência de lágrimas. O pulso está débil e o enchimento capilar é > 5 segundos.\n\nNesse caso, qual tratamento inicial deve ser ministrado, segundo o fluxograma do Ministério da Saúde do Brasil de 2023?","options":{"A":"Solução de reidratação oral de 50 a 100 mL/kg por via oral, por um período de 4 a 6 horas.","B":"Solução de reidratação oral de 50 a 100 mL/kg por gastróclise, por um período de 4 a 6 horas.","C":"Soro fisiológico a 0,9% 30 mL/kg por via endovenosa; em 30 minutos, administrar + Ringer Lactato 30 mL/kg em 2 horas.","D":"Soro fisiológico a 0,9% 20 mL/kg por via endovenosa; em 30 minutos, repetir essa quantidade até que a criança esteja hidratada."},"answer":"D","area":"Pediatria","assunto":"Gastrologia Pediátrica","topico":"Diarreia Aguda ","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Manejo da hidratação"},{"id":"revalida-2024-1-050","number":50,"stem":"Um médico de família e comunidade é chamado para verificar, juntamente com sua equipe de saúde da família, um óbito domiciliar de um homem com 78 anos. O paciente fazia acompanhamento por hipertensão arterial sistêmica, diabetes mellitus e síndrome metabólica de difícil controle. Um familiar refere que o paciente acordou cedo, sentiu forte dor precordial, irradiando para o braço esquerdo, ficou pálido e sudoreico e caiu no chão. No domicílio, o médico e sua equipe realizam procedimentos para confirmação do óbito buscando a existência de rigidez cadavérica, realizando avaliação da temperatura corporal e identificando a presença ou não de possível achado de causa externa — possibilidade que é excluída. Após examinar o corpo, inicia-se a fase preenchimento da declaração de óbito (DO). Na seção de condições e causas do óbito constante na DO, há alguns itens a serem preenchidos, quais sejam, causa básica do óbito, causa imediata do óbito e causa contributiva. Com base nessa situação, assinale a alternativa que apresenta o preenchimento correto a ser feito na declaração com relação à causa de óbito desse paciente.","options":{"A":"Causa básica: síndrome metabólica.","B":"Causa contributiva: diabetes mellitus.","C":"Causa básica: infarto agudo do miocárdio.","D":"Causa imediata: doença arterial aterosclerótica."},"answer":"B","area":"Medicina Preventiva","assunto":"Ética Médica","topico":"Código de Ética Médica (CEM)","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Documentos médicos"},{"id":"revalida-2024-1-056","number":56,"area":"Psiquiatria","source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","stem":"Diagnóstico da Anorexia Nervosa Tratamento da Anorexia Nervosa Durante uma visita domiciliar, o médico de família nota que a Filha de 16 anos do casal visitado aparentava ser muito menor do que o vestido que usava. O casal concorda com a observação e afirma que a filha come pouco. A adolescente relata que não apresenta qualquer problema de saúde e que apenas procura se cuidar fazendo musculação e corrida diariamente, além de seguir as dietas que estuda nas redes sociais. A mãe refere que, seguindo a dieta atual, a Filha havia perdido 7 kg em 1 mês. A adolescente nega vomitar após as refeições ou quaisquer problemas, exceto o fato de não menstruar há 4 meses, negando também ser sexualmente ativa. Ao exame físico, verificam-se altura de 1,7 metros e peso de 45 kg. Observa-se ainda que o exame físico da adolescente não apresenta alterações, exceto aspecto emagrecido e palidez cutaneomucosa. Para esse caso clínico, o diagnóstico e o tratamento a serem considerados inicialmente são, respectivamente,","options":{"A":"bulimia nervosa; bupropiona.","B":"hipertireoidismo; propiltiuracil.","C":"anorexia nervosa; psicoterapia.","D":"transtorno de purgação; metoclopramida."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Transtorno Alimentares","topico":"Anorexia Nervosa"},{"id":"revalida-2024-1-079","number":79,"stem":"Uma puérpera, 14 dias pós-parto vaginal, que vem amamentando exclusivamente seu bebê, procura uma unidade básica de saúde referindo dor em mama direita.\n\nAo exame, evidenciam-se pressão arterial de 120 x 70 mmHg, frequência cardíaca de 90 bpm, temperatura axilar de 37,8 °C, mamas túrgidas e com fissuras nos mamilos, hiperemia, calor e dor na junção dos quadrantes inferiores da mama direita, sem sinais de flutuação.\n\nPara o caso dessa paciente, a hipótese diagnóstica e o tratamento adequado são, respectivamente,","options":{"A":"galactocele; massagem mamária e manutenção da amamentação.","B":"mastite; analgesia, manutenção da amamentação e antibioticoterapia via oral.","C":"abscesso mamário; antibioticoterapia intravenosa e drenagem da mama direita com sedação.","D":"ingurgitamento mamário; aplicação de compressas frias, interrupção da amamentação e manutenção das mamas bem suspensas."},"answer":"B","area":"Pediatria","assunto":"Puericultura ","topico":"Amamentação/ Aleitamento Materno","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Prevenção e manejo dos principais problemas relacionados à amamentação"},{"id":"revalida-2024-1-080","number":80,"stem":"Ao realizar uma visita domiciliar, a médica da unidade básica de saúde avalia uma família de 6 pessoas, sendo a configuração familiar formada por pai, mãe, avó paterna, duas crianças — uma de 9 meses e outra de 4 anos — e uma adolescente de 15 anos. Durante a consulta, a médica solicita as cadernetas de vacina das crianças e da adolescente, a fim de conferir se estão em dia de acordo com o Calendário Nacional de Vacinação.\n\nNesse caso, em relação às vacinas contra a meningite meningocócica, a médica deve observar se as crianças de 9 meses e de 4 anos e se a adolescente de 15 anos possuem, respectivamente,","options":{"A":"uma dose da vacina meningocócica C conjugada; uma dose e um reforço da vacina meningocócica C conjugada; e uma dose da vacina meningocócica ACWY conjugada.","B":"duas doses da vacina meningocócica C conjugada; duas doses e um reforço da vacina meningocócica C conjugada; e uma dose da vacina meningocócica ACWY conjugada.","C":"duas doses e um reforço da vacina meningocócica C conjugada; três doses e um reforço da vacina meningocócica C conjugada; e duas doses da vacina meningocócica ACWY conjugada.","D":"uma dose e um reforço da vacina meningocócica C conjugada; duas doses e um reforço da vacina meningocócica C conjugada; e uma dose da vacina meningocócica ACWY conjugada."},"answer":"B","area":"Pediatria","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Esquema vacinal"},{"id":"revalida-2024-1-081","number":81,"stem":"Uma paciente com 26 anos comparece à unidade de saúde da família para consulta com relato de dispneia aos esforços, que vem se intensificando nos últimos 3 ou 4 meses. O médico a examina e observa um desdobramento fixo da segunda bulha audível em foco pulmonar. O exame físico revela frequência cardíaca em ritmo regular de 80 bpm, sem outros achados.\n\nNesse caso, quais são, respectivamente, o diagnóstico mais provável e o risco potencial relacionado com esse diagnóstico?","options":{"A":"Estenose pulmonar; embolia pulmonar.","B":"Estenose de valva mitral; embolia sistêmica.","C":"Defeito de septo interatrial; embolia sistêmica.","D":"Prolapso de valva mitral; embolia pulmonar."},"answer":"C","area":"Pediatria","assunto":"Cardiologia Pediátrica","topico":"Cardiopediatria e Cardiopatias congênitas","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Cardiopatias congênitas"},{"id":"revalida-2024-1-102","number":102,"area":"Infectologia","source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","stem":"Vacinas meningocócicas Calendário infantil Calendário dos adolescentes Ao realizar uma visita domiciliar, a médica da unidade básica de saúde avalia uma família de 6 pessoas, sendo a configuração familiar formada por pai, mãe, avó paterna, duas crianças — uma de 9 meses e outra de 4 anos — e uma adolescente de 15 anos. Durante a consulta, a médica solicita as cadernetas de vacina das crianças e da adolescente, a Cm de conferir se estão em dia de acordo com o Calendário Nacional de Vacinação. Nesse caso, em relação às vacinas contra a meningite meningocócica, a médica deve observar se as crianças de 9 meses e de 4 anos e se a adolescente de 15 anos possuem, respectivamente,","options":{"A":"uma dose da vacina meningocócica C conjugada; uma dose e um reforço da vacina meningocócica C conjugada; e uma dose da vacina meningocócica ACWY conjugada.","B":"duas doses da vacina meningocócica C conjugada; duas doses e um reforço da vacina meningocócica C conjugada; e uma dose da vacina meningocócica ACWY conjugada.","C":"duas doses e um reforço da vacina meningocócica C conjugada; três doses e um reforço da vacina meningocócica C conjugada; e duas doses da vacina meningocócica ACWY conjugada.","D":"uma dose e um reforço da vacina meningocócica C conjugada; duas doses e um reforço da vacina meningocócica C conjugada; e uma dose e um reforço da vacina meningocócica ACWY conjugada."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Vacinas","topico":"Calendário vacinal em adultos e idosos"},{"id":"revalida-2024-1-103","number":103,"area":"Obstetrícia","source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","stem":"Processos inflamatórios mastites Mastite lactacional Uma puérpera, 14 dias pós-parto vaginal, que vem amamentando exclusivamente seu bebê, procura uma unidade básica de saúde referindo dor em mama direita. Ao exame, evidenciam-se pressão arterial de 120 x 70 mmHg, frequência cardíaca de 90 bpm, temperatura axilar de 37,8 °C, mamas túrgidas e com Cssuras nos mamilos, hiperemia, calor e dor na junção dos quadrantes inferiores da mama direita, sem sinais de flutuação. Para o caso dessa paciente, a hipótese diagnóstica e o tratamento adequado são, respectivamente","options":{"A":"galactocele; massagem mamária e manutenção da amamentação.","B":"mastite; analgesia, manutenção da amamentação e antibioticoterapia via oral.","C":"abscesso mamário; antibioticoterapia intravenosa e drenagem da mama direita com sedação.","D":"ingurgitamento mamário; aplicação de compressas frias, interrupção da amamentação e manutenção das mamas bem suspensas."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puerpério","topico":"Infecção puerperal / endometrite puerperal","subtopico":"Diagnóstico"},{"id":"revalida-2023-1-058","number":58,"stem":"Um adolescente de 12 anos, pesando 85 kg e com índice de massa corpórea de 30 kg/m², é atendido na emergência queixando-se de fortes dores no quadril direito e de impotência funcional do membro inferior direito. O pai informa ao médico de plantão que o menino é hipertenso, que realiza um tratamento para emagrecer e nega associação do problema na perna a trauma.\n\nNesse caso, a hipótese diagnóstica mais provável é de","options":{"A":"epifisiólise femoral.","B":"artrite séptica do quadril.","C":"artrite reumatoide juvenil.","D":"sinovite transitória do quadril."},"answer":"A","area":"Ortopedia","assunto":"Ortopedia Pediátrica","topico":"Quadril Pediátrico","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1"},{"id":"revalida-2023-1-101","number":101,"area":"Pediatria","source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","stem":"Um lactente com 2 anos, previamente hígido, com história de um dia de febre, tosse e coriza, é atendido no pronto- socorro. A mãe conta que, desde a madrugada, ele apresenta obstrução nasal, sono agitado e cansaço. Ao exame de entrada, mostra-se em bom estado geral, corado, acianótico, agitado; à ausculta pulmonar, são notados murmúrios vesiculares diminuídos e simétricos, tiragem de fúrcula moderada e estridor leve ao repouso. Com base na principal hipótese diagnóstica para esse quadro clínico, a conduta mais adequada no momento é indicar","options":{"A":"salmeterol inalatório e claritromicina.","B":"salbutamol inalatório e metilprednisolona.","C":"dexametasona e nebulização com epinefrina.","D":"prednisolona e nebulização com soro fisiológico."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Pneumologia Pediátrica","topico":"Bronquiolite ","subtopico":"Tratamento"},{"id":"revalida-2023-1-102","number":102,"area":"Cirurgia Geral","source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","stem":"Um adolescente de 12 anos, pesando 85 kg e com índice de massa corpórea de 30 kg/m2, é atendido na emergência queixando-se de fortes dores no quadril direito e de impotência funcional do membro inferior direito. O pai informa ao médico de plantão que o menino é hipertenso, que realiza um tratamento para emagrecer e nega associação do problema na perna a trauma. Nesse caso, a hipótese diagnóstica mais provável é de","options":{"A":"epifisiólise femural.","B":"artrite séptica do quadril.","C":"artrite reumatoide juvenil.","D":"sinovite transitória do quadril."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Politrauma Ortopédico","subtopico":"Politrauma Ortopédico"},{"id":"revalida-2023-1-105","number":105,"area":"Oftalmologia","source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","stem":"Uma paciente com 25 anos apresentou edema, rubor e dor em pálpebra superior direita, com resolução espontânea do quadro em 48 horas. No momento, apresenta nodulação de 0,3 cm, indolor, localizada na face interna do terço médio da pálpebra superior direita. Nega febre ou qualquer outro sintoma. Nesse caso, qual é o diagnóstico mais provável?","options":{"A":"Calázio.","B":"Hordéolo.","C":"Canaliculite.","D":"Dacriocistite."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Síndrome do Olho Vermelho","topico":"Patologias Palpebrais"},{"id":"revalida-2022-2-005","number":5,"stem":"Uma mulher de 34 anos com diagnóstico de depressão procurou a unidade de saúde da família (UBS) onde você trabalha. Com base no prontuário da paciente, você observou que ela faz acompanhamento na unidade há 10 meses com outro médico da unidade. A paciente consulta sozinha, psicologicamente vulnerável, mas chegou à unidade acompanhada da irmã, com quem ela mora e que está bastante preocupada. A paciente tem sintomas de humor deprimido, fatigabilidade e choro fácil; está em uso de 40 mg/dia de fluoxetina nos últimos 6 meses, tendo apresentado discreta melhora. Segundo a paciente, há 1 mês, aproximadamente, começou a ouvir vozes e ver alguns vultos, e tem pensado em se matar, mas sem plano.\n\nNesse caso, qual é a conduta adequada?","options":{"A":"Continuar o atendimento na UBS e trocar o tratamento.","B":"Encaminhar a paciente para internação em hospital psiquiátrico.","C":"Solicitar internação em hospital geral e otimizar o tratamento farmacológico.","D":"Referenciar a paciente à equipe multiprofissional do Centro de Atenção Psicossocial."},"answer":"D","area":"Psiquiatria","assunto":"Transtornos do Humor","topico":"Depressão","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-021","number":21,"area":"Medicina Preventiva","source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","stem":"Medicina Preventiva Sistema Único de Saúde SUS Políticas de Saúde do Sistema Único de Saúde A Agência Nacional de Saúde Suplementar (ANS), vinculada ao Ministério da Saúde, é uma autarquia que regula, normatiza, controla e Hscaliza os planos de saúde. Em novembro de 2021, foi aprovada a Política Nacional de Saúde Suplementar para o enfrentamento da covid-19 (PNSS-Covid-19). Uma das diretrizes dessa política é","options":{"A":"criar um sistema de saúde complementar ao SUS, tendo como eixo a Atenção Primária à Saúde (APS) da rede SUS e a integração de bases de dados relacionadas à covid-19.","B":"promover ações que garantam o atendimento à saúde, visando-se ao melhor desfecho clínico com custo adequado e cuidado centrado na experiência do paciente.","C":"desenvolver mecanismos que posterguem o cumprimento de contratos e o atendimento à saúde, a partir dos critérios da ANS, haja vista a excepcionalidade da pandemia de covid-19.","D":"empreender ações que visem garantir o atendimento às necessidades de tratamento dos pacientes graves, permitindo-se que os casos leves sejam atendidos pela APS da rede SUS."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Sistema Único de Saúde (SUS)","topico":"Financiamento em Saúde","subtopico":"Saúde Suplementar"},{"id":"revalida-2022-2-022","number":22,"area":"Ginecologia","source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","stem":"Mulher de 36 anos de idade, G3P3A0 (3 partos vaginais), compareceu a consulta no centro de saúde, para renovar receita de anticoncepcional injetável mensal. Faz uso do método contraceptivo há 5 anos, com boa adaptação, e não deseja nova gestação. É tabagista, fuma 20 cigarros por dia, e é etilista social. Tem parceiro único há 10 anos. Nega uso de preservativo nas relações sexuais. Diante das informações, qual é a orientação de método anticoncepcional mais adequado para essa paciente?","options":{"A":"Usar contraceptivo oral além do injetável mensal.","B":"Substituir o método utilizado pelo anel vaginal.","C":"Inserir dispositivo intrauterino (DIU) de cobre.","D":"Manter o esquema conceptivo adotado."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Ginecologia endócrina","topico":"Planejamento familiar","subtopico":"Anticoncepção em condições especiais"},{"id":"revalida-2022-2-041","number":41,"area":"Obstetrícia","source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","stem":"Obstetrícia Rastreamento na gestação Primigesta de 24 anos, vendedora, compareceu a unidade de saúde da família (USF) com os resultados de exames solicitados na primeira consulta de pré-natal, realizada havia quatro semanas, ao Final do primeiro trimestre de gestação. Estava com idade gestacional de 16 semanas. Negou queixas e referiu estar em uso regular do ácido fólico e do sulfato ferroso prescritos. Disse estar preocupada com o resultado do exame de toxoplasmose. O médico verificou que a gestante apresentava IgG reagente e IgM não reagente para toxoplasmose. Assinale a opção que indica, respectivamente, o que o exame sugere e a conduta a ser tomada.","options":{"A":"Possivelmente um falso-positivo para toxoplasmose; repetir os exames e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","B":"Compatibilidade com toxoplasmose aguda; iniciar o tratamento específico e encaminhar a paciente para acompanhamento no pré-natal de alto risco.","C":"Toxoplasmose pregressa; tranquilizar a paciente de que não há motivos de preocupação e orientá-la a continuar o acompanhamento habitual no pré-natal na USF.","D":"Suscetibilidade à toxoplasmose; orientar a paciente sobre medidas de prevenção e indicar que ela continue o acompanhamento no pré-natal na USF."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Pré-natal","topico":"Assistência pré-natal","subtopico":"Exames laboratoriais"},{"id":"revalida-2022-2-044","number":44,"area":"Cirurgia Geral","source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","stem":"Homem de 35 anos vítima de acidente automobilístico foi inicialmente atendido em unidade de pronto atendimento e, em seguida, levado pelo serviço de atendimento móvel de urgência ao hospital. No exame físico, apresentava-se com Glasgow 15; frequência cardíaca de 120 batimentos por minuto; frequência respiratória de 24 incursões respiratórias por minuto; pressão arterial de 110 × 70 mmHg; saturação de O2 de 94% em ar ambiente; glicemia capilar de 80 mg/dL; murmúrio vesicular presente bilateralmente, sem ruídos adventícios; ritmo cardíaco regular com bulhas normofonéticas em 2 tempos; abdome sem alterações; força muscular em membros superiores direito e esquerdo grau 4/5, sensibilidade preservada em membros superiores, força grau 0/5 em membro inferior direito e grau 1/5 em membro inferior esquerdo, com sensibilidade de membros inferiores diminuída, reflexos patelar, aquileu e bicipital presentes e simétricos. Assinale a opção que indica o exame complementar inicial a ser solicitado nesse caso.","options":{"A":"Mielografia.","B":"Radiografia simples.","C":"Ressonância magnética.","D":"Tomografia computadorizada."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Avaliação Secundária"},{"id":"revalida-2022-2-045","number":45,"area":"Psiquiatria","source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","stem":"Paciente do sexo feminino, de 23 anos, foi encaminhada para serviço ambulatorial especializado após ter sido estabilizada em atendimento de urgência em internação ocasionada por fraqueza generalizada e lipotimia. Durante a avaliação clínica na urgência, foi constatado que a paciente apresentava hipertrofia de glândulas parótidas, dentes em regular estado de conservação e sinal de Russel nas mãos. Na consulta ambulatorial, foi verificado que a paciente atendia aos critérios do diagnóstico de bulimia nervosa, por apresentar episódios recorrentes de compulsão alimentar, seguidos de comportamentos compensatórios e inapropriados para evitar o ganho de peso (no caso, autoindução de vômitos). Como proposta terapêutica não farmacológica, foi planejada a terapia cognitiva comportamental, em 20 sessões em grupo, durante 5 meses. Em relação à proposta de terapêutica farmacológica para essa paciente, é correto afirmar que,","options":{"A":"entre os inibidores seletivos da recaptação de serotonina, o citalopram é uma opção terapêutica na dose de 10 mg.","B":"entre os inibidores da recaptação de serotonina e noradrenalina, a venlafaxina é uma opção terapêutica na dose de 37,5 mg.","C":"entre os inibidores seletivos da recaptação de serotonina, a fluoxetina é uma opção terapêutica na dose de 60 mg.","D":"entre os anticonvulsivantes, em substituição a antidepressivos, o topiramato é uma opção terapêutica na dose de 25 mg."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Transtorno Obsessivo-Compulsivo (TOC)","topico":"Tratamento do TOC"},{"id":"revalida-2022-2-085","number":85,"stem":"A Agência Nacional de Saúde Suplementar (ANS), vinculada ao Ministério da Saúde, é uma autarquia que regula, normatiza, controla e fiscaliza os planos de saúde. Em novembro de 2021, foi aprovada a Política Nacional de Saúde Suplementar para o enfrentamento da covid-19 (PNSS-Covid-19). Uma das diretrizes dessa política é","options":{"A":"criar um sistema de saúde complementar ao SUS, tendo como eixo a Atenção Primária à Saúde (APS) da rede SUS e a integração de bases de dados relacionadas à covid-19.","B":"promover ações que garantam o atendimento à saúde, visando-se ao melhor desfecho clínico com custo adequado e cuidado centrado na experiência do paciente.","C":"desenvolver mecanismos que posterguem o cumprimento de contratos e o atendimento à saúde, a partir dos critérios da ANS, haja vista a excepcionalidade da pandemia de covid-19.","D":"empreender ações que visem garantir o atendimento às necessidades de tratamento dos pacientes graves, permitindo-se que os casos leves sejam atendidos pela APS da rede SUS."},"answer":"B","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Financiamento em Saúde","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Saúde Suplementar"},{"id":"revalida-2022-2-094","number":94,"stem":"Paciente de 30 anos, com 25 semanas de gestação, portadora de diabetes mellitus tipo 1, compareceu a consulta no pré-natal de alto risco, com queixa de corrimento vaginal com prurido e ardência. Relatou também dispareunia de introito vaginal e disúria. No exame físico, confirmou-se a presença de eritema e fissuras vulvares, corrimento grumoso, com placas aderidas à parede vaginal, de cor branca, edema vulvar e escoriações. Desde o início da gestação, a paciente já tinha tratado 4 vezes os mesmos sintomas.\nQual é o tratamento a ser proposto para a paciente?","options":{"A":"Indução com fluconazol 150 mg, via oral, 1 vez ao dia, dias 1, 4 e 7. Manutenção com fluconazol 150 mg, via oral, 1 vez por semana, por 6 meses.","B":"Indução com itraconazol 100 mg, 2 comprimidos, via oral, 2 vezes ao dia, por 1 dia. Anticoncepcional/Manutenção com miconazol óvulo vaginal, 1 vez por semana, durante 3 meses.","C":"Indução com miconazol creme vaginal tópico diário por 10 a 14 dias. Manutenção com miconazol creme vaginal tópico, 2 vezes por semana, durante 6 meses.","D":"Indução com miconazol creme vaginal tópico diário por 7 dias. Manutenção com miconazol óvulo vaginal, 1 vez por semana, durante 3 meses."},"answer":"C","area":"Ginecologia","assunto":"Infecções em ginecologia","topico":"Vulvovaginites","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Candidíase"},{"id":"revalida-2023-2-018","number":18,"stem":"Um menino de 7 anos é atendido em consulta de rotina na unidade básica de saúde. Ele não apresenta queixas no momento da consulta, porém, ao exame físico genital, é verificada a impossibilidade da retratibilidade completa do prepúcio, para exposição parcial do meato uretral, com anel cicatricial prepucial. Quando a responsável foi questionada acerca dos sintomas observados no paciente, ela referiu que, em duas ocasiões pregressas, ocorreram infecções locais que foram tratadas com antimicrobianos.\n\nCom base no quadro desse paciente, é correto afirmar que ele apresenta","options":{"A":"fimose fisiológica e deve permanecer em acompanhamento pediátrico, com provável resolução espontânea do processo.","B":"fimose patológica e deve ser referenciado para serviço de cirurgia pediátrica para realização de postectomia eletiva.","C":"parafimose e deve ser encaminhado ao serviço de emergência referenciado para realização de manobra de redução pelo cirurgião.","D":"fimose fisiológica e sua responsável deve ser orientada sobre a necessidade de realizar manobras visando a acelerar a abertura do prepúcio."},"answer":"B","area":"Cirurgia Geral","assunto":"Cirurgia Infantil","topico":"Afecções do Trato Geniturinário","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Fimose"},{"id":"revalida-2023-2-037","number":37,"stem":"Um paciente de 71 anos apresenta quadro de sangramento intermitente na urina há 4 semanas, acompanhado por dor em peso no hipogástrio, sensação de plenitude vesical e urgência miccional. Ele relata dois episódios prévios de hematúria com eliminação de cálculos. Possui, como antecedente, hipertensão arterial sistêmica controlada, diabetes mellitus tipo 2, dislipidemia, obesidade e tabagismo (40 maços/ano). \nAcerca desse caso, assinale a opção que apresenta a principal hipótese diagnóstica e os exames mais adequados para a investigação.","options":{"A":"Tumor urotelial; ressonância nuclear magnética e cistoscopia.","B":"Ureterolitíase obstrutiva; urina tipo 1 e urotomografia com contraste.","C":"Hiperplasia benigna de próstata; dosagem de PSA e ultrassonografia transrretal.","D":"Tuberculose genitourinária; urocultura específica para BAAR e urografia excretora."},"answer":"A","area":"Cirurgia Geral","assunto":"Urologia","topico":"Neoplasias Urológicas","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Câncer de Bexiga"},{"id":"revalida-2023-2-056","number":56,"stem":"Um homem de 65 anos, trabalhador rural, procura atendimento em uma unidade de atenção primária à saúde por queixa de dor na região lombar esquerda iniciada há 1 mês. A dor vem piorando progressivamente e, nos últimos dias, tem impossibilitado o sono reparador do paciente. Sua esposa se queixa de que as calças do marido estão com cheiro de urina ultimamente. Ao exame, o paciente está lúcido, colaborativo e as mucosas estão úmidas e hipocoradas. Há retificação da coluna lombar, espasmo muscular localizado e dor à palpação delicada das apófises vertebrais de L2 e L3. As manobras de elevação do membro inferior esquerdo estendido (Lasègue) e do membro inferior direito estendido (Lasègue cruzado) não reproduzem a dor. Como o paciente se queixa de dor com o decúbito ventral, o sinal de Lasègue invertido (Wasserman) foi pesquisado em pé. A extensão das coxas com o paciente em ortostatismo também não provokaram dor.\n\nEm relação a essa situação, assinale a opção que apresenta, respectivamente, o diagnóstico clínico correto e a conduta médica apropriada.","options":{"A":"Dor lombar musculoesquelética; prescrever anti-inflamatórios.","B":"Dor lombar por radiculopatia; encaminhar paciente para o neurocirurgião.","C":"Dor lombar com comprometimento neurológico; solicitar exame de imagem.","D":"Dor lombar postural relacionada à profissão; recomendar repouso e solicitar fisioterapia."},"answer":"C","area":"Ortopedia","assunto":"Ortopedia Geral","topico":"Doenças da coluna vertebral","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-061","number":61,"stem":"Um paciente de 17 anos, previamente hígido, relata cefaleia, dor de garganta e febre há 8 dias. Ao exame físico, apresenta linfonodos cervicais com características fibroelásticas, que são indolores; o maior possui 1,5 cm de diâmetro. Seu exame abdominal está sem alterações. O hemograma revela leucocitose (15 500 células/mm³) e linfocitose com presença de linfócitos atípicos.\n\nDiante desse quadro, a conduta diagnóstica inicial adequada é a realização de","options":{"A":"sorologia para Epstein-Barr.","B":"biópsia excisional do linfonodo.","C":"punção aspirativa da medula óssea.","D":"tomografia computadorizada do pescoço."},"answer":"A","area":"Pediatria","assunto":"Infectologia Pediátrica","topico":"Doenças exantemáticas","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Mononucleose"},{"id":"revalida-2023-2-066","number":66,"stem":"Um homem de 50 anos vai ao ambulatório relatando 3 dias de febre e icterícia. Ele mora em área urbana com falta de saneamento básico e nega viagens recentes. Além de febre e de icterícia, apresenta náuseas, eritema conjuntival bilateral e dor muscular, especialmente em panturrilhas. Os exames iniciais indicam leucocitose com neutrofilia e apresentam os seguintes resultados: potássio de 3 mEq/L (valor de referência [VR]: 3,5 a 5,1 mEq/L); creatinina de 1,8 mg/dL (VR: 0,6 a 1,2 mg/dL); bilirrubina total de 24 mg/dL (VR: 0,2 a 1,2 mg/dL); bilirrubina direta de 19 mg/dL (VR: até 1 mg/dL); transaminase glutâmico oxalacética (TGO) de 98 U/L (VR: 5 a 40 U/L); e transaminase glutâmico pirúvica (TGP) de 102 U/L (VR: 7 a 56 U/L).\n\nA partir dessas informações, é correto afirmar que a hipótese pertinente para o caso apresentado e a investigação complementar são, respectivamente,","options":{"A":"dengue; sorologia IgM para dengue.","B":"hepatite por vírus B; Anti-HBc e HBsAg.","C":"leptospirose; teste de microaglutinação.","D":"febre amarela; sorologia IgM para febre amarela."},"answer":"C","area":"Infectologia","assunto":"Síndromes febris","topico":"Leptospirose","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-069","number":69,"stem":"O Sistema Único de Saúde (SUS) possui normativo a respeito da presença de acompanhantes nos serviços de saúde em sua rede própria ou conveniada.\n\nEm relação dos serviços de saúde durante o período de trabalho de parto, parto e pós-parto imediato, assinale a alternativa correta.","options":{"A":"É desnecessária autorização para filmar o parto, sendo facultado ao acompanhante fazê-lo.","B":"É necessário que o acompanhante tenha grau de instrução pelo menos de primeiro grau completo","C":"É preciso que o acompanhante seja, obrigatoriamente, um parente de 1.º grau — pai, mãe ou irmã(o).","D":"É permitida a mudança de acompanhante ao longo do processo de trabalho de parto, do parto e do pós-parto."},"answer":"D","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Outras normativas do SUS e da Saúde em geral"},{"id":"revalida-2023-2-070","number":70,"stem":"Um paciente de 11 anos é trazido pela mãe para consulta de puericultura na unidade básica de saúde. A família vivia, anteriormente, em uma região de difícil acesso a serviços de saúde e se mudou para o território de abrangência há 3 meses. Durante a consulta, a mãe informa que a criança não apresenta problemas de saúde e não faz uso regular de medicamentos. Quando questionada sobre a situação vacinal da criança, a mãe informa que só se lembra de que o paciente recebeu algumas vacinas do primeiro ano de vida e que não tem o cartão vacinal.\n\nNesse contexto, qual deve ser o esquema vacinal indicado para esse paciente?","options":{"A":"3 doses de hepatite B, 3 doses da dupla adulto (dT), dose única de febre amarela, 2 doses de tríplice viral, 2 doses de HPV e dose única de meningocócica ACWY.","B":"3 doses de hepatite B, 3 doses da dupla adulto (dT), dose única de febre amarela, dose única de tríplice viral, 3 doses de HPV e dose única de meningocócica C.","C":"3 doses de hepatite B, 3 doses da dupla adulto (dT), dose única de febre amarela, 2 doses de tríplice viral e dose única de meningocócica ACWY.","D":"3 doses da pentavalente, 2 doses de febre amarela, 2 doses de tríplice viral, 2 doses de HPV e 2 doses de meningocócica C."},"answer":"A","area":"Pediatria","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Esquema vacinal"},{"id":"revalida-2023-2-087","number":87,"stem":"Uma paciente de 54 anos vem ao consultório com queixa de vermelhidão e dor no olho esquerdo há 4 meses, sem melhora ao usar colírio lubrificante ou anti-inflamatório. Além disso, há 2 semanas, iniciou turvação visual em visão periférica de olho esquerdo. Ela nega queixas no olho direito. A paciente apresenta antecedente de hipertensão arterial sistêmica, diabetes mellitus tipo 2 e depressão, e está em tratamento regular com losartana 50 mg/dia, atenolol 25 mg/dia, hidroclorotiazida 25 mg/dia, metformina 850 mg/dia e amitriptilina 75 mg/dia. O médico, então, realiza exame de fundo de olho e nota, no olho esquerdo, aumento de escavação na periferia da papila óptica sem sinais de hemorragia ou alterações de vasos retinianos ou edema de papila.","options":{"A":"ajustar os hipoglicemiantes orais para evitar a perda visual, pois trata-se de retinopatia diabética.","B":"indicar o uso de vitaminas C e E, betacaroteno e zinco, pois podem retardar a evolução da degeneração.","C":"realizar teste de pressão intraocular e substituir a amitriptilina, pois seu uso aumenta a pressão intraocular.","D":"solicitar exame de imagem intracraniana, pois trata-se de suspeita de tumor que causa compressão retrorbitária."},"answer":"C","area":"Oftalmologia","assunto":"Glaucoma","topico":"Glaucoma Primário de Ângulo Fechado","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-097","number":97,"stem":"Uma paciente de 28 anos procura unidade básica de saúde solicitando encaminhamento a um serviço de cirurgia bariátrica. Ela relata que desistiu de tratamentos conservadores após tentar emagrecer, sem sucesso, por mais de 10 meses, utilizando métodos farmacológicos e restrição calórica. Também relata que sua vizinha foi submetida à cirurgia bariátrica com menos peso que ela e que perdeu 30 kg em 6 meses, com grande ganho de qualidade de vida. A paciente tem 1,62 m de altura e peso de 112 kg. É portadora de hipertensão arterial sistêmica, a qual é controlada com losartana 100 mg/dia, e diabetes melittus tipo 2, com uso de dapagliflozina 10 mg/dia e de metformina 1 g/dia. Além disso, faz uso de rosuvastatina 20 mg/dia para tratamento de dispilidemia e apresenta amenorreia. Ela também é tabagista e sedentária e revela que sofre de depressão.\n\nDiante dessa demanda da paciente, assinale a opção que apresenta a conduta médica adequada.","options":{"A":"Orientar a paciente sobre a necessidade de acompanhamento multidisciplinar e encorajá-la a continuar com a abordagem conservadora, pois a indicação da cirurgia acontece após tentar emagrecer, sob supervisão médica, por 5 meses em um período de 2 anos.","B":"Encaminhar a paciente ao serviço cirúrgico, o qual lhe esclarecerá sobre a necessidade de mudanças nos hábitos de vida e, considerando o impacto permanente da cirurgia, serão apresentadas e discutidas as técnicas cirúrgicas tanto com a paciente quanto com a família.","C":"Informar à paciente sobre os critérios de indicação de cirurgia bariátrica, como IMC > 40 Kg/m2 e presença de comorbidades, e encaminhá-la à equipe multidisciplinar para traçar plano de cuidados individualizado e estratégia conservadora com acompanhamento semanal.","D":"Esclarecer à paciente que as comorbidades são fatores de contraindicação à cirurgia e encaminhá-la à equipe multidisciplinar para estabilização e adequação de medicações, além de elaboração de um plano individual de cuidados que inclua antidepressivo na abordagem farmacológica."},"answer":"C","area":"Cirurgia Geral","assunto":"Cirurgia Bariátrica e Metabólica","topico":"Tratamento Cirúrgico da Obesidade","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Visão Geral"},{"id":"revalida-2023-2-102","number":102,"area":"Cirurgia Geral","source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","stem":"Um homem de 22 anos é atendido em hospital de médio porte após ter mergulhado em lagoa e ter batido a cabeça em uma pedra submersa. Ao chegar ao hospital, após ser trazido pela equipe de atendimento pré-hospitalar, encontra-se consciente, com colar cervical, imobilizado adequadamente em prancha rígida. Relata que apresenta sensibilidade diminuída (graduação sensorial 1) do primeiro ao terceiro dedos das mãos, mas não identifica toque leve ou estímulos dolorosos no quarto e no quinto dedos das mãos, no tronco, na pelve e nos membros inferiores. Realiza a extensão dos cotovelos (tríceps) apenas com os membros superiores apoiados sobre o leito, sem ação da gravidade (força muscular grau 2), e não consegue fletir os dedos das mãos ou mover o tronco, a pelve e ou os membros inferiores. Com base no quadro clínico desse paciente, ele apresenta uma","options":{"A":"fratura do arco anterior e posterior da primeira vértebra cervical (de Jefferson).","B":"fratura da sétima vértebra cervical e subluxação entre essa vértebra e a primeira vértebra torácica.","C":"fratura de processo transverso da terceira vértebra cervical com comprometimento de artéria vertebral.","D":"fratura transversa do elemento posterior da segunda vértebra cervical (corpo do Axis) em sua parte interarticular."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Politrauma Ortopédico","subtopico":"Trauma Raquimedular e Fraturas da Coluna Vertebral"},{"id":"revalida-2023-2-103","number":103,"area":"Nefrologia","source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","stem":"Uma adolescente de 15 anos é levada ao pronto-atendimento por seu pai, que refere ter encontrado sua filha desacordada ao lado de uma cartela de comprimidos de bromazepam vazia. Ele diz que os comprimidos, originalmente, pertenciam à avó, que sofre de insônia e reside no mesmo domicílio, e não sabe dizer quantos comprimidos a adolescente ingeriu ou há quanto tempo ocorreu a ingestão. Na avaliação inicial, a adolescente apresenta rebaixamento do nível de consciência, abrindo os olhos e murmurando palavras incompreensíveis quando submetida a estímulo doloroso. Suas vias aéreas estão pérvias e a respiração é regular, com saturação de oxigênio de 96% em ar ambiente. Diante do quadro dessa paciente, quais são as condutas clínicas indicadas?","options":{"A":"Dosar o nível sérico de benzodiazepínicos; administrar, imediatamente, o flumazenil.","B":"Realizar lavagem gástrica após intubação orotraqueal para proteção de vias aéreas; administrar carvão ativado.","C":"Iniciar lavagem gástrica; monitorar eletrocardiograma, eletrólitos, função renal e hepática; administrar flumazenil.","D":"Monitorar eletrocardiograma, eletrólitos, função renal e hepática; realizar hidratação para estimular a eliminação renal; manter oximetria de pulso contínuo."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Controle da água corporal total","topico":"Reposição volêmica"},{"id":"revalida-2023-2-105","number":105,"area":"Cirurgia Geral","source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","stem":"Um adolescente de 15 anos comparece à unidade básica de saúde. Ele relata lombalgia há 6 meses, com 3 episódios semanais. Nega trauma local e nega prática de atividades físicas, como musculação. Diariamente, carrega mochila nas costas no translado de casa para a escola, o qual dura 20 minutos. Na inspeção do paciente, ao ficar de costas, na posição ereta, foi observado que o ombro esquerdo é mais elevado do que o ombro direito. O teste de Adams (presença de gibosidade) deu positivo. A aferição do membro inferior direito é de 98 cm e do membro inferior esquerdo é de 98 cm. Considerando a história e o exame clínico apresentados, qual propedêutica complementar deve ser solicitada para comprovar a principal hipótese diagnóstica?","options":{"A":"Radiografia panorâmica da coluna.","B":"Escanometria de membros inferiores.","C":"Ultrassonografia de coluna lombossacra.","D":"Ressonância magnética da coluna lombar."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Trauma Músculo-Esquelético","subtopico":"Diagnóstico "},{"id":"revalida-2026-1-017","number":17,"area":"Otorrinolaringologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Uma criança de 6 anos, do sexo feminino, é levada ao Ambulatório de Pediatria pela mãe devido à queixa de reclamações na escola por falta de atenção e sonolência excessiva. Segundo a mãe, a criança apresenta respiração oral ruidosa que piora durante o sono, com roncos e episódios de apneia, acordando várias vezes durante a noite com a boca seca e pedindo água. A mãe nega febre, tosse ou secreção nasal, que ocorrem apenas quando a criança Eca gripada, o que é frequente. Nega prurido nasal ou espirros, assim como antecedentes familiares patológicos. Ao exame, a criança apresenta fácies congestas, com vedamento labial incompleto, respiração bucal ruidosa e olheiras. Otoscopia normal bilateralmente. Mucosas e cornetos nasais com leve hiperemia; cavidade oral com palato em ogiva; tonsilas palatinas com leve aumento e ausência de placas ou secreções. Ausculta pulmonar com roncos de transmissão. Qual o exame complementar confirmatório a ser solicitado?","options":{"A":"Teste de hipersensibilidade imediata.","B":"Radiografia de cavum.","C":"Nasofibroscopia flexível.","D":"Polissonografia."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Hipertrofia de Adenoide e Síndrome do Respirador Oral","topico":"Hipertrofia de Adenoide"},{"id":"revalida-2026-1-025","number":25,"area":"Otorrinolaringologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Manejo Homem de 45 anos dá entrada na Unidade de Pronto Atendimento com epistaxe anterior há cerca de 40 minutos. É hipertenso, fazendo uso irregular de fármaco anti-hipertensivo; nega trauma recente. Ao exame, apresenta sangramento visível no septo nasal anterior à esquerda, está hemodinamicamente estável e com vias aéreas pérvias. Após avaliação inicial e monitorização, a conduta mais adequada como primeira linha no manejo agudo desse paciente é realizar","options":{"A":"hiperextensão cervical e uso de corticoide tópico.","B":"tamponamento nasal posterior com sonda de Foley.","C":"compressão nasal anterior e uso de vasoconstritor tópico.","D":"ligadura cirúrgica da artéria esfenopalatina."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Epistaxe","topico":"Manejo"},{"id":"revalida-2026-1-038","number":38,"area":"Pediatria","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Síndrome Inflamatória Multissistêmica Menina, 8 anos, previamente hígida, é levada à Unidade de Pronto Atendimento com quadro de febre (39 a 40 °C) há 5 dias, associado à dor abdominal intensa, vômitos, exantema maculopapular em tronco e hiperemia conjuntival bilateral sem secreção. A mãe refere que a criança teve um quadro gripal leve há cerca de 4 semanas com teste de covid-19 positivo. Exame físico: prostrada; tempo de enchimento capilar de 4 segundos; pulsos Enos; FC 135 bpm; PA 75 x 45 mmHg (abaixo do percentil 5 para idade e estatura); SatO2 91% em ar ambiente. Ausculta cardíaca revela ritmo de galope. Palpação abdominal mostra descompressão brusca negativa, mas com dor importante à palpação profunda. Qual é a principal suspeita clínica?","options":{"A":"Doença de Kawasaki clássica.","B":"Pneumonia bacteriana secundária à covid-19.","C":"Apendicite aguda.","D":"Síndrome inflamatória multissistêmica pediátrica."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Reumatologia Pediátrica","topico":"Doença de Kawasaki","subtopico":"Síndrome Inflamatória Multissistêmica"},{"id":"revalida-2026-1-067","number":67,"area":"Infectologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Furúnculo e antraz Adolescente, 15 anos, é levado a atendimento devido a episódios repetidos de lesões dolorosas em áreas de atrito, nos últimos 6 meses, especialmente coxas e nádegas. Refere que as lesões começam como nódulos endurecidos, muito dolorosos, que evoluem para áreas avermelhadas e quentes, com saída de secreção purulenta após alguns dias. Relata episódios semelhantes neste período, alguns necessitando de drenagem. No episódio atual, relata febre (37,8 a 38,2 °C) há 2 dias, mal-estar e aumento progressivo da dor. Ao exame físico, apresenta uma lesão nodular eritematosa de 3 cm, quente, extremamente dolorosa à palpação, com ponto de flutuação evidente na região posterior da coxa. Há cicatrizes residuais de episódios anteriores. Pele adjacente quente e infiltrada. Qual o diagnóstico para esse adolescente?","options":{"A":"Celulite de repetição.","B":"Impetigo recorrente.","C":"Furunculose de repetição.","D":"Foliculite recorrente."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infecções bacterianas","topico":"Infecção de pele e partes moles (Piodermites)"},{"id":"revalida-2026-1-070","number":70,"area":"Medicina Preventiva","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Vetores Epidemiologia Transmissão O aquecimento global tem modificado a distribuição geográfica de vetores e a dinâmica de transmissão de doenças infecciosas. No Brasil, tem sido registrado um aumento de transmissão autóctone de dengue e Chikungunya em áreas de maior altitude e clima mais ameno no Sul do país. Diante deste cenário, qual alternativa melhor explica a influência do aumento da temperatura na competência vetorial do Aedes aegypti?","options":{"A":"O período de incubação extrínseco do vírus no mosquito é encurtado, tornando-se vetor infectante em tempo menor.","B":"Mutação genética é induzida no vírus, permitindo a transmissão por mosquitos de outras espécies, mais abundantes em clima frio.","C":"O ciclo de vida do mosquito é acelerado, preservando a sua capacidade de replicação viral no vetor.","D":"A sazonalidade das chuvas é modificada e provoca redução da densidade do vetor, preservando a sua competência para transmissão viral."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Epidemiologia","topico":"Aspectos Epidemiológicos das Doenças Transmissíveis","subtopico":"Modos de Transmissão das Doenças Transmissíveis"},{"id":"revalida-2026-1-072","number":72,"area":"Psiquiatria","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Introdução Mulher, 55 anos, funcionária de segurança, é levada à Unidade Básica de Saúde por sua Agente Comunitária de Saúde (ACS) devido a delírio persecutório. Segundo relatos da ACS, a paciente chegou a proferir uma clara ameaça de morte à vizinha, a quem atribuiria a realização de trabalhos espirituais contra ela. Enquanto aguardava ser chamada na recepção, a paciente começou a Ecar progressivamente agitada, falando sozinha, e tentou agredir outros usuários com um cabo de vassoura. Após tentativa de abordagem verbal e posterior restrição de espaço realizada pela equipe de enfermagem, ela ficou ainda mais agitada e passou a tentar agredir todos que se aproximavam. A sequência de procedimentos adequados para esse caso é","options":{"A":"administração de haloperidol intramuscular, seguida de nova intervenção verbal.","B":"administração de diazepam intramuscular, seguida de observação em consultório.","C":"contenção mecânica, seguida de administração de haloperidol intramuscular.","D":"contenção mecânica, seguida de observação em consultório."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Transtorno Psicóticos","topico":"Transtorno Delirante Persistente"},{"id":"revalida-2026-1-075","number":75,"area":"Neurologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"um paciente de 78 anos que esteve internado devido a episódio de acidente vascular encefálico isquêmico e recebeu alta hospitalar há 1 semana. O paciente está acamado e apresenta perda de peso e ingestão alimentar irregular. Na região sacral, há descoloração e eritema na pele íntegra, o qual permanece por mais de 15 minutos após o alívio da pressão no local. A Filha, cuidadora principal, está muito aflita e relata que no hospital não recebeu orientação de cuidado. Qual orientação a equipe deve priorizar para prevenir a progressão da lesão?","options":{"A":"Utilizar dispositivos do tipo argola ou roteiro com preenchimento hídrico.","B":"Manter o paciente em decúbito dorsal permanente com a cabeceira elevada.","C":"Estabelecer um rodízio de decúbito que não exceda o intervalo de 2 horas.","D":"Realizar massagem circular sobre a região do eritema com soluções de ácidos graxos essenciais."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Acidentes Vasculares Cerebrais (AVC)","topico":"Acidente Vascular Cerebral  Isquêmico"},{"id":"revalida-2026-1-083","number":83,"area":"Ginecologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"BIRADS 4 Mulher, 51 anos, comparece à consulta ginecológica na Unidade Básica de Saúde para apresentar mamografia realizada há 1 mês. Não apresenta queixas relacionadas à mama e não possui alterações no exame físico. Nega comorbidades e histórico familiar de doenças mamárias ou oncológicas. Mamografia bilateral. Mama esquerda: parênquima fibroglandular denso. Presença de calcificações pleomórficas finas, com distribuição segmentar, no quadrante ínferomedial. Mama direita: parênquima Ebroglandular denso. Ausência de achados significativos. Mamografia BI-RADS 4C. Considerando os achados mamográficos, qual é a conduta recomendada?","options":{"A":"Solicitar avaliação complementar com ressonância magnética.","B":"Manter seguimento conforme a rotina habitual de rastreamento.","C":"Repetir a mamografia bilateral em 6 meses para controle evolutivo.","D":"Encaminhar a paciente para serviço especializado em mastologia."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Mastologia","topico":"Rastreamento do câncer de mama","subtopico":"BIRADS"},{"id":"revalida-2026-1-086","number":86,"area":"Neurologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Quadro Clínico Diagnóstico Homem, 64 anos, professor universitário aposentado, com histórico de hipertensão arterial sistêmica malcontrolada há anos e ex-tabagista, é levado por sua Filha à Unidade Básica de Saúde, devido a queixas de declínio cognitivo, com início há cerca de 2 anos. Segundo o relato, o quadro teve início súbito durante episódio de pico hipertensivo, quando o paciente começou a apresentar dificuldades para planejar e executar atividades habituais, como organizar contas e seguir o uso correto de suas medicações (losartana e anlodipino). Desde então, ocorreu piora cognitiva em degraus, com períodos de estabilidade intercalados com novas perdas de desempenho. A Filha destaca também episódios de instabilidade postural e quedas frequentes no mesmo período. O paciente apresenta déficit de memória recente, com razoável preservação de linguagem e orientação temporal. Não há histórico familiar de demência. Ao exame físico, PA 170 x 95 mmHg, reflexos patelares exaltados bilateralmente, além de marcha com base alargada e insegura. O miniexame do estado mental é de 22/30, com destaque para prejuízo em funções executivas e atenção. A principal hipótese diagnóstica para esse caso é de demência","options":{"A":"vascular.","B":"frontotemporal.","C":"de corpúsculos de Lewy.","D":"na doença de Alzheimer."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Demências","topico":"Demência Vascular"},{"id":"revalida-2026-1-091","number":91,"area":"Cirurgia Geral","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Exame físico e Avaliação Funcional do Idoso Mulher, 73 anos, comparece à Unidade Básica de Saúde, acompanhada da Filha, para consulta de rotina. Relata tratar hipertensão arterial sistêmica, diabetes mellitus tipo 2 e hipotireoidismo, estando em uso regular de anlodipino, enalapril, hidroclorotiazida, gliclazida, metformina e levotiroxina. Teve queda da própria altura, com fratura de fêmur direito, relatando internação para correção cirúrgica há 1 ano. Quanto à atividade de vida diária, diz conseguir tomar banho sozinha, porém se queixa de não conseguir realizar a limpeza da casa desde a cirurgia ortopédica. A Filha informa que a mãe tem apresentado episódios de esquecimento há 2 meses. Ao exame: lúcida; deambula com auxílio de bengala; IMC 26 kg/m²; PA 160 x 90 mmHg; FC 88 bpm e FR 19 irpm. Considerando o índice de vulnerabilidade clínico-funcional (IVCF-20) para avaliação multidimensional da pessoa idosa, quais são os itens de pontuação para a estratificação do risco de declínio funcional dessa paciente?","options":{"A":"Polifarmácia, esquecimento e não conseguir limpar a casa.","B":"Idade, hipertensão mal controlada e usar bengala.","C":"Fratura de fêmur, internação e portar doenças crônicas.","D":"Cirurgia ortopédica, IMC e apresentar histórico de queda."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Avaliação Pré-Operatória","topico":"Risco Cirúrgico"},{"id":"revalida-2026-1-093","number":93,"area":"Pediatria","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Blues do Puerpério Puérpera, 21 anos, é acolhida Unidade Básica de Saúde, após o nascimento da Filha, há dez dias. Relata que pensa em entregar a Filha para a avó cuidar, uma vez que se sente “sugada” pela recém-nascida, e sente momentos de tristeza ao longo do dia, quando se questiona se deveria ter engravidado ou não, desejando interromper a amamentação, voltar a trabalhar e, principalmente, não estar com a Filha. Sente-se muito culpada por pensar dessa maneira e envergonhada por não conseguir ser uma “boa mãe”. Queixa-se também do sono, pois as noites maldormidas a deixam mais irritada. Está ainda mais preocupada, pois nunca se sentiu assim. Qual é a conduta mais adequada para esse caso?","options":{"A":"Encaminhar para apoio psicossocial.","B":"Prescrever o uso de fluoxetina.","C":"Encaminhar para tratamento no CAPS.","D":"Prescrever o uso de clonazepam."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Puericultura Geral","subtopico":"Orientações gerais de puericultura / Sinais de alerta"},{"id":"revalida-2026-1-095","number":95,"area":"Pediatria","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Um menino de 7 anos, previamente hígido, apresenta dor insidiosa no quadril direito há aproximadamente 3 meses, associada à claudicação progressiva. Não há história de trauma, febre ou outros sintomas sistêmicos. Ao exame físico, observa-se atitude antálgica em flexão do quadril, com limitação da abdução e da rotação interna. A radiografia simples do quadril evidencia discreto achatamento e irregularidade do núcleo epifisário da cabeça femoral direita. A principal hipótese diagnóstica é","options":{"A":"epifisiólise proximal do fêmur.","B":"artrite idiopática juvenil oligoarticular.","C":"sinovite transitória do quadril.","D":"necrose asséptica da cabeça do fêmur."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Reumatologia Pediátrica","topico":"AIJ - Artrite Idiopática Juvenil","subtopico":"Diagnóstico Diferencial"},{"id":"revalida-2026-1-097","number":97,"area":"Ginecologia","source":"Revalida INEP 2026.1","examId":"revalida-2026-1","examName":"Revalida INEP: 2026.1","stem":"Características Diagnóstico Mulher, 23 anos, vida sexual ativa, sem parceiro Exo, procura atendimento ginecológico com queixa de linfoadenomegalia inguinal dolorosa, com linfonodo à esquerda com supuração e Estulização por orifícios múltiplos. Relata que no início era uma pápula que evoluiu para uma ferida alguns dias antes de apresentar aumento do linfonodo e da dor na região inguinal. Considerando a situação clínica descrita, qual é o provável agente etiológico?","options":{"A":"Chlamydia trachomatis.","B":"Haemophilus ducreyi.","C":"Klebsiella granulomatis.","D":"Treponema pallidum."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infecções em ginecologia","topico":"Úlceras genitais","subtopico":"Úlceras infecciosas de causa sexualmente transmissível"},{"id":"revalida-2022-1-001","number":1,"area":"Oftalmologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um paciente com 25 anos de idade, soldador, procurou Unidade de Pronto Atendimento relatando que, durante seu ofício, retirou o protetor facial momentaneamente e foi atingido por \"(ash\" ocasionado pelo equipamento de solda no olho direito. O médico clínico socorrista evidenciou apenas eritema conjuntival. O paciente refere, nesse momento, irritabilidade e \"sensação de areia\" nos olhos, sem perda da acuidade visual. Nesse caso, a melhor medida a ser adotada pelo médico socorrista antes de encaminhar o paciente para avaliação especializada é","options":{"A":"curativo oclusivo e compressivo.","B":"oftalmoscopia e retirada de corpo estranho com pinça.","C":"aplicação de colírio contendo antimicrobianos e corticoesteroides.","D":"irrigação ocular com soro fisiológico a 0,9% em temperatura ambiente."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Traumatismos Oculares","topico":"Corpo Estranho Corneano e Conjuntival"},{"id":"revalida-2022-1-002","number":2,"area":"Ortopedia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Entorse do tornozelo Durante um jogo de basquete feminino, a estrela da equipe, com 19 anos de idade, após um salto para \"enterrar\" a bola, pisou de maneira inadequada no solo e caiu. Não tendo sido mais capaz de se levantar naquele momento, foi levada para o Pronto-Socorro, onde chegou deambulando, embora mancasse. A jogadora apresentava dor aos movimentos, edema e equimose no tornozelo esquerdo. Ao palpar o tornozelo, o médico não evidenciou nenhum ponto ósseo específico de dor. Diante desse quadro, considerando o preconizado em casos de entorse de tornozelo, a conduta adequada é","options":{"A":"pedir uma radiografia do tornozelo para avaliar a fratura.","B":"aplicar calor local e encaminhar a paciente para avaliação do ortopedista.","C":"iniciar fisioterapia motora precoce e solicitar o parecer de um ortopedista.","D":"imobilizar o membro afetado e medicar a paciente com anti-inflamatório."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Ortopedia Geral","topico":"Transtornos de Partes Moles"},{"id":"revalida-2022-1-004","number":4,"area":"Ginecologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Diretrizes do rastreamento mamográfico Segundo o Instituto Nacional do Câncer (INCA), o rastreamento do câncer de mama organizado por mamografia de rotina (em que se convida formalmente as mulheres na faixa etária alvo para os exames periódicos), além de garantir controle de qualidade, seguimento oportuno e monitoramento em todas as etapas do processo, apresenta melhores resultados e menores custos que o rastreamento oportunístico. Considerando as informações apresentadas, para qual faixa etária e e m que periodicidade, respectivamente, o INCA recomenda o rastreamento do câncer de mama organizado por mamografia de rotina?","options":{"A":"45 aos 69 anos de idade; anualmente.","B":"50 aos 79 anos de idade; anualmente.","C":"40 aos 69 anos de idade; a cada 2 anos.","D":"50 aos 69 anos de idade; a cada 2 anos."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Mastologia","topico":"Rastreamento do câncer de mama","subtopico":"Rastreamento mamográfico"},{"id":"revalida-2022-1-008","number":8,"area":"Infectologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma paciente com 26 anos de idade, gesta: 2, para: 2, aborto: 0, utilizando contraceptivo oral combinado regularmente, comparece à Unidade Básica de saúde para verificação do resultado de exame de citologia oncótica cérvico-vaginal realizado há 1 mês. Não há queixas ou alterações descritas no prontuário do atendimento anterior quando do exame ginecológico. No laudo, descreve-se a presença de lesão intraepitelial escamosa de baixo grau( LSIL). Em relação ao resultado do exame de citologia oncótica cérvico-vaginal da paciente, segundo o Instituto Nacional do Câncer/Ministério da Saúde, qual deve ser a conduta?","options":{"A":"Repetir a coleta para exame da citologia em 6 meses.","B":"Realizar nova coleta para exame da citologia em 1 ano.","C":"Solicitar pesquisa do tipo e da classe viral.","D":"Encaminhar para colposcopia e biópsia."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Vacinas","topico":"Calendário vacinal em adultos e idosos"},{"id":"revalida-2022-1-013","number":13,"area":"Ginecologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma mulher com 32 anos de idade comparece à consulta médica agendada na Unidade Básica de Saúde levando o resultado de exame citopatológico do colo uterino coletado há 1 mês. A paciente, muito nervosa, confessa que havia lido o resultado do exame e que pesquisou na internet sobre o tema. Ressaltou que segue corretamente às orientações do seu médico e que, aos 29 anos de idade, realizou o mesmo exame, com resultado normal. O resultado do exame citopatológico do colo uterino realizado no último mês apresentou amostra satisfatória, representatividade da junção escamo colunar, presença de células escamosas e glandulares e presença de ASCUS - (células escamosas atípicas de significado indeterminado). Considerando o caso apresentado, após explicar à paciente que há presença de um exame com alteração, o médico de família deve","options":{"A":"repetir o exame citopatológico do colo uterino no momento da consulta.","B":"solicitar novo exame citopatológico do colo uterino em 12 meses e, caso a alteração permaneça, avaliar indicação de cirurgia.","C":"encaminhar a paciente para o serviço especializado de Ginecologia para realização de um novo exame mais detalhado, a colposcopia.","D":"solicitar novo exame citopatológico do colo uterino em 6 meses e, caso a alteração permaneça, solicitar a realização de um exame mais detalhado, a colposcopia."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","subtopico":"Diretrizes para o rastreamento"},{"id":"revalida-2022-1-015","number":15,"area":"Obstetrícia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Obstetrícia Doenças associadas à gestação Síndromes Hipertensivas da Gestação Uma paciente chega à unidade de emergência com idade gestacional de 37 semanas e 6 dias, gesta: 2, para: 1, aborto: 0 (um parto cesariana anterior), com contrações uterinas presentes, colo não pérvio, pressão arterial de 160x110 mmHg, já com duas aferições intervaladas por 10 minutos. Para esse caso, a conduta correta é solicitar","options":{"A":"acesso venoso e decúbito lateral esquerdo, além de encaminhar a paciente para cesariana de urgência.","B":"decúbito lateral esquerdo e exames laboratoriais, além de reavaliar a pressão arterial da paciente e proceder a resolução da gestação.","C":"acesso venoso e exames laboratoriais, além de iniciar sulfato de magnésio e proceder a resolução da gestação.","D":"acesso venoso e exames laboratoriais, além de encaminhar a paciente para cirurgia devido a cesariana anterior."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Doenças associadas à gestação","topico":"Síndromes Hipertensivas da Gestação","subtopico":"Eclâmpsia"},{"id":"revalida-2022-1-018","number":18,"area":"Obstetrícia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Obstetrícia Herpes na gestação Uma gestante primigesta com 25 anos de idade e com idade gestacional de 20 semanas comparece à consulta no Centro de Saúde referindo uma lesão em vulva. Relata que, inicialmente, sentiu dor e coceira no local e que, pouco depois, apareceu a lesão, que ainda dói e arde. Nega episódios semelhantes anteriores. Ao exame ginecológico, apresenta lesão em fúrcula vaginal, hiperemiada, com vesículas agrupadas, algumas exulceradas. Considerando esse quadro clínico, assinale a opção que apresenta, respectivamente, a principal hipótese diagnóstica e a conduta correta a ser adotada.","options":{"A":"Sífilis (lesão secundária); deve ser solicitado VDRL e teste treponêmico com urgência para definir conduta.","B":"Sífilis (lesão primária); indicação de tratamento com penicilina benzatina para a mulher e o(s) parceiro(s).","C":"Herpes Genital; deve ser solicitada sorologia (IGG e IGM) e cultura de secreção da lesão e, após coleta, iniciar tratamento com aciclovir.","D":"Herpes Genital; indicação de tratamento com aciclovir e com 36 semanas de gestação deve ser prescrito aciclovir profilático, para diminuir o risco de lesões ativas no momento do parto."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Doenças associadas à gestação","topico":"Doenças infecciosas na gestação – HIV, sífilis, hepatites, herpes","subtopico":"Herpes na gestação "},{"id":"revalida-2022-1-022","number":22,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma médica é chamada para dar assistência ao recém-nascido de uma gestante com 35 anos e idade gestacional de 33 semanas, com rotura de membrana, superior há 18 horas. No que se refere a essa situação, assinale a opção correta.","options":{"A":"Caso o recém-nascido apresente boa vitalidade, o clampeamento imediato do cordão evita a hemorragia intracraniana e a enterocolite necrosante.","B":"Caso o recém-nascido comece a respirar ou chorar e esteja ativo, deve-se secá-lo rapidamente e envolver a região das fontanelas e do corpo em campo estéril aquecido para evitar a hipotermia; o neonato deve ser posicionado no abdome ou tórax materno.","C":"Caso o recém-nascido não apresente boa vitalidade, realizam-se o clampeamento imediato de cordão, a colocação de touca dupla e saco plástico, visando-se manter a temperatura axilar > 37,5 °C para proteção de lesão cerebral em paciente asfixiado.","D":"Caso o recém-nascido apresente boa vitalidade, após posicionar o pescoço, deve-se aspirar delicadamente a boca e depois as narinas com sonda traqueal número 6-8 conectada ao aspirador a vácuo, sob pressão máxima de 100 mmHg."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Neonatologia","topico":"Reanimação neonatal","subtopico":"Reanimação neonatal em menores de 34 semanas"},{"id":"revalida-2022-1-025","number":25,"area":"Obstetrícia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Obstetrícia Imunizaçao na gestação Uma paciente secundigesta, com 25 anos de idade, 28 semanas de amenorreia, vem à Unidade Básica de Saúde para receber as vacinas que viu em uma campanha na televisão. Em seu cartão de vacinas consta vacinação contra in(uenza e administração da dTpa há 2 anos, durante sua primeira gestação. Com relação à vacinação dessa paciente contra influenza e coqueluche, deve-se","options":{"A":"realizar a vacinação contra influenza em dose única imediata e administrar nova dose de dTpa.","B":"administrar nova dose de dTpa, não havendo necessidade de nova vacinação contra influenza.","C":"realizar vacinação contra influenza em 2 doses (imediata e após 30 dias) e administrar nova dose de dTpa.","D":"realizar vacinação contra influenza em dose única imediata, não havendo indicação de nova dose da dTpa."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Pré-natal","topico":"Assistência pré-natal","subtopico":"Imunizaçao na gestação "},{"id":"revalida-2022-1-028","number":28,"area":"Obstetrícia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma paciente de 32 anos de idade está grávida de seu segundo filho e faz pré-natal no centro de saúde. Solicitou um atendimento de urgência no dia de hoje, por queixa de dor lombar e mal-estar. No momento está com 29 semanas de idade gestacional. Tratou uma cistite há 2 semanas com cefalexina e, após isso, não fez nenhum exame de controle. O restante do pré-natal está normal. Refere, durante a consulta, que a dor lombar iniciou há 2 dias, que teve febre (não medida) e queda do estado geral. Nega sintomas gripais e refere boa movimentação fetal. Ao exame, apresenta-se em regular estado geral, corada, hidratada, febril (temperatura = 38 °C), com pulso de 100 batimentos por minuto (bpm) e pressão arterial de 100 x 60 mmHg. Apresenta, ainda, exame cardio-pulmonar sem anormalidade. Abdome sem sinais de irritação peritoneal, com altura uterina de 28 cm. Batimentos cardíacos fetais de 148 bpm, sem dinâmica uterina. Punho percussão de região lombar dolorosa à direita . Toque vaginal com colo grosso, medianizado e impérvio. Considerando o quadro clínico apresentado, faça o que se pede nos itens a seguir. a) Cite a principal hipótese diagnóstica. Justifique sua resposta. b) Descreva qual a conduta adequada. c) Cite três possíveis complicações referentes a esse caso clínico.","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Doenças associadas à gestação","topico":"Infecção Urinária e Bacteriúria Assintomática na gestação (ITU) "},{"id":"revalida-2022-1-031","number":31,"area":"Cirurgia Geral","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um homem com 22 anos de idade, atendido no Pronto-Socorro de hospital, apresentava um ferimento por projétil de arma de fogo no hemitórax direito. Ao exame físico, foram constatados: frequência respiratória de 24 incursões respiratórias por minuto, frequência cardíaca de 110 batimentos por minuto, preenchimento capilar maior que 2 segundos, pressão arterial de 80 x 40 mmHg, estase jugular bilateral, desvio da traqueia para a esquerda, murmúrio vesicular abolido e timpanismo aumentado no hemitórax direito. Com base nesses dados, a conduta adequada é realizar","options":{"A":"radiografia do tórax e toracocentese no segundo espaço intercostal direito.","B":"radiografia do tórax e drenagem pleural fechada no quarto espaço intercostal direito.","C":"toracocentese inicialmente e drenagem pleural fechada no quarto espaço intercostal direito.","D":"toracocentese inicialmente e drenagem pleural aberta no segundo espaço intercostal direito."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Trauma Torácico"},{"id":"revalida-2022-1-032","number":32,"area":"Cirurgia Geral","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um homem com 23 anos de idade, em atendimento no Pronto-Socorro de hospital de nível terciário, apresenta trauma abdominal contuso após acidente automobilístico, sem evidências de lesões em outros segmentos corpóreos. Ao exame físico, apresenta frequência cardíaca de 84 batimentos por minuto, preenchimento capilar menor que 2 segundos, pressão arterial de 115 x 65 mmHg. Durante o atendimento inicial foi utilizada sondagem vesical de demora que evidenciou hematúria maciça. A tomografia de abdome com contraste endovenoso mostrou uma lesão renal grau III, correspondendo a laceração cortical do parênquima renal maior que 1 cm, sem extravasamento urinário. Não foram evidenciadas outras lesões no abdome. Considerando essa história clínica, os dados do exame físico e da tomografia, a conduta correta é indicar","options":{"A":"arteriografia e embolização para coibir o sangramento.","B":"tratamento operatório em função da hematúria maciça.","C":"sonda vesical de três vias e irrigação com solução salina 0,9%.","D":"repouso até resolução da hematúria, hematócrito seriado e antibióticos."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","subtopico":"Traumatismo Urológico"},{"id":"revalida-2022-1-037","number":37,"area":"Nefrologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma paciente com 35 anos de idade vem apresentando dor em região lombar direita, associada a náuseas e vômitos de início súbito há 4 horas. Nesse período, nega febre e refere vários episódios semelhantes anteriores. Ao exame físico, apresenta apenas sinal de Giordano positivo à direita. Realizou tomografia de abdome e pelve que mostrou cálculo de 1,2 cm, localizado em junção ureteropiélica direita e de densidade de 1.500 UH. Resultado do exame de Elementos Anormais e Sedimentos (EAS) na urina mostrou apenas hematúria microscópica discreta. Em relação ao cálculo, entre as condutas a seguir, a mais indicada é","options":{"A":"ureterorrenoscopia.","B":"pielolitotomia cirúrgica.","C":"litotripsia extracorpórea.","D":"terapia expulsora do cálculo com hidratação e alfa- bloqueadores."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Nefrolitíase ","topico":"Tratamento Intervencionista"},{"id":"revalida-2022-1-042","number":42,"area":"Cirurgia Geral","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma paciente com 33 anos de idade foi internada para procedimento cirúrgico de ressecção segmentar da mama direita, para retirada de tumor mamário local com margem de ressecção. Na chegada ao hospital fez sua identificação na área de internação, tendo sido colocada pulseira de identificação com anotação de alergia a dipirona. Na chegada do cirurgião ao hospital, o mesmo foi rapidamente ao quarto para o preenchimento de termo de consentimento da paciente. O anestesista já estava lhe aguardando no centro cirúrgico, tendo sido solicitado o encaminhamento da paciente para a sala operatória. O maqueiro entrou no quarto, juntamente com a enfermeira do andar, que realizou nova identificação da paciente e colocou- a na maca para transporte. Ao chegar ao centro cirúrgico ocorreu mais uma checagem relativa à identificação da paciente pela enfermeira chefe do centro cirúrgico, tendo encaminhado a paciente para a sua respectiva sala operatória. Após a anestesia geral foi iniciado pelo cirurgião o procedimento operatório, com sinalização ao final da cirurgia da falta de fio de sutura adequado. Foi constatado pela circulante de sala que o fio solicitado encontrava-se em falta no hospital, tendo como solução a utilização de outra alternativa disponível, que levou a resultado estético não satisfatório. Diante dessa situação, identifique e descreva, de acordo com as etapas preventivas preconizadas para a segurança do paciente pelo Programa Nacional de Segurança do Paciente, estabelecido pela Portaria n. 529/2013, do Ministério da Saúde, as ações preventivas que foram realizadas e aquelas que deveriam ter sido feitas no caso apresentado.","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Temas Gerais em Cirurgia","topico":"Segurança do Paciente"},{"id":"revalida-2022-1-043","number":43,"area":"Infectologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma mulher com 51 anos de idade, em tratamento para osteoporose com bifosfonato, comparece ao ambulatório de infectologia de um hospital escola para receber o resultado da investigação diagnóstica de quadro de lesão crônica oro- cérvico-facial à direita. Segundo a paciente, a lesão iniciou-se há cerca de 18 meses como um endurecimento in(amatório logo abaixo da mandíbula, bem ao nível de seu ângulo; ao longo de alguns dias, a lesão tornou-se um nódulo endurecido que, posteriormente, se ulcerou, dando saída a secreção purulenta contendo granulações amareladas por 2 tratos fistulosos. Conta que procurou assistência médica, tendo realizado tratamento antibiótico por algumas vezes, sempre por 7 a 14 dias, com melhora inicial do quadro, mas retorno da drenagem de material nas semanas seguintes. Acrescenta que, há 4 semanas, foi submetida a procedimento de biópsia local, tendo retornado ao ambulatório para saber o resultado da investigação diagnóstica. O laudo histopatológico revelou a presença de granulações contendo material in(amatório linfo- histiocitário associado a camadas densas de neutrófilos, no interior das quais são observadas massas de bactérias gram- positivas com filamentos ramificados, além de material sugestivo de depósitos de fosfato de cálcio. As culturas do material drenado isolaram, além de Actinomyces israelli, Eikenella corrodens e espécies de Staphylococcus. Ao exame físico, a paciente apresenta 2 elementos molares da arcada dentária inferior, bem adjacentes à lesão cérvico-facial, em péssimo estado de conservação, com processo inflamatório inequívoco. Nesse caso, o fármaco adequado, de uso prolongado, para a conduta terapêutica antimicrobiana é","options":{"A":"oxacilina.","B":"cefalexina.","C":"clindamicina","D":"levofloxacina."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infecções bacterianas","topico":"Infecção de pele e partes moles (Piodermites)"},{"id":"revalida-2022-1-045","number":45,"area":"Cardiologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um homem com 64 anos de idade chega ao serviço de emergência, conduzido pelos familiares, por confusão mental e sonolência. O paciente tem história de hipertensão arterial sistêmica com difícil controle. Ao exame, apresenta edema de papila ao fundo de olho, pressão arterial (PA) de 220 x 130 mmHg, presença de 4ª bulha na ausculta cardíaca. O restante do exame físico não apresenta alterações. A tomografia de crânio sem contraste não evidenciou sinais de isquemia cerebral. O tratamento de primeira escolha a ser proposto para esse paciente é iniciar","options":{"A":"clonidina, via oral, com o objetivo de reduzir a PA em até 50% em 24 horas ou para uma PA na faixa de 140x90- 85 mmHg.","B":"nitroprussiato endovenoso com o objetivo de reduzir a PA em até 25% em 2 horas ou para uma PA na faixa de 160 x 100-110 mmHg.","C":"nitroglicerina endovenosa com o objetivo de reduzir a PA em até 25% em 2 horas ou para uma PA na faixa de 160 x 100-110 mmHg.","D":"captopril, via sublingual, com o objetivo de reduzir a PA em 50% em 8 horas ou para uma PA na faixa de 140x90- 85 mmHg."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Hipertensão arterial complicada"},{"id":"revalida-2022-1-047","number":47,"area":"Pneumologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma paciente com 22 anos de idade dá entrada na unidade de emergência de hospital de média complexidade com quadro de asma descompensada. A paciente, que se apresenta taquicárdica (frequência cardíaca: 110 batimentos por minuto), taquipneica (frequência respiratória: 28 incursões respiratórias por minuto) e febril (38,3 °C), relata descompensação do quadro respiratório há 2 dias, tendo utilizado medicação de resgate (beta 2 agonista adrenérgico inalatório) por diversas vezes ao longo desse período, sem obter melhora. Diagnosticada com asma ainda na infância, ela conta que sua doença vem sendo classificada como asma moderada persistente, estando em uso regular de beta 2 agonista de longa duração (salmoterol) e corticoide inalatório (budesonida) em baixa dose, além da medicação de resgate. Ao exame físico, nota-se também leve cianose e sibilância inspiratória e expiratória; a hemodinâmica encontra-se estável bem como o nível de consciência. A paciente é submetida a administração de nebulização com beta 2 agonista adrenérgico inalatório e anticolinérgico de ação rápida (brometo de ipratrópio). A despeito da oxigenioterapia sob máscara nasal com reservatório, repetição da nebulização e da administração de metilprednisolona intravenosa, a paciente continua com algum grau de desconforto respiratório. Exames laboratoriais indicam a presença de possível processo infeccioso bacteriano (leucocitose com leve desvio à esquerda e aumento da proteína C reativa [PCR]), confirmado na radiografia de tórax, que indica padrão de condensação segmentar no lobo inferior direito. A gasometria arterial revelou o seguinte padrão: pH: 7,44 (valor de referência [VR]: 7,35-7,45); PaO₂: 65 (VR para idade: 95); PaCO₂: 44 (VR: 35-45); HCO₃⁻: 22 (VR: 24 +/- 2); SaO2: 91% (VR > 94%). Completada essa avaliação inicial, o médico opta por indicar a realização de intubação orotraqueal preventiva. A principal razão para a tomada dessa decisão","options":{"A":"foi o nível reduzido da PaO₂ à gasometria arterial.","B":"foi o nível normal da PaCO₂ à gasometria arterial.","C":"foram as evidências de pneumonia à radiografia de tórax, hemograma e PCR.","D":"foi a presença de sibilância inspiratória e expiratória associada à taquipneia."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Asma","topico":"Exacerbação de asma"},{"id":"revalida-2022-1-050","number":50,"area":"Hematologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Hematologia Quadro clínico da anemia falciforme Uma jovem com 14 anos de idade procura atendimento em Unidade Básica de Saúde (UBS) devido a crises recorrentes de lombalgia há, pelo menos, 4 anos. Relata que a dor é intensa, de início agudo, sem fator desencadeante que tenha identificado e que já havia precisado ser levada a pronto atendimento em algumas dessas crises para administração de analgésicos endovenosos. Conta que, em algumas dessas ocasiões, realizou exames laboratoriais, informando que apenas era detectada a presença de anemia. Acrescenta que, no último atendimento, também foi realizada uma radiografia da coluna lombar, que evidenciou a presença de vértebras em \"H\", tendo sido orientada a procurar o médico da UBS para prosseguimento de investigação. Diante desse histórico, o médico da UBS deve considerar a hipótese de","options":{"A":"hiperparatireoidismo e solicitar dosagem de paratormônio.","B":"anemia falciforme e solicitar eletroforese de hemoglobina.","C":"fraturas vertebrais secundárias e solicitar tomografia computadorizada.","D":"espondilite anquilosante e solicitar ressonância magnética de sacroilíacas."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Hemoglobinopatias","topico":"Anemia falciforme"},{"id":"revalida-2022-1-061","number":61,"area":"Pneumologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma mulher com 54 anos de idade, tabagista, cujo consumo é de 30 maços de cigarro por ano, comparece à consulta por dispneia e tosse que, segundo relata, se iniciaram há aproximadamente 1 ano. A paciente traz uma espirometria com uma razão entre o volume expiratório forçado no primeiro segundo e a capacidade vital forçada de 0.7 e um volume expiratório forçado no primeiro segundo de 80% do predito, sem resposta ao broncodilatador. O exame foi realizado com técnica correta. Considerando os dados apresentados, é correto afirmar que","options":{"A":"a falta de resposta ao broncodilatador sugere o diagnóstico de asma nessa paciente.","B":"os resultados da espirometria estabelecem o diagnóstico de doença pulmonar obstrutiva crônica nessa paciente.","C":"a espirometria precisa ser repetida para se confirmar o diagnóstico de doença pulmonar obstrutiva crônica nessa paciente.","D":"os valores do volume expiratório forçado no primeiro segundo afastam o diagnóstico de doença pulmonar obstrutiva crônica nessa paciente."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Doença Pulmonar Obstrutiva Crônica (DPOC)","topico":"Espirometria"},{"id":"revalida-2022-1-069","number":69,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um escolar do sexo masculino, residente em área rural, é encaminhado para um hospital de referência para investigação de quadro de febre irregular e prolongada, palidez, hepatoesplenomegalia e emagrecimento, insidiosos e progressivos, associados ao comprometimento do estado geral. Esteve internado em sua cidade de origem por 24 horas após apresentar epistaxe de grande intensidade e gengivorragia. Ao exame admissional, observam-se prostração, petéquias disseminadas em tronco e edema de membros inferiores. Em sua cidade de origem, foram realizados os exames inespecíficos, que demostraram anemia, leucopenia e plaquetopenia. Informa que o pai teve quadro semelhante há alguns meses. Entre os exames a serem realizados para se estabelecer o diagnóstico, é correto afirmar que","options":{"A":"o exame sorológico por imunofluorescência indireta é o mais vantajoso no que se refere a custo e efetividade, sendo considerados positivos os títulos a partir da diluição 1:80.","B":"a punção aspirativa esplénica é o método que oferece maior sensibilidade e menor risco, sendo o mais utilizado para a técnica de visualização direta do parasita.","C":"a reação em cadeia da polimerase (PCR), técnica molecular, é de baixa sensibilidade quando comparada a técnicas por visualização direta.","D":"a dosagem de proteínas, na qual há forte inversão da relação albumina/globulina, é exame de alta sensibilidade e especificidade."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infectologia Pediátrica","topico":"Febre sem sinais localizatórios (FSSL)","subtopico":"Abordagem Diagnóstica"},{"id":"revalida-2022-1-075","number":75,"area":"Endocrinologia","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Um homem com 65 anos de idade, diabético, chega com familiares para consulta no serviço de pronto atendimento devido a confusão mental. Os familiares informam que ele é diabético há 20 anos e faz acompanhamento com o endocrinologista, em uso de insulina há 2 meses (não sabem a dose, mas que faz uso 2 vezes ao dia), além de acompanhamento com o nefrologista há 1 mês, por uma alteração renal que não sabem especificar qual é. Relatam que, no dia anterior, o paciente havia começado a realizar caminhadas para tentar melhor controle do diabetes e que ele vem reduzindo sua quantidade de alimentos com essa mesma intenção. Contam que hoje pela manhã, começou a queixar-se de suor frio e tontura e que, em poucos minutos, tornou-se confuso, apresentando dificuldade para articular as palavras. Ao exame físico apresenta-se normal, sem sinais focais, mas confuso, sem conseguir manter uma conversa ou contato visual. Apresenta pressão arterial de 130 x 90 mmHg e frequência cardíaca de 110 batimentos por minuto, com tremores de extremidades. Considerando que, na abordagem inicial do paciente, foram realizadas monitorização, suplementação de oxigênio e punção de acesso venoso periférico, faça o que se pede nos itens a seguir. a) Cite a principal hipótese diagnóstica a ser considerada. Justifique sua resposta. b) Indique o exame complementar a ser solicitado imediatamente nesse caso. c) Descreva a conduta medicamentosa imediata.","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Diabetes ","topico":"Complicações agudas"},{"id":"revalida-2022-1-082","number":82,"area":"Medicina Preventiva","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Medicina Preventiva Bases legais de Saúde do Trabalhador Doenças relacionadas ao trabalho Uma mulher, moradora de cidade com 600.000 habitantes, procurou a Unidade Básica de Saúde de referência para se consultar com o médico da Estratégia de Saúde da Família por dor no braço, antebraço e punho direitos. Durante a anamnese, o médico detectou que a paciente apresentava esses sintomas há 6 meses com piora ao longo do tempo, mas que não a impediam de trabalhar com digitação de textos em uma empresa de computação. Ela relatou que, durante a pandemia da COVID-19, muitas digitadoras haviam sido demitidas e que aquelas que tinham permanecido estavam trabalhando sem pausas para descanso, frequentemente trabalhando além do horário regular, sem remuneração adicional, e que muitas também apresentavam queixas similares às dela. Ao exame físico, a única alteração observada foi dor à palpação do antebraço e braço direitos. Considerando essa situação, faça o que se pede nos itens a seguir. a) Cite a principal hipótese diagnóstica para o caso apresentado. Justifique sua resposta. b) Descreva o plano (propedêutico, terapêutico, educativo e de seguimento) adequado ao caso. c) Liste dois problemas biopsicossociais evidenciados no relato da paciente.","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Saúde do Trabalhador","topico":"Doenças relacionadas ao trabalho","subtopico":"Doenças osteomusculares relacionadas ao trabalho (DORT) / Lesão por esforços repetitivos (LER)"},{"id":"revalida-2022-1-088","number":88,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"uma adolescente com 13 anos de idade, acompanhada da mãe, refere, em consulta, ausência de menstruação. A genitora mostra-se ansiosa, pois relata acreditar que o desenvolvimento corporal da filha está atrasado em relação às amigas da mesma idade. Ao exame físico, a adolescente apresenta altura e peso compatíveis com percentil 60 do gráfico de crescimento da Organização Mundial da Saúde. Observa-se aumento das mamas e aréola, sem separação dos contornos (M3 na classificação de Tanner), assim como presença de pelos pigmentados, longos e enrolados, atingindo a sínfise púbica (P3 na classificação de Tanner). Nesse caso, a conduta adequada é","options":{"A":"solicitar dosagens hormonais e fazer o encaminhamento da paciente para centro de referência.","B":"pedir avaliação ultrassonográfica da presença e tamanho de útero e ovários da paciente.","C":"solicitar teste de progesterona via oral da paciente para estímulo endometrial.","D":"orientar e esclarecer a paciente sobre a normalidade do desenvolvimento."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Puberdade","subtopico":"Distúrbios Puberais"},{"id":"revalida-2022-1-091","number":91,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma menina com 8 anos de idade apresenta-se, acompanhada da mãe, em consulta ambulatorial com história de chiado no peito quase que diariamente, associado a dispneia aos esforços moderados e tosse noturna 5 vezes por semana, estando em tratamento contínuo com 1 pu de 250 ucg de beclometasona 1 vez ao dia, sem sinal de melhora. Apresenta exacerbações frequentes, com limitação das atividades nessas ocasiões, sendo necessário o uso de beta 2 agonista de curta duração e, às vezes, de corticoide oral. Ausculta respiratória sem alterações, frequência respiratória de 20 incursões respiratórias por minuto e saturometria de 96%. Diante desse caso, a classificação correta da doença da criança e a conduta adequada para o tratamento a longo prazo são, respectivamente,","options":{"A":"asma intermitente; tratar os episódios de exacerbação com inalação de beta 2 agonista de curta duração.","B":"asma persistente moderada não controlada; fazer uso de corticoide inalatório oral em dose moderada.","C":"asma persistente leve parcialmente controlada; utilizar corticoide inalatório oral de baixa dosagem.","D":"asma persistente grave parcialmente controlada; iniciar corticoide inalatório oral em dosagem alta."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Pneumologia Pediátrica","topico":"Asma ","subtopico":"Classificação do controle clínico da asma"},{"id":"revalida-2022-1-092","number":92,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"escolar com 4 anos de idade, acompanhado dos pais, dá entrada na emergência com quadro de febre, cefaleia e irritabilidade que se iniciou há 2 dias. A mãe relata que, hoje pela manhã, a criança apresentou erupções vermelhas na pele e que não percebeu outros sintomas antes do início do aparecimento desse quadro, porém, conta que o pai da criança estava com sintomas de síndrome gripal 2 semanas antes do adoecimento do filho. Ao exame físico, a criança apresenta estado geral comprometido, mucosas hipocoradas +/4+ e escleróticas anictéricas. Apresenta, ainda, olhos com conjuntivas hiperemiadas; pescoço com linfoadenomegalia cervical; tórax com diminuição da expansibilidade e tiragem subcostal presente; abdome plano, sem visceromegalias; pele com presença de erupções exantematosas. Frequência cardíaca = 168 batimentos por minuto, frequência respiratória = 39 incursões respiratórias por minuto e temperatura axilar = 39,1 °C. Os resultados dos exames laboratoriais iniciais da criança são apresentados no quadro a seguir. Após análise do quadro clínico e dos resultados laboratoriais, a principal hipótese diagnóstica é","options":{"A":"dengue grave com choque.","B":"síndrome do choque tóxico estafilocócico.","C":"meningite meningocócica na forma séptica.","D":"síndrome inflamatória multissistêmica pediátrica."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Reumatologia Pediátrica","topico":"Doença de Kawasaki","subtopico":"Síndrome Inflamatória Multissistêmica"},{"id":"revalida-2022-1-103","number":103,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Transposição de grandes artérias TGA Um recém-nascido a termo com 6 horas de vida encontra-se internado na maternidade, evoluindo com cianose progressiva. É filho de mãe diabética, nasceu com 4.200 Kg, obteve apgar7e8. Ao exame, apresenta regular estado geral e cianose 3+/4+. A saturometria foi de 50% em ar ambiente. Os pulsos estão normopalpáveis, simétricos. Apresenta ainda sopro sistólico suave +/6+ em borda esternal esquerda alta. Foi realizado ecocardiograma, que apresentou transposição simples das grandes artérias (TGA) e comunicação interatrial ampla. Nessa situação, a conduta imediata é","options":{"A":"realizar atriosseptostomia por balão.","B":"iniciar a administração de prostaglandina.","C":"encaminhar o paciente para cirurgia corretiva.","D":"ventilar o paciente com uma FiO2 entre 80 a 100%."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Cardiologia Pediátrica","topico":"Cardiopediatria e Cardiopatias congênitas","subtopico":"Cardiopatias congênitas"},{"id":"revalida-2022-1-105","number":105,"area":"Pediatria","source":"Revalida INEP 2022.1","examId":"revalida-2022-1","examName":"Revalida INEP: 2022.1","stem":"Uma escolar com 7 anos de idade é atendida em Unidade de Pronto Atendimento. A mãe relata que, há 1 dia, está com inchaço nos olhos e tem urinado pouco, apresentando urina escura. Relata também que, há 15 dias, a menina queixou-se de dor na garganta, dificuldade para engolir os alimentos e apresentou febre alta por 4 dias, manejada com medicação sintomática. No momento, a escolar apresenta cefaleia. Ao exame físico, verificam-se regular estado geral, edema periorbital discreto e hipertensão estágio 1. Considerando o caso clínico descrito, responda às questões a seguir. a) Qual é a principal hipótese diagnóstica? Justifique sua resposta. b) Quais exames laboratoriais podem estar alterados nesse caso? c) Quais as orientações a serem feitas e que medicamentos devem ser usados para essa escolar? d) Qual é a evolução esperada desse quadro para casos não complicados?","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Nefrologia Pediátrica ","topico":"Infecção de Trato Urinário (ITU)","subtopico":"Diagnóstico laboratorial"},{"id":"revalida-2025-1-006","number":6,"area":"Infectologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Falsos conceitos sobre vacinas Durante uma roda de conversa em uma sala de espera com mães que aguardavam a consulta de seus filhos com um médico de família e comunidade, uma enfermeira da equipe de saúde da família propôs a discussão do tema da hesitação vacinal. Durante o diálogo, uma das participantes afirmou que “a culpa de tudo isso é da Internet”. Considerando essa situação, assinale a alternativa correta, acerca dos argumentos a serem utilizados pela enfermeira nessa conversa com a comunidade.","options":{"A":"Internet veicula dúvidas quanto à real eficácia/eficiência e segurança das vacinas, o que abala a confiança da população nos imunobiológicos; ademais, o algoritmo das redes sociais associa temas antivacinação a outros temas de natureza moral, fazendo exposição seletiva.","B":"A hesitação vacinal ocorre nos extratos sociais de menor renda, que são contrárias à medicalização da saúde e acreditam que hábitos de vida saudáveis protegem contra doenças e garantem saúde, dispensando a necessidade de vacinação.","C":"O paradoxo epidemiológico de que algumas doenças imunopreveníveis hoje são raras, associado à complexidade do calendário vacinal, criou a política de redução temporária do uso de algumas vacinas em determinado ano para aumentar o engajamento da população no ano seguinte.","D":"A circulação de informações falsas (fake news), impulsionada pela internet, causa pouco impacto nas escolhas da população de menor poder aquisitivo, que tende a ter mais confiança na vacinação e menor acesso às redes sociais."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Vacinas","topico":"Calendário vacinal em adultos e idosos"},{"id":"revalida-2025-1-014","number":14,"area":"Otorrinolaringologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Menino de 6 anos é levado ao pronto-socorro pediátrico por sua mãe, que relata que a criança introduziu um objeto metálico pequeno no nariz enquanto brincava. O paciente apresenta obstrução nasal à direita, sem outros sintomas significativos. Radiografia em mentonaso dos seios da face revela uma imagem radiopaca circular com duplo contorno em fossa nasal direita. Nesse caso, qual é a conduta médica adequada?","options":{"A":"Alta médica, com encaminhamento para consulta com otorrinolaringologista.","B":"Transferência para centro de referência, para nasofibroscopia imediata.","C":"Internação no pronto-socorro, para lavagem e aspiração nasal.","D":"Internação hospitalar, para realização de rinoscopia eletiva."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Corpo Estranho Nasal"},{"id":"revalida-2025-1-022","number":22,"area":"Infectologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Mastite lactacional Mastite Multípara de 43 anos, lactante no fio mês de amamentação, procura atendimento afirmando área de hiperemia e dor no quadrante superior-lateral de mama esquerda, há 5 dias. Relata que, inicialmente, a área afetada era próxima à aréola e que depois foi se estendendo para a região axilar homolateral. Verifica-se ponto de flutuação e adenopatia dolorosa na axila esquerda. Paciente febril no momento do atendimento. Diante desse quadro, deve-se realizar","options":{"A":"drenagem cirúrgica sobre o ponto de flutuação, com prosseguimento de amamentação em ambas as mamas.","B":"drenagem com agulha fina guiada por ultrassonografia, com prosseguimento de amamentação pela mama contralateral.","C":"antibioticoterapia durante 7 dias, com lactação mantida, desde que o leite produzido pela mama afetada seja fervido antes de oferecê-lo.","D":"mamografia para descartar carcinoma inflamatório de mama, seguida de punção esvaziadora e de suspensão de amamentação até o resultado do anatomopatológico."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Infecções bacterianas","topico":"Infecção de pele e partes moles (Piodermites)"},{"id":"revalida-2025-1-061","number":61,"area":"Cirurgia Geral","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Homem de 45 anos, trabalhador da construção civil, comparece a uma unidade básica de saúde (UBS) devido à dor lombar iniciada há um mês, com piora progressiva, irradiada para o membro inferior direito, com maior intensidade ao final do expediente de trabalho, especialmente após carregar materiais pesados. Nega histórico de trauma, febre, perda de peso ou outros sintomas sistêmicos. Ao exame físico, há dor à palpação de musculatura paravertebral bilateral na região lombar, sem alterações neurológicas. Não há restrição de movimentos e a flexão está preservada. O exame de força e sensibilidade nos membros inferiores está normal, e os reflexos patelar e aquileu estão preservados. Lasègue negativo bilateralmente. Quais são as condutas adequadas a serem adotadas nesse caso?","options":{"A":"Solicitar ressonância magnética da coluna lombar, devido à irradiação da dor para membro inferior; prescrever antiinflamatório não esteroide associado a paracetamol.","B":"Solicitar radiografia de coluna lombar, devido à duração e à irradiação da dor; prescrever corticoide sistêmico associado a paracetamol; encaminhar o paciente à fisioterapia.","C":"Não solicitar exames complementares, devido à duração da dor e reflexos preservados; prescrever corticoide sistêmico associado a relaxante muscular; orientar repouso por 5 dias.","D":"Não solicitar exames complementares, devido à ausência de sinais de alerta; orientar a prática de exercício físico; prescrever anti-inflamatório não esteroide associado a relaxante muscular."},"answer":"D","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":"Trauma Músculo-Esquelético","subtopico":"Diagnóstico "},{"id":"revalida-2025-1-066","number":66,"area":"Medicina Preventiva","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Políticas de Saúde para Populações Específicas Princípios da Medicina de Família e Comunidade Um médico de família e comunidade, atuante numa equipe fluvial, atende a uma população ribeirinha e a uma população indígena, ambas na região amazônica. Ele reconhece que essas duas populações vivem em regiões remotas. No entanto, é notável que elas apresentam diferenças culturais e de modos de vida. A partir dessas informações, assinale a alternativa que apresenta a estratégia adequada a ser adotada pelo médico e por sua equipe no cuidado à saúde das populações mencionadas.","options":{"A":"Utilização de profissionais de saúde nativos ou locais sem a necessidade de capacitação específica focada no paradigma biomédico, uma vez que eles já conhecem profundamente a cultura, as tradições e os hábitos dessas populações.","B":"Atendimento à população ribeirinha centrado em soluções biomédicas e tecnológicas, utilizando conhecimentos da medicina ocidental, enquanto o atendimento à população indígena deve ser pautado por suas próprias práticas de cuidado e cura.","C":"Incentivo e valorização das práticas de cuidado tradicionais, promoção do uso racional de medicamentos básicos pela população indígena e estímulo à participação local e à integração do saber acadêmico e do senso comum da comunidade ribeirinha.","D":"Organização dos atendimentos das populações de forma padronizada, a partir da identificação das prioridades em saúde, considerando que as comunidades compartilham realidades geográficas e desafios semelhantes em relação ao acesso a cuidados médicos."},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Medicina de Família e Comunidade","topico":"Abordagem Comunitária "},{"id":"revalida-2025-1-067","number":67,"area":"Pediatria","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Menina de 14 anos vai à consulta na unidade básica de saúde (UBS), acompanhada de sua mãe, relatando preocupação, pois todas as suas amigas da mesma faixa etária já menstruaram, exceto ela. A paciente apresenta as mamas desenvolvidas e alguns pelos pubianos e, durante a consulta, apresenta muitas dúvidas em relação à menstruação. Nesse caso, após orientar a menina sobre ciclo menstrual e sobre métodos contraceptivos, a conduta adequada é","options":{"A":"solicitar exames complementares para investigação de amenorreia.","B":"orientar a mãe e a filha a aguardarem a menstruação até os 16 anos.","C":"indicar teste de progesterona oral para confirmar amenorreia primária.","D":"solicitar ultrassonografia e dosagens hormonais para investigação de amenorreia."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Puberdade","subtopico":"Distúrbios Puberais"},{"id":"revalida-2025-1-068","number":68,"area":"Pediatria","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Manutenção da amamentação Dieta Materna no período da amamentação Retorno da mulher ao trabalho Lactante previamente hígida comparece à consulta de puericultura com seu filho de 4 meses. Ela refere que voltará a trabalhar em 15 dias, por isso tem dúvidas quanto à oferta do leite materno. Considerando essa situação, assinale a alternativa que apresenta a orientação correta quanto aos cuidados adequados com a ordenha e o leite materno ordenhado.","options":{"A":"Para o descongelamento do leite materno, pode-se realizar a fervura ou o aquecimento em micro-ondas.","B":"Para a coleta de leite materno, pode-se realizar ordenha manual após higienização das mamas com álcool 70%.","C":"Para a conservação do leite materno, pode-se mantê-lo em congelador por até 15 dias a partir da primeira retirada.","D":"Para o favorecimento da continuidade do aleitamento materno, pode-se oferecer em mamadeira o leite ordenhado"},"answer":"C","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Puericultura ","topico":"Amamentação/ Aleitamento Materno","subtopico":"Técnicas de amamentação"},{"id":"revalida-2025-1-071","number":71,"area":"Medicina Preventiva","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Promoção à Saúde x Prevenção de Doenças Enchentes, secas, ondas de calor, tempestades tropicais, incêndios florestais e aumento do nível do mar estão diretamente relacionados à escalada dos determinantes sociais da saúde. Esses fatores podem levar ao aumento de doenças cardiovasculares, entre outras. Considerando a interferência desses fatores, assinale a alternativa correta com relação às ações de promoção da saúde.","options":{"A":"A exposição à poluição do ar pode acarretar no aumento do risco para hipertensão, diabetes e dermatite atópica, portanto, indica-se fechar as janelas da residência nos horários de maior fluxo de carros a fim de reduzir a exposição aos poluentes.","B":"As plantações de milho para a produção de biocombustível configuram uma importante tendência no país uma vez que aumentam a oferta de empregos na economia verde e melhoram as condições de vida de pequenos e médios produtores rurais.","C":"A elevação da pressão arterial é um efeito comum das ondas de calor, por isso, é indicado aumentar as doses dos anti-hipertensivos, reforçar a hidratação e procurar fontes de sombra e refrigeração.","D":"As atividades de educação em saúde acerca do estresse climático são desaconselháveis nas escolas, devido ao risco de sofrimento emocional nas crianças e nos adolescentes."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Epidemiologia","topico":"Processo saúde-doença","subtopico":"Determinação Social da Saúde/Determinantes Sociais da Saúde (DSS)"},{"id":"revalida-2025-1-078","number":78,"area":"Pediatria","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Sinais e sintomas Herpes simples congênita Sinais e sintomas Agrupadas no acrônimo TORCHSZ, as infecções congênitas e/ou perinatais são causas de significativa morbimortalidade neonatal. Os sinais e sintomas dessas enfermidades são similares, porém algumas características são mais sugestivas de determinada doença. A partir do exposto, assinale a alternativa que relaciona corretamente sinais e sintomas e/ou achados de exames complementares com a doença.","options":{"A":"Hidrocefalia, plaquetose, hepatoesplenomegalia e icterícia são achados mais comuns da toxoplasmose.","B":"Rash macular com úlceras, plaquetopenia e alteração liquórica são achados típicos da rubéola congênita.","C":"Rinite serossanguinolenta, pseudoparalisia de Parrot, catarata e coriorretinite são encontradas na herpes simples.","D":"Catarata, persistência do canal arterial ou estenose pulmonar e retardo de crescimento intrauterino são achados mais comuns de citomegalovírus."},"answer":"A","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Neonatologia","topico":"Infecções congênitas","subtopico":"Toxoplasmose congênita"},{"id":"revalida-2025-1-079","number":79,"area":"Oftalmologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Homem de 40 anos é levado a uma unidade de pronto atendimento após sofrer um acidente de trabalho enquanto utilizava uma máquina de esmerilhamento. Ele relata que um fragmento metálico de alta velocidade ultrapassou a proteção de seus óculos e atingiu seu olho direito. O paciente apresenta dor intensa no olho afetado, com perda parcial da visão e sensação de corpo estranho. O exame físico revela laceração na conjuntiva bulbar com extravasamento espontâneo de pequena quantidade de conteúdo gelatinoso pelo olho direito. Nesse momento, antes de encaminhar o paciente para o especialista, qual é a conduta adequada para o caso?","options":{"A":"Irrigar o olho afetado com solução salina estéril, fazer penicilina cristalina via endovenosa e reavaliar o paciente após 6 horas.","B":"Colocar escudo rígido sobre o olho afetado, iniciar fluoroquinolona endovenosa e verificar imunização antitetânica.","C":"Aplicar colírio corticoide no olho afetado, colocar escudo rígido sobre ele e solicitar radiografia de órbita.","D":"Aplicar colírio antibiótico no olho afetado, realizar curativo oclusivo e prescrever analgesia endovenosa."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Traumatismos Oculares","topico":"Ruptura do Globo Ocular e Lesão Ocular Penetrante"},{"id":"revalida-2025-1-094","number":94,"area":"Cirurgia Geral","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Homem de 28 anos foi admitido em hospital após 30 minutos de acidente motociclístico. Apresentava múltiplas e graves lesões em face, mandíbula e cavidade oral, sem lesões cervicais. Exame físico do tórax e do abdome e ultrassonografia focada no abdome no trauma (FAST) sem alterações. Sinais vitais: frequência cardíaca 92 bpm; pressão arterial 130 x 80 mmHg; saturação periférica de oxigênio 100% em ar ambiente. O paciente evoluiu rapidamente com dispneia, taquipneia, estridor inspiratório e expiratório, cornagem e rebaixamento do nível de consciência. Saturação periférica de oxigênio passou para 88%, mesmo com a oferta de oxigênio suplementar. Após alguns minutos, evoluiu com saturação periférica de oxigênio de 59% e frequência cardíaca de 48 bpm. Nesse momento, qual é a conduta imediata adequada para esse paciente?","options":{"A":"Traqueostomia.","B":"Cricotireoidotomia.","C":"Intubação orotraqueal.","D":"Intubação nasotraqueal."},"answer":"B","explanation":"","needsVisualReview":false,"questionType":"objective","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","subtopico":"Via Aérea Definitiva"},{"id":"revalida-2025-1-101","number":101,"area":"Ginecologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Uma mulher de 28 anos procura uma médica de família e comunidade para ser orientada quanto à prevenção de infecções sexualmente transmissíveis (IST) e de gestação indesejada. A paciente relata consumo de álcool durante as festas de carnaval e manifesta desejo de fazer uso de dispositivo intrauterino (DIU). Apesar de não ter tido relações sexuais nos últimos 30 dias, a paciente refere atividade sexual com múltiplos parceiros com status sorológico desconhecido nos últimos 6 meses, além de uso inconsistente de preservativo. A2rma ter feito uso de profilaxia pós-exposição (PEP) duas vezes nesse período. Nega uso de outras substâncias psicoativas. Refere data da última menstruação há 7 dias. Realizou coleta de citologia oncótica há 6 meses, sem alterações. A respeito do caso apresentado, responda os itens a seguir. a) Que medidas de prevenção de IST podem ser oferecidas à paciente pela médica de família? (valor: 4,0 pontos) b) Caso a paciente deseje fazer uso de profilaxia pré-exposição (PrEP), qual deve ser a conduta antes de se iniciar a PrEP? (valor: 3,0 pontos) c) Considerando-se as práticas sexuais da paciente nos 6 meses anteriores à consulta, que condições a médica deve investigar antes da inserção do DIU? (valor: 3,0 pontos)","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Ginecologia endócrina","topico":"Planejamento familiar","subtopico":"Dispositivos intrauterinos"},{"id":"revalida-2025-1-102","number":102,"area":"Ginecologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Mulher de 38 anos, G2P1A1, comparece à unidade básica de saúde (UBS) para solicitar orientação anticoncepcional. É sedentária, cardiopata em uso de anticoagulante oral devido a trombose venosa que sofreu no último aborto, há 6 meses, e apresenta índice de massa corporal (IMC) de 35 kg/m². Além disso, fuma em média 20 cigarros por dia. A partir desse caso clínico, elabore um plano terapêutico abordando os itens a seguir. a) Métodos anticoncepcionais. (valor: 6,0 pontos) b) Outras questões de saúde. (valor: 4,0 pontos)","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Ginecologia endócrina","topico":"Planejamento familiar","subtopico":"Anticoncepção em condições especiais"},{"id":"revalida-2025-1-103","number":103,"area":"Pediatria","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Menino de 6 anos é levado à emergência com quadro de dispneia. Sua mãe, que o acompanha, refere que o paciente tem asma, com uso irregular de corticosteroide inalatório, e apresenta crises frequentes. Relata também que o último episódio se iniciou há 2 dias, com quadro de tosse, febre e “chiado no peito”. Hoje a criança está pior, com dificuldade para respirar. Ao exame físico, o paciente está agitado, sem conseguir completar frases, taquidispneico; frequência respiratória (FR) de 40 incursões respiratórias por minuto (irpm); sibilos difusos à ausculta pulmonar; tiragem intercostal; tempo expiratório prolongado; e saturação de oxigênio (O2) de 90% em ar ambiente. O paciente pesa 24 kg. De imediato, o paciente recebe, por via inalatória, três ciclos de 6 jatos de salbutamol de 100 mcg por 1 jato, utilizando-se espaçador, com intervalo de 20 minutos entre cada ciclo. Após a conduta inicial, a criança é reavaliada, apresentando discreta melhora. O paciente continua com agitação e sem conseguir completar frases, com FR de 36 irpm, saturação de O2 de 91% em ar ambiente, taquidispneia, tiragem intercostal e sibilância difusa. Coleta-se, então, a gasometria arterial em ar ambiente, que mostra pH de 7,37, pO2 de 80 mmHg (80-100 mmHg), pCO2 de 33 mmHg (32–48 mmHg), bicarbonato de 22 mEq/L (20-28 mEq/L) e saturação de O2 de 91%. Considerando esse caso clínico, faça o que se pede nos itens a seguir. a) Interprete os achados da gasometria, relacionando-os com o quadro clínico do paciente. (valor: 2,0 pontos) b) Cite 3 medidas terapêuticas que devem ser realizadas nesse momento no paciente em questão. (valor: 3,0 pontos) c) Há indicação de intubação orotraqueal nesse caso? Cite 2 argumentos que justifiquem sua resposta. (valor: 2,0 pontos) d) Cite 3 critérios necessários para que se indique a internação hospitalar nesse caso. (valor: 3,0 pontos)","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Pneumologia Pediátrica","topico":"Asma ","subtopico":"Classificação e Tratamento da Crise"},{"id":"revalida-2025-1-104","number":104,"area":"Gastroenterologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Homem de 41 anos comparece a unidade básica de saúde com queixa de episódios de hematoquezia de 3 a 4 vezes por mês, durante os últimos 8 meses. O paciente relata que, durante as evacuações, observa nodulação na região anal, que costuma reintroduzir manualmente no ânus. Nega outras alterações associadas. O paciente nega tabagismo, perda de peso significativa, alterações no trânsito intestinal ou comorbidades. Ao exame físico, o paciente apresenta bom estado geral, sem alterações abdominais. Ao exame da região perianal, observa-se prolapso de tecido que se exterioriza à manobra de Valsalva, sendo possível sua redução manual. A inspeção local não revela fissuras ou abscessos. Não há sinais de inflamação intensa ou trombose. Sensibilidade e tônus esfincteriano preservados ao toque retal, sem massas ou lesões palpáveis na ampola retal. Considerando esse caso clínico, responda os itens a seguir. a) Qual é o diagnóstico mais provável? (valor: 2,0 pontos) b) Quais as classificações do quadro desse paciente, a partir do diagnóstico mais provável? (valor: 3,0 pontos) c) Cite apenas 3 condutas clínicas a serem adotadas nessa situação. (valor: 3,0 pontos) d) Qual a conduta cirúrgica indicada? (valor: 2,0 pontos)","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Hemorragia Digestiva (HD)","topico":"Hemorragia Digestiva Baixa - HDB"},{"id":"revalida-2025-1-105","number":105,"area":"Hepatologia","source":"Revalida INEP 2025.1","examId":"revalida-2025-1","examName":"Revalida INEP: 2025.1","stem":"Homem de 58 anos, procedente de zona rural, procura atendimento na unidade básica de saúde com queixa de fadiga crônica há 6 meses e de episódios esporádicos de desconforto abdominal. Relata histórico de transfusão de sangue na infância. Ao exame físico, não apresenta alterações significativas. Testes rápidos para triagem de hepatites virais crônicas apresentam resultados reagentes para hepatite B e hepatite C. Em relação aos resultados dos testes rápidos para triagem das hepatites virais B e C e considerando os dados apresentados nesse caso clínico, responda os itens a seguir. a) É necessária a realização de exames confirmatórios após o teste rápido para hepatite B? Justifique. (valor: 2,0 pontos) b) É necessária a realização de exames confirmatórios após o teste rápido para hepatite C? Justifique. (valor: 2,0 pontos) c) Quais exames complementares adicionais são essenciais para avaliação da gravidade e impacto clínico e funcional da doença hepática? Justifique. (valor: 4,0 pontos) d) Elabore 2 orientações iniciais para o paciente, considerando o manejo das hepatites virais crônicas e possíveis medidas de prevenção direcionadas a contatos domiciliares. (valor: 2,0 pontos)","options":{},"answer":null,"explanation":"","needsVisualReview":false,"questionType":"discursive","assunto":"Hepatites Virais","topico":"Hepatite C"},{"id":"revalida-2024-2-001","number":5,"stem":"Após a promulgação da Constituição Federal de 1988, foram aprovadas duas leis, pelo Congresso Nacional, que são chamadas de leis orgânicas do SUS. Uma delas, a lei n. 8.142/1990, dispõe sobre a participação da comunidade na gestão do Sistema Único de Saúde (SUS) e sobre as transferências intergovernamentais de recursos financeiros na área da saúde.\nConsiderando a legislação mencionada, para que o Governo Federal repasse recursos do SUS para estados e municípios, é necessária a existência de","options":{"A":"comissão de elaboração do plano de carreira, cargos e salários e de prontuário eletrônico.","B":"plano diretor de regionalização e de conselho de saúde paritário.","C":"plano de saúde e de central de marcação de consultas e exames.","D":"fundo de saúde, conselho de saúde, plano de saúde, relatório de gestão, contrapartida de recursos e comissão de elaboração do plano de carreira."},"answer":"D","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","annulled":false,"images":["assets/revalida/img/revalida-2024-2-001-1.png"],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Leis orgânicas da saúde"},{"id":"revalida-2024-2-003","number":3,"stem":"Um adolescente não identificado, encontrado desacordado numa festa Rave, é atendido pelo SAMU. Há relatos de que consumiu drogas de abuso e álcool minutos antes de ser encontrado. À avaliação está sem respiração e sem pulso, segundo relatos há pelo menos 10 minutos. Dois socorristas iniciam a realização das compressões e das ventilações. São colocados eletrodos no paciente, identificando-se atividade elétrica sem pulso (AESP). A partir desse diagnóstico, é realizado acesso venoso de urgência.\nAssinale a alternativa que apresenta as próximas condutas imediatas.","options":{"A":"Pausar massagem cardíaca e obter via aérea segura.","B":"Obter via aérea segura e iniciar administração de drogas vasopressoras.","C":"Prosseguir com compressões e insuflações coordenadas.","D":"Realizar desfibrilação e, depois, retornar com as compressões."},"answer":"B","area":"Cardiologia","assunto":"Arritmias Cardíacas","topico":"Abordagem do paciente em parada cardiorrespiratória (PCR)","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-017","number":17,"stem":"Um homem de 30 anos, com 90 kg, sofre queimadura ao acender uma churrasqueira. Ele apresenta lesões em face anterior do tronco, em face anterior e posterior dos membros superiores e em face anterior de membro inferior esquerdo. Esse paciente é trazido consciente ao pronto-socorro, com queixa de muita dor. Ao exame físico, nota-se eritema em todas as áreas atingidas, com muitas bolhas, principalmente em tórax, antebraços, mãos, perna e pé.\n\nNessa situação, considerando o volume de reposição pela regra dos 9, preconizado pelo ATLS, assinale a alternativa que apresenta, respectivamente, a classificação da queimadura e a reposição volêmica indicada para esse paciente.","options":{"A":"Queimadura moderada, de terceiro grau; reanimação hídrica com cerca de 500 mL/h de solução coloide nas primeiras 8 horas e, após isso, utilização de, aproximadamente, 500 mL/h de ringer, por 16 horas.","B":"Queimadura grave, de terceiro grau; reanimação hídrica com cerca de 1.000 mL/h de ringer lactato nas primeiras 16 horas e, após isso, utilização de, aproximadamente, 500 mL/h, por 8 horas.","C":"Queimadura grave, de segundo grau; reanimação hídrica com cerca de 500 mL/h de ringer lactato nas primeiras 8 horas e, após isso, utilização de, aproximadamente, 250 mL/h, por 16 horas.","D":"Queimadura moderada, de segundo grau; reanimação hídrica com 0,5 mL/kg/h, por 48 horas, com monitoração da diurese."},"answer":"C","area":"Cirurgia Geral","assunto":"Queimaduras e Trauma Elétrico","topico":"Atendimento Inicial às Vítimas de Queimadura","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Manejo Hospitalar"},{"id":"revalida-2024-2-020","number":20,"stem":"Uma menina de 6 anos viajou de férias com a família para a República Dominicana, onde permaneceu por 10 dias. Na véspera do retorno ao Brasil, a paciente apresentou febre baixa, evoluindo, em 24 horas, para um quadro com diarreia súbita, líquida e abundante. Ao desembarcarem no aeroporto, ela foi prontamente atendida pela equipe da ANVISA, que a encaminhou ao hospital para avaliação, devido à suspeita de cólera. Tendo em vista a exuberância dos sintomas e o grau de desidratação, ao chegar ao hospital, a paciente é internada imediatamente. No hospital, são coletadas amostras de fezes, com resultado positivo para Vibrio cholerae. Durante a internação hospitalar, a paciente recebe, além de reidratação endovenosa e de sulfato de zinco, antibioticoterapia com doxiciclina (3 mg/kg em dose única).\n\nNessa circunstância, as medidas de prevenção e de controle pertinentes ao quadro apresentado por essa paciente incluem","options":{"A":"manter a criança em isolamento padrão e de gotículas durante a internação.","B":"proceder à notificação imediata do caso à autoridade de saúde de vigilância municipal.","C":"realizar a testagem dos pais e ministrar antibióticos, no caso de serem portadores assintomáticos do vibrião.","D":"vacinar contra a cólera os pais e pessoas contactantes da criança durante o período de transmissão da doença."},"answer":"B","area":"Medicina Preventiva","assunto":"Epidemiologia","topico":"Aspectos Epidemiológicos das Doenças Transmissíveis","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Mecanismos de Emergência e Reemergência de Doenças Infecciosas"},{"id":"revalida-2024-2-021","number":21,"stem":"Um homem de 65 anos, natural da Bahia, procedente da zona rural, é encaminhado ao ambulatório de gastroenterologia de um hospital escola devido a quadro de disfagia progressiva desenvolvido há 1 ano. O quadro piorou há 2 meses. O paciente passou a apresentar vômitos frequentes com restos alimentares, sem sangue. Nesse período, ele perdeu cerca de 12% de seu peso corporal.\n\nA partir dessas informações, é correto afirmar que a investigação complementar inicial, considerando a etiologia mais provável desse quadro, deve incluir","options":{"A":"radiografia de tórax.","B":"dosagem de CA 19-9.","C":"ressonância magnética de tórax.","D":"sorologia para doença de Chagas."},"answer":"D","area":"Gastroenterologia","assunto":"Esôfago","topico":"Fisiologia e Distúrbios da Motilidade","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-022","number":22,"stem":"Uma paciente de 62 anos foi submetida à colectomia direita com anastomose primária devido a adenocarcinoma colônico. Ela relata antecedente de radioterapia pélvica para tratamento de neoplasia de endométrio. No 4º dia de pós-operatório, ela apresenta 39 °C de temperatura axilar, distensão abdominal sem defesa, presença de ferida operatória sem sinais flogísticos e fístula colo-cutânea com débito de 150 mL/dia em área de cicatriz cirúrgica.\n\nAcerca do tratamento adequado para essa paciente, é correto indicar","options":{"A":"fistulectomia precoce, correção do desequilíbrio acidobásico, terapia nutricional e controle da sepse.","B":"tratamento clínico com controle de sepse, correção hidroeletrolítica volêmica, e terapia nutricional.","C":"fistulografia, jejum, instalação de nutrição parenteral e abordagem cirúrgica do trajeto fistuloso.","D":"jejum, instalação de nutrição parenteral e reabordagem cirúrgica com colostomia."},"answer":"B","area":"Cirurgia Geral","assunto":"Complicações Pós-Operatórias","topico":"Complicações Gastrointestinais","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Fístulas Intestinais"},{"id":"revalida-2024-2-023","number":23,"stem":"Um recém-nascido (RN) a termo, afrodescendente, do sexo masculino, com 26 dias de vida, apresenta quadro de icterícia neonatal zona III de Kramer desde o 3.º dia de vida. Seus pais negam outras queixas e afirmam que ambos são consanguíneos (primos). Encontra-se em uso de fórmula láctea com ganho ponderal adequado. Não houve intercorrências na gestação e parto. Diante dessas informações, o médico solicita outros exames. A criança, então, retorna à consulta ambulatorial com propedêutica complementar solicitada há 7 dias. Os resultados dos exames realizados podem ser verificados a seguir.\n\nA tipagem sanguínea da mãe é O+ e do recém-nascido é A-. O Coombs direto (ou teste de antiglobulina direto) apresenta resultado negativo.\n\nExame laboratorial | Resultado | Valor de referência\nHemoglobina | 12 g/dL | 12,5 a 20,5 g/dL\nHematócrito | 36% | 39 a 63%\nVCM | 80 fL | 86 a 124 fL\nHCM | 26 pg | 28 a 40 pg\nCHCM | 25 g/dL | 28 a 38 g/dL\nPlaquetas | 450.000/mm³ | 250.000 a 500.000/mm³\nReticulócitos | 6,4 % | 2,0 a 6,0%\nBilirrubinas totais | 12,8 mg/dL | RN 3 - 5 dias: 10,30 mg/dL\nBilirrubinas diretas | 0,8 mg/dL | RN 3 - 5 discordant\nBilirrubinas indiretas | 12,0 g/dL | -\nTSH | 5 μU/mL | < 10 μU/mL\n\nConsiderando-se o caso clínico e os exames complementares realizados, qual é a hipótese diagnóstica mais provável?","options":{"A":"Esferocitose hereditária.","B":"Deficiência de G6PD.","C":"Anemia falciforme.","D":"Galactosemia."},"answer":"A","area":"Pediatria","assunto":"Neonatologia","topico":"Icterícia nenonatal e distúrbios hematológicos no RN","annulled":false,"images":["assets/revalida/img/revalida-2024-2-023-1.png"],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Icterícia neonatal"},{"id":"revalida-2024-2-030","number":30,"stem":"Em certo município brasileiro, a gestão da saúde é feita de forma centralizada: todas as decisões e ações são tomadas por um pequeno grupo de gestores sem a participação efetiva da população. Isso tem gerado descontentamento e desconfiança por parte dos cidadãos, que sentem que suas necessidades e demandas não estão sendo consideradas. Um grupo de moradores, então, decide organizar-se para reivindicar maior participação no processo de gestão da saúde. A primeira medida que esses moradores tomam é buscar informações sobre o controle social no SUS.\n\nEsse grupo de moradores descobriu, com base na lei n. 8.142 de 1990 e no Decreto n. 7.508 de 2011, que eles têm o direito de","options":{"A":"votar na conferência municipal de saúde a cada 3 anos e na conferência estadual de saúde a cada 6 anos.","B":"participar de conselhos de saúde em proporção não paritária em relação ao conjunto dos demais segmentos.","C":"eleger representantes para o conselho estadual de saúde, que deve ser composto por, no mínimo, 50% de usuários.","D":"atuar na gerência de unidades básicas municipais de saúde após realização de curso fornecido pelo Ministério da Saúde."},"answer":"C","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Principais marcos legais do SUS","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Leis orgânicas da saúde"},{"id":"revalida-2024-2-046","number":46,"stem":"Um homem de 68 anos busca uma unidade de pronto-atendimento devido à dor precordial tipo aperto, irradiada para região cervical anterior, de intensidade moderada. O primeiro episódio de dor se iniciou há aproximadamente 4 horas e cessou, espontaneamente, após 15 minutos de duração. Relata que, há 20 minutos, iniciou-se um novo episódio de dor precordial, tipo aperto, irradiada para região cervical, um pouco mais intensa do que a anterior e que, no momento, parece estar diminuindo. O paciente é hipertenso há 16 anos e diabético há 7 anos. Faz uso diário de enalapril, 20 mg de 12 em 12 horas, de glibenclamida, 5 mg ao dia, e de metformina, 850 mg 2 vezes ao dia. Nega tabagismo e refere fazer caminhadas diárias de até 40 minutos. Relata que seu irmão mais velho faleceu por infarto agudo do miocárdio há 30 dias. O exame físico apresentou-se sem alterações. O paciente realizou dosagem de troponina ao ser admitido e após 3 horas, ambas com resultados normais. Também realizou 2 ECGs: o primeiro na admissão e, o segundo, depois de 30 minutos:\n\n[ECG Admissão e ECG após 30 minutos]\n\nNesse caso, a conduta terapêutica correta é proceder com","options":{"A":"realização de oxigenioterapia, de analgesia, de terapias anti-isquêmica, antitrombótica e anticoagulante e encaminhamento do paciente à unidade de terapia intensiva.","B":"prescrição de fibrinólise pré-hospitalar e, posteriormente, encaminhamento do paciente para o hospital de referência.","C":"encaminhamento do paciente ao laboratório de hemodinâmica para realização de angioplastia primária.","D":"acolhimento do paciente, dando a ele orientações e encaminhamento ao ambulatório de cardiologia."},"answer":"A","area":"Cardiologia","assunto":"Aterosclerose e Doença Arterial Coronariana","topico":"Síndrome Coronariana Aguda sem Supradesnível do Segmento ST (SCASSST)","annulled":false,"images":["assets/revalida/img/revalida-2024-2-046-1.png"],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-060","number":60,"stem":"Um médico de família realiza uma visita domiciliar a um homem de 64 anos que está acamado e em tratamento para mal de Parkinson e hipertensão arterial. Durante a consulta, a filha do paciente relata que seu pai apresenta alterações de comportamento há 4 dias, estando mais prostrado e lentificado, com episódios de agitação noturna, sem outras queixas. Ao exame físico, notam-se estertores crepitantes em terço médio à direita, sem alteração percebida na ausculta cardíaca. Paciente sarcopênico e sem sinais de roda denteada. Apresenta, pressão arterial de 110 × 95 mmHg, frequência cardíaca de 96 batimentos por minuto, frequência respiratória de 13 incursões respiratórias por minuto, saturação de oxigêncio de 99% em ar ambiente e temperatura de 36,1 °C.\nO médico solicitou exames complementares, cujos resultados foram apresentados a ele três dias depois, no retorno da visita domiciliar. A consulta foi constatado que o idoso mantinha o mesmo quadro clínico pelo sétimo dia consecutivo. Apresentou os seguintes exames:\n[Tabela de exames e radiografia de tórax nas imagens]\nA conduta terapêutica a ser adotada para o caso desse paciente é","options":{"A":"iniciar tratamento para quadro demencial, associado à doença de base.","B":"realizar a internação hospitalar do paciente para instituir tratamento endovenoso.","C":"iniciar tratamento ambulatorial para tuberculose pulmonar e profilaxia dos contactantes.","D":"instituir betalactâmico em domicílio e orientar familiares responsáveis quanto aos sinais de alarme."},"answer":null,"area":"Infectologia","assunto":"Pneumonia","topico":"Pneumonia adquirida na comunidade (PAC)","annulled":true,"images":["assets/revalida/img/revalida-2024-2-060-1.png","assets/revalida/img/revalida-2024-2-060-2.png"],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-062","number":62,"stem":"Uma menina de 5 anos chega ao pronto-socorro pediátrico acompanhada pelo pai. Ele relata ter aplicado um protetor solar em aerossol no rosto da filha há cerca de 30 minutos. Desde então, ela apresenta uma ardência intensa nos olhos, vermelhidão e sensibilidade à luz.\nNesse caso, de acordo com as diretrizes atuais do ATLS, qual deve ser o tratamento inicial adotado para essa paciente?","options":{"A":"irrigação com soro fisiológico ou ringer lactato.","B":"irrigação com corticoide e antibiótico tópicos.","C":"aplicação local de pomada antibiótica.","D":"aplicação local de colírio analgésico."},"answer":"A","area":"Oftalmologia","assunto":"Traumatismos Oculares","topico":"Queimaduras Químicas Oculares","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-068","number":68,"stem":"Uma criança de 3 anos, pré-escolar, é atendida na atenção primária à saúde. Ao verificar o cartão vacinal dela, o médico constata atraso. Ele verifica que não foram administradas as vacinas recomendadas aos 15 meses.\nNesse caso, buscando regularizar o cartão vacinal o quanto antes, as vacinas a serem aplicadas nessa criança, devem ser","options":{"A":"difteria, tétano e pertussis; hepatite A; sarampo, caxumba e rubéola.","B":"sarampo, caxumba e rubéola; varicela; poliomielite oral; febre amarela.","C":"sarampo, caxumba e rubéola; hepatite A; difteria, tétano e pertussis; varicela; febre amarela.","D":"difteria, tétano e pertussis; hepatite A; sarampo, caxumba e rubéola; varicela; poliomielite oral."},"answer":"D","area":"Pediatria","assunto":"Puericultura ","topico":"Imunizações/Vacinação ","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Programa Nacional de Imunizações"},{"id":"revalida-2024-2-071","number":71,"stem":"Uma jovem de 15 anos, previamente hígida, é trazida para consulta em unidade básica de saúde devido a quadro, iniciado há 1 semana, de astenia progressiva, dor de garganta e febre diária. Ao exame físico, apresenta linfonodomegalia cervical, principalmente em cadeia posterior, leve erupção cutânea não pruriginosa em tronco e em membros superiores, além de petéquias em palato e tonsilite exsudativa. Nega ter vida sexual ativa e usar drogas injetáveis.\nConsiderando essas informações, a hipótese diagnóstica mais provável é","options":{"A":"criptococose.","B":"infecção pelo HIV.","C":"linfoma não Hodgkin.","D":"monoucleose infecciosa."},"answer":"D","area":"Pediatria","assunto":"Infectologia Pediátrica","topico":"Doenças exantemáticas","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Mononucleose"},{"id":"revalida-2024-2-072","number":72,"stem":"Um paciente de 20 anos procura atendimento imediato em posto de saúde devido a um ferimento cortante em face volar do 1º quirodáctilo direito em falange proximal. Ao exame físico, observa-se ferida cortante de 2 cm de extensão com déficit na flexão do segmento e com sangramento em pequeno volume.\nA conduta adequada deve ser a realização de uma","options":{"A":"sutura simples da pele.","B":"sutura da pele e imobilização com gesso.","C":"curativo simples e transferência para ortopedia.","D":"curativo simples e transferência para cirurgia vascular."},"answer":"C","area":"Cirurgia Geral","assunto":"Trauma","topico":"Trauma Músculo-Esquelético","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Diagnóstico "},{"id":"revalida-2024-2-080","number":80,"stem":"Uma primigesta de 28 anos, com idade gestacional de 25 semanas e 4 dias, foi atendida por uma equipe de saúde da família fluvial. Na avaliação, ela se queixou de tosse há 5 dias, associada a anosmia, febre de 38,2 °C e dispneia. Segundo familiares, ela recebeu apenas a primeira dose da vacina contra Covid-19. O quadro clínico dessa paciente evolui com insuficiência respiratória aguda e óbito. Diante disso, é realizado parto cesáreo de urgência e a criança nasce com 450 g e 20 cm, apresentando batimentos cardíacos e movimentos respiratórios por 10 segundos, sendo constatado óbito do bebê após esse período. A paciente havia realizado apenas uma consulta de pré-natal, assim que descobriu a gestação, não tendo sido identificadas alterações nos exames realizados à época.\n\nComo esses eventos devem ser considerados para o cálculo dos indicadores de mortalidade e natalidade?","options":{"A":"A morte da gestante não será contabilizada no cálculo da mortalidade materna; a criança será contabilizada no cálculo da natalidade e da mortalidade neonatal precoce.","B":"A morte da gestante será contabilizada no cálculo da mortalidade materna; a criança será contabilizada apenas no cálculo da mortalidade perinatal, não contribuindo para a natalidade.","C":"A morte da gestante não será contabilizada no cálculo da mortalidade materna; a criança será contabilizada apenas no cálculo da mortalidade infantil, não contribuindo para a natalidade.","D":"A morte da gestante será contabilizada no cálculo da mortalidade materna; a criança será contabilizada no cálculo da natalidade e da mortalidade infantil neonatal precoce."},"answer":"D","area":"Medicina Preventiva","assunto":"Epidemiologia","topico":"Medidas de saúde coletiva","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Indicadores especiais de mortalidade"},{"id":"revalida-2024-2-091","number":91,"stem":"Uma mulher de 45 anos, portadora de hipertensão arterial sistêmica há menos de 1 ano, vai à consulta de acompanhamento no centro de saúde. Durante a consulta, são observados edema e piora da hipertensão. Em investigação laboratorial, constata-se a presença de hematúria microscópica persistente com presença de dismorfismo eritrocitário, proteinúria de 1,5 g/24 horas e albumina sérica de 3,6 mg/dL. A paciente é referenciada ao nefrologista que indicou a realização de biópsia renal.\nAssinale a alternativa que apresenta a síndrome clínica reportada e um possível diagnóstico compatível com o quadro.","options":{"A":"Síndrome nefrótica; amiloidose renal.","B":"Síndrome nefrítica; nefropatia por IgA.","C":"Síndrome nefrótica; nefropatia membranosa.","D":"Síndrome nefrítica; doença de lesões mínimas."},"answer":"B","area":"Nefrologia","assunto":"Glomerulopatias","topico":"As grandes síndromes glomerulares","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-092","number":92,"stem":"Uma paciente de 24 anos, estudante, é atendida no pronto-socorro após sentir uma tumoração, de moderado volume, com hiperemia, em região retroauricular à direita e redução da acuidade auditiva. Relata apresentar, há 5 semanas, episódios repetidos de dor na orelha direita, que melhoravam com analgésico e calor local. Ao exame físico, nota-se presença de celulite retroauricular à direita, sem saída de secreção ou ponto de flutuação e sem secreção no conduto auditivo. \nNesse caso, qual deve ser a conduta imediata para essa paciente?","options":{"A":"Internação hospitalar, uso de antibioticoterapia tópica e cirurgia de urgência.","B":"Encaminhamento para especialista para avaliação e tratamento eletivos.","C":"Internação hospitalar, antibioticoterapia sistêmica e avaliação especializada.","D":"Tratamento domiciliar com antibiótico oral e acompanhamento em unidade básica de saúde."},"answer":"C","area":"Otorrinolaringologia","assunto":"Infecções das Vias Aéreas Superiores","topico":"Otites","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-096","number":96,"stem":"Um homem de 75 anos, tabagista inveterado, com diagnóstico recente de câncer de pulmão de pequenas células, é levado a uma unidade de emergência com quadro de rebaixamento do nível de consciência. Segundo familiares, nos últimos dias, ele vinha se queixando de cefaleia holocraniana e de turvação visual bilateral. Na véspera do atendimento, os familiares relatam que o paciente ficou sonolento e que, no dia do atendimento, evoluiu com crises convulsivas tônico-clônicas generalizadas. Ao exame físico, mostra-se torporoso, mas sem déficits neurológicos focais, mantendo hemodinâmica (pressão arterial elevada, em 170 × 100 mmHg); padrão respiratório regular (frequência respiratória de 18 incursões respiratórias por minuto) e frequência cardíaca de 58 batimentos por minuto. Os exames complementares revelam anemia normocrômica, normocítica, (hemoglobina de 9,2 g/dL); sódio sérico baixo (108 mEq/L); ácido úrico sérico baixo (2,1 mg/dL); hiperglicemia leve (138 mg/dL) e taxa de excreção renal de sódio superior a 25 mEq/dia. À tomografia computadorizada de crânio, identifica-se aspecto compatível com edema cerebral difuso.\n\nNesse caso, a conduta adequada é proceder com a","options":{"A":"infusão intravenosa de 0,05 mL/kg/min de solução salina a 3%.","B":"prescrição de dexametasona 10 mg de ataque, seguida por 4 mg, 4 vezes ao dia.","C":"administração de desmopressina 0,05 mg, 2 vezes por dia, por meio de puff nasal.","D":"restrição hídrica, limitando a oferta de soluções hipotônicas em 1,2 litros por dia."},"answer":"A","area":"Nefrologia","assunto":"Hiponatremia","topico":"Quadro clínico","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-097","number":97,"stem":"Um paciente de 21 anos, atleta, com 1,92 m de estatura, vai à consulta ambulatorial relatando dor recorrente em membro inferior esquerdo, com piora progressiva há 2 meses e com alguns episódios de febre nas crises de dor, além de perda de peso de 6 kg no último mês. O paciente observou aumento do volume no terço medial da perna esquerda e, há 1 semana, está claudicando devido à dor. Ao exame físico, percebe-se aumento do volume do terço medial da tíbia com tumoração palpável de 3 cm de diâmetro, sem alterações de mobilidade do membro ou lesões de pele.\n\nAssinale a alternativa que apresenta, respectivamente, a principal hipótese diagnóstica, a investigação complementar e a conduta para esse caso.","options":{"A":"Calo ósseo por prática de esporte; radiografia; analgesia e repouso.","B":"Osteopenia; cintilografia óssea e hemograma; orientação nutricional.","C":"Osteossarcoma; ressonância magnética e biópsia; quimioterapia.","D":"Lesão por esforço repetitivo; tomografia computadorizada e cintilografia; fisioterapia."},"answer":"C","area":"Ortopedia","assunto":"Ortopedia Geral","topico":"Tumores ósseos","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-026","number":26,"stem":"Uma paciente de 74 anos, com diagnóstico de hipertensão arterial sistêmica e de diabetes mellitus tipo 2 há 25 anos, é trazida de instituição de longa permanência. Ela se queixa de fraqueza acentuada em membros inferiores observada há, pelo menos, 1 ano e que vem se agravando há 2 semanas. Relata não ter força para caminhar e nega febre. Ao exame físico, apresenta-se em estado geral regular, lúcida, orientada e hidratada. Identifica-se, em exame neurológico, força grau 3 em membros inferiores; tônus reduzido em panturrilhas bilateralmente; reflexos patelar e aquileu abolidos bilateralmente. Observa-se ausência de alterações da rima labial; teste do monofilamento alterado em ambos os pés; pulsos pediosos e tibiais posteriores reduzidos (2+/4+) bilateralmente.\nA partir dessas informações, qual é o exame complementar mais adequado para o caso?","options":{"A":"Radiografia de coluna lombo-sacra.","B":"Ressonância magnética de encéfalo.","C":"Ressonância magnética de coluna tóraco-lombar.","D":"Pesquisa de sensibilidade com o uso de biotesiômetro."},"answer":"C","area":"Neurologia","assunto":"Doenças Neuromusculares","topico":"Neuropatias Periféricas","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-027","number":27,"stem":"Um paciente de 65 anos vai ao SAMU referindo dor lombar aguda irradiada para membro inferior direito, após queda da própria altura ocorrida há 6 horas. Ele está utilizando anti-inflamatório e analgésico via oral e apresenta retenção urinária e dor em hipogástrio. Possui histórico de dor lombar crônica e osteoartrite em coluna lombar e coxofemoral direita. Ao exame físico, apresenta dor à palpação de região púbica com massa palpável na região suprapúbica; força muscular preservada em membros inferiores e reflexos patelar e aquileu preservados bilateralmente; hipoestesia tátil em face posterior de coxa e perna direita e anestesia em região perineal bilateral. Ressonância magnética de coluna lombar mostrou alterações degenerativas de discos intervertebrais L3-L4 / L4-L5 / L5-S1, com redução de forames intervertebrais correspondentes, osteófitos posteriores em corpos vertebrais de L4, L5 e S1, além de protrusão discal volumosa centro-foraminal à direita em L4-L5, causando estenose foraminal nesse nível.\nDiante dessas informações, a conduta terapêutica adequada, no caso desse paciente, é realizar","options":{"A":"descompressão cirúrgica de urgência e utilizar analgésico comum.","B":"tratamento conservador e associar o uso de analgésicos opioides.","C":"sondagem vesical de demora e usar anti-inflamatório esteroidal.","D":"tratamento conservador e manter uso de anti-inflamatório."},"answer":"A","area":"Ortopedia","assunto":"Ortopedia Geral","topico":"Doenças da coluna vertebral","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-037","number":37,"stem":"Uma paciente de 64 anos é socorrida, em via pública, pelo SAMU por queda da própria altura com rebaixamento do nível de consciência. Ao exame físico, constata-se ferida corto-contusa na região occipital direita de 3 cm; Glasgow 9; pressão arterial de 110 × 70 mmHg; e frequência cardíaca de 88 batimentos por minuto. Ao exame pulmonar, percebe-se expansibilidade preservada bilateralmente e, à ausculta cardíaca, constata-se bulhas rítmicas e normofonéticas. O abdome apresenta-se flácido e indolor.\n\nNesse caso, a conduta imediata deve ser a","options":{"A":"intubação com inclinação da cabeça para trás, em extensão cervical, e realizar elevação do mento.","B":"ventilação com máscara por meio da tração anterior da mandíbula com discreta flexão cervical.","C":"intubação com tração anterior pelo ângulo da mandíbula com discreta rotação cervical para o lado do socorrista.","D":"ventilação com máscara e desobstrução de vias aéreas utilizando manobras manuais que preservem a coluna cervical (como a tração da mandíbula) sem extensão da cabeça."},"answer":"B","area":"Cirurgia Geral","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Via Aérea Definitiva"},{"id":"revalida-2024-2-039","number":39,"stem":"Uma paciente de 39 anos, G2 PV1, com idade gestacional de 40 semanas (calculada por ecografia obstétrica de 10 semanas de idade gestacional), procura sua maternidade de referência. Ela refere movimentação fetal e nega perdas de líquido ou sangramentos vaginal. Está em uso de metildopa 750 mg/dia, por hipertensão gestacional, com bom controle pressórico. A paciente tem fator ABO Rh: A+ e realizou todas as rotinas laboratoriais do pré-natal, as quais estavam normais. Sua última ecografia obstétrica com Doppler foi realizada há 4 semanas e evidenciou feto único, cefálico, com índice de líquido amniótico normal, peso fetal no percentil 20 e circunferência abdominal fetal no percentil 30. O Doppler obstétrico apresentou-se normal.\nAo exame físico, apresenta-se afebril, eupneica com frequência cardíaca de 88 batimentos por minuto, pressão arterial de 127 × 66 mmHg. Ao exame físico obstétrico, identifica-se altura uterina de 34 cm, movimentação fetal presente, dinâmica uterina ausente e índice de Bishop de 8.\nÀ carditocografia, identificou-se aumento abrupto da frequência cardíaca fetal, com ápice maior ou igual a 15 batimentos por minuto e duração maior ou igual a 15 segundos; batimento cardíaco fetal basal de 130 batimentos por minuto e variabilidade da frequência cardíaca fetal de 20 batimentos por minuto.\nNesse caso, conforme o Manual de Gestação de Alto Risco do Ministério da Saúde (2022), qual é a conduta médica adequada?","options":{"A":"Pedir uma ecografia obstétrica com Doppler.","B":"Solicitar a realização de uma amnioscopia.","C":"Indicar a indução de trabalho de parto.","D":"Orientar que retorne em 3 dias."},"answer":"C","area":"Obstetrícia","assunto":"Doenças associadas à gestação","topico":"Síndromes Hipertensivas da Gestação","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Hipertensão gestacional"},{"id":"revalida-2024-2-042","number":42,"stem":"Um paciente, que está no 5º dia pós-operatório de gastroduodenopancreatectomia para o tratamento de neoplasia da papila duodenal, é encaminhado a consulta. Ao examiná-lo, o médico nota o paciente normocárdico, afebril, com drenagem de 500 mL/24h de secreção clara e límpida por meio de dreno abdominal. A ferida cirúrgica está sem sinais de flogose.\nNesse caso, para o diagnóstico de eventual complicação, deve-se realizar","options":{"A":"ultrassonografia endoscópica.","B":"cultura e antibiograma da secreção.","C":"dosagem de amilase e lipase da secreção.","D":"colangiopancreatografia retrógrada endoscópica."},"answer":"C","area":"Cirurgia Geral","assunto":"Complicações Pós-Operatórias","topico":"Complicações Gastrointestinais","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Fístula Pancreática Pós-operatória"},{"id":"revalida-2024-2-054","number":54,"stem":"Uma primigesta de 41 anos, com idade gestacional de 20 semanas, vai à consulta pré-natal para levar seus exames de rotina, sem apresentar outras queixas. Seu exame físico está normal, os batimentos cardíacos fetais estão em 140 batimentos por minuto e o fundo uterino é de 21 cm. Ao checar os exames, a médica observou que a glicemia de jejum da paciente era de 110 mg/dL. Os demais exames de rotina pré-natal estavam normais.\nDiante desse quadro, a conduta adequada para essa paciente é","options":{"A":"realizar teste oral de tolerância à glicose com 75 g entre 30 e 34 semanas de gestação, pois ela apresenta pré-diabetes.","B":"realizar teste de glicemia de jejum entre 28 e 30 semanas de gestação, a fim de confirmar o diagnóstico de diabetes gestacional.","C":"iniciar uso de insulina NPH para evitar complicações mais graves para a mãe e para o feto, pois ela apresenta uma alteração na produção de insulina.","D":"iniciar tratamento com dieta pobre em carboidrato e começar a praticar atividade física regular, pois ela apresenta diagnóstico de diabetes gestacional."},"answer":"D","area":"Obstetrícia","assunto":"Doenças associadas à gestação","topico":"Diabetes na gestação (DMG)","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Diagnóstico "},{"id":"revalida-2024-2-056","number":56,"stem":"Uma mulher de 42 anos é levada por familiares à emergência apresentando estado confusional e elevação importante da pressão arterial. Os familiares relatam que ela começou, recentemente, tratamento para hipertensão e que, nos últimos dias, tem se queixado de palpitações, cefaleia e sensação de cabeça leve. Atualmente, está utilizando metoprolol em substituição à clonidina, além de hidroclorotiazida e enalapril. Ao exame físico, apresenta-se agitada, confusa, com pupilas dilatadas e edema papilar, ela está sudoreica, com as extremidades apresentando discreto tremor e pulsos periféricos amplos, pressão arterial de 230 × 150 mmHg, frequência cardíaca de 115 batimentos por minuto e saturação de oxigênio de 89%. Realizada tomografia de crânio e coleta de líquor, cujos resultados não apresentaram evidências de hemorragia intracraniana ou de infecção. O resultado da pesquisa de drogas na urina foi negativo.\nDiante desse quadro, a conduta imediata mais adequada para essa paciente é","options":{"A":"transferi-la para a unidade de terapia intensiva, intubá-la e realizar exame para mensurar as enzimas cardíacas.","B":"monitorizá-la, puncionar acesso venoso calibroso, iniciar oxigenoterapia com máscara e administrar nitroprussiato de sódio por via intravenosa.","C":"interná-la em enfermaria, prescrever diuréticos, ansiolíticos, IECA ou BRA e betabloqueadores e solicitar ressonância magnética. ","D":"acompanhá-la em enfermaria nas próximas 24 horas, aguardar melhora do quadro e encaminhá-la para atendimento ambulatorial."},"answer":"B","area":"Cardiologia","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Hipertensão arterial complicada","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-086","number":86,"stem":"Uma paciente de 39 anos procura a unidade básica de saúde referindo quadro de lombalgia iniciado há 20 dias. Relata sentir, desde o início do quadro, fraqueza em membros inferiores e apresentar polievacuações. Também relata uma sensação de anestesia na região perineal. Nega disúria, mas afirma ter dificuldade para urinar espontaneamente. Nega leucorreia, febre ou história de traumatismos. Afirma que seu peso tem se mantido estável e que sua última menstruação foi há 25 dias.\nA partir dessas informações, assinale a alternativa apresenta o exame mais indicado para a investigação do quadro.","options":{"A":"Radiografia de coluna lombossacra e de bacia.","B":"Punção lombar com análise do líquor.","C":"Ressonância magnética da coluna lombar.","D":"Exame de rotina de urina (EAS) e urocultura."},"answer":"C","area":"Ortopedia","assunto":"Ortopedia Geral","topico":"Doenças da coluna vertebral","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2"},{"id":"revalida-2024-2-088","number":88,"stem":"Uma pré-escolar de 4 anos é atendida com quadro, iniciado no dia anterior, de diarreia associada à febre de até 38,5 °C, que cede com o uso de antitérmico. Segundo a mãe, foram 9 episódios de fezes líquidas, sem muco, pus ou sangue associados. A criança também apresenta coriza hialina e tosse pouco produtiva, iniciadas 2 dias antes. A mãe nega recusa alimentar e, durante a consulta, foi oferecida água para a criança que bebeu sem dificuldades. Ao exame físico, apresenta-se em bom estado geral, responde a brincadeiras de maneira tranquila, está hidratada e que o sinal da prega retorna em menos de 2 segundos.\nNesse caso, considerando-se a classificação dos tipos de desidratação, a conduta médica adequada é","options":{"A":"prescrever zinco oral por 10 dias.","B":"solicitar que a paciente retorne em 2 dias.","C":"administrar soro de reidratação oral na unidade de saúde.","D":"prescrever antibiótico oral, de acordo com a epidemiologia local."},"answer":"A","area":"Pediatria","assunto":"Gastrologia Pediátrica","topico":"Diarreia Aguda ","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Manejo da hidratação"},{"id":"revalida-2024-2-053","number":53,"stem":"Um recém-nascido (RN) com 25 dias de vida, masculino, é levado por sua mãe para consulta na unidade de saúde com história de febre de 39 °C, recusa alimentar e vômitos. A mãe relata que seu filho está em aleitamento materno exclusivo e que é a primeira vez que ele fica doente. Ao exame físico, nota-se RN irritado, com temperatura axilar de 38,3 °C, sem nenhuma outra alteração. Ao hemograma, observa-se leucocitose com neutrofilia e plaquetas normais. À rotina de urina, nota-se piúria, estearase positiva, nitrito positivo e flora aumentada. Em Gram de gota de urina não centrifugada, é constatada presença de bastonete Gram negativo (> 1 bactéria/campo de imersão).\n\nConsiderando o provável diagnóstico, a conduta imediata do médico deve ser","options":{"A":"repetir todos os exames e, caso seja confirmado o diagnóstico, internar a criança e iniciar tratamento parenteral.","B":"introduzir antibiótico parenteral imediatamente, confirmar o diagnóstico pela urocultura e pedir cintigrafia com DMSA e ultrassonografia em 30 dias.","C":"internar o RN, iniciar antibiótico parenteral imediatamente, sem necessidade de confirmação pela urocultura e realizar ultrassonografia após o término do tratamento.","D":"iniciar antibiótico oral ambulatorialmente e já pedir ultrassonografia renal e de vias urinárias, além de programar cintigrafia com DMSA assim que a criança tiver alta."},"answer":"C","area":"Pediatria","assunto":"Nefrologia Pediátrica ","topico":"Infecção de Trato Urinário (ITU)","annulled":false,"images":[],"source":"Revalida INEP 2024.2","examId":"revalida-2024-2","examName":"Revalida INEP: 2024.2","subtopico":"Tratamento"},{"id":"revalida-2024-1-014","number":14,"stem":"Os dados da carteirinha de uma gestante com 28 anos, primigesta, sem intercorrências clínicas prévias à gestação e que foi atendida em uma unidade básica de saúde, estão transcritos a seguir:\n\nDATA | IG | PA | AU | BCF/MF | OBSERVAÇÕES\n15/09 | 7 sem. | 100/70 | - | -/- | Náuseas leves, dor em cólicas discretas. Tabagista 10 cigarros/dia. Pedidos exames de rotina.\n12/10 | 11 sem. | 94/62 | 6 cm | -/- | Piora nas náuseas, medicada com metoclopramida. Solicito ultrassonografia morfológica.\n12/11 | 15 sem. | 100/64 | 12 cm | +/- | Melhora nas náuseas, refere corrimento amarelado. Não conseguiu fazer o USG.\n09/12 | 19 sem. | 110/72 | 17 cm | +/+ | Já percebe MF, sente dor em hipogástrio.\n07/01 | 21 sem. | 104/68 | 20 cm | +/+ | Sem queixas.\n11/02 | 26 sem. | 130/98 | 24 cm | +/+ | Solicitado USG morfológica do segundo trimestre.\n15/03 | 31 sem. | 140/82 | 26 cm | +/+ | Aguarda USG morfológica. Teve sinusiorragia e sangramento ao esforço evacuatório.\n12/04 | 35 sem. | 142/88 | 29 cm | +/+ | Encaminhada para avaliação no setor de gravidez de alto risco.\n\nCom base nesses dados, é correto afirmar que:","options":{"A":"o atendimento pré-natal foi adequadamente realizado.","B":"o diagnóstico de pré-eclâmpsia sem critérios de gravidade pode ser estabelecido.","C":"o referenciamento da paciente para o pré-natal de alto risco não está indicado.","D":"a USG obstétrica morfológica do segundo trimestre foi solicitada no momento incorreto."},"answer":"D","area":"Obstetrícia","assunto":"Pré-natal","topico":"Assistência pré-natal","annulled":false,"images":["assets/revalida/img/revalida-2024-1-014-1.png"],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Exames ultrassonográficos"},{"id":"revalida-2024-1-022","number":22,"stem":"Um paciente com 30 anos, portador de diabetes mellitus tipo 1 há 15 anos, retorna para uma consulta com queixa de ulceração em região plantar esquerda, em extremidade distal, posterior, do 4º metatarso esquerdo, com início há cerca de 20 dias. Ao exame físico, verificam-se: pulso de 80 bpm, pressão arterial de 120 x 70 mmHg, temperatura de 36,5 °C; todos os pulsos presentes, cheios e simétricos. Observa-se, ainda, a presença de lesão ulcerada de 3 cm com discreta secreção serosa, sem hiperemia ou calor, com hiperqueratose local e com tecido de granulação central em região plantar esquerda.\n\nNesse caso, além do controle glicêmico, qual é o tratamento adequado?","options":{"A":"Simpatectomia lombar.","B":"Enxerto de pele autólogo.","C":"Terapia compressiva inelástica.","D":"Curativo e adaptação de calçado."},"answer":"D","area":"Cirurgia Geral","assunto":"Cirurgia Vascular","topico":"Oclusão Arterial Crônica (OAC)","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Tratamento"},{"id":"revalida-2024-1-029","number":29,"stem":"Em sua segunda consulta de pré-natal, uma paciente com 36 anos, na 8ª semana da gestação, refere fadiga, ganho de peso, queda de cabelos e pele ressecada. Relata que já teve 2 abortamentos e que, atualmente, está na terceira gestação. Traz resultado de exames laboratoriais cujo único achado relevante foi o de TSH de 8,20 mUI/L (valor de referência - VR = 0,4 a 4,5 mUI/L). Em relação à condição clínica descrita, assinale a opção correta.","options":{"A":"A prescrição de metimazol deverá ser iniciada imediatamente, considerando-se a principal hipótese diagnóstica e etiologia dessa situação clínica.","B":"Os níveis elevados de estrógenos da gestação estimulam, em nível hepático, aumento na produção de TBG, o que pode determinar a elevação do TSH.","C":"A presença de TSH elevado se correlaciona a perdas fetais, independentemente de a gestante apresentar bócio, sendo mais grave se o resultado do exame de anti-TPO estiver elevado.","D":"A prescrição de levotiroxina somente deverá se iniciar após as 12 semanas de gestação, pois, se administrada antes, a molécula atravessa a barreira placentária e pode inibir o desenvolvimento embriológico da tireoide fetal."},"answer":"C","area":"Obstetrícia","assunto":"Doenças associadas à gestação","topico":"Tireoidopatias na gestação","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1"},{"id":"revalida-2024-1-032","number":32,"stem":"Um homem com 32 anos dá entrada na unidade de pronto-socorro, vítima de queimadura por fogo. A esposa refere que o acidente aconteceu quando ele tentou acender a churrasqueira com álcool, momento em que o fogo atingiu as mãos e os braços. Ao exame físico, o paciente apresenta queimaduras de segundo grau em cerca de 25% da superfície corporal, incluindo as mãos e os membros superiores. A caderneta vacinal registra a aplicação de 3 doses da vacina antitetânica, com intervalos mensais, realizada há 3 anos.\nDiante desse quadro, após a realização de analgesia, reposição volêmica e limpeza das feridas, qual é a conduta correta em relação à profilaxia do tétano?","options":{"A":"Administrar a dose de reforço de vacina antitetânica.","B":"Administrar o soro antitetânico, com dose de reforço de vacina antitetânica.","C":"Não administrar dose de reforço de vacina antitetânica e indicar o uso de soro antitetânico.","D":"Não administrar dose de reforço de vacina antitetânica e não indicar o uso de soro antitetânico."},"answer":"D","area":"Cirurgia Geral","assunto":"Cicatrização de Feridas","topico":"Classificação da Cicatrização","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Fechamento Primário"},{"id":"revalida-2024-1-051","number":51,"stem":"Um homem com 65 anos refere, em consulta, apresentar múltiplas lesões dolorosas por todo o corpo e febre intermitente há 2 semanas. Ao exame físico, verificam-se: temperatura axilar de 38 °C e frequência cardíaca de 89 bpm, nódulos cutâneos múltiplos, dolorosos, firmes, eritematosos, medindo cerca de 2 x 2 cm cada um, que estão distribuídos bilateralmente em braços, antebraços, coxas e dorso; rarefação dos pelos nos supercílios, edema e dor nas articulações do pulso e do tornozelo. Realizado exame anatomopatológico de uma lesão nodular, o resultado evidenciou granulomas dérmicos e vasculite leucocitoclástica. Considerando-se esse quadro, qual é a hipótese diagnóstica mais provável?","options":{"A":"Reação hansênica tipo 2.","B":"Granulomatose de Wegner.","C":"Leishmaniose tegumentar americana.","D":"Manifestação cutânea de retocolite ulcerativa."},"answer":"A","area":"Dermatologia","assunto":"Hanseníase","topico":"Introdução","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1"},{"id":"revalida-2024-1-082","number":82,"stem":"Um pintor com 40 anos foi exposto acidentalmente à cal de pintura em ambos os olhos. Após lavagem dos olhos com água corrente, o trabalhador relata dor, sensação de “areia” nos olhos e visão embaçada.\nQual é a conduta imediata adequada para esse paciente?","options":{"A":"Aplicação de colírio lubrificante e repouso domiciliar.","B":"Avaliação por médico oftalmologista em pronto-socorro.","C":"Oclusão prolongada de ambos os olhos com gaze úmida.","D":"Avaliação e acompanhamento pelo médico na unidade básica de saúde."},"answer":"B","area":"Oftalmologia","assunto":"Traumatismos Oculares","topico":"Queimaduras Químicas Oculares","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1"},{"id":"revalida-2024-1-083","number":83,"stem":"Um recém-nascido, com peso de nascimento de 2.900 g, nascido a termo e de parto vaginal, é levado à primeira consulta pós-natal na unidade básica de saúde com 10 dias de vida. Durante a consulta, observa-se abundante quantidade de secreção purulenta em ambos os olhos da criança e, segundo a mãe, essa secreção teve início há 2 dias, formando-se rapidamente, mesmo após a limpeza. O paciente apresenta, também, hiperemia ocular e edema bipalpebral. Sabe-se que a mãe iniciou tardiamente o pré-natal e fez acompanhamento irregular, e ela refere que, atualmente, está apresentando leucorreia purulenta. O médico, então, solicita swab da secreção, cujo resultado chegará em até 5 dias.\nCom base nessas informações, quais são, respectivamente, o diagnóstico da doença da criança e a conduta médica adequada para o caso?","options":{"A":"Conjuntivite gonocócica; tratar a criança com colírio antibiótico após receber o resultado do swab, já que não há risco de perda da visão.","B":"Conjuntivite bacteriana; orientar a mãe do paciente, realizar limpeza dos olhos e iniciar o uso do colírio antibiótico, mesmo sem o resultado do swab.","C":"Conjuntivite bacteriana; orientar a mãe do paciente, realizar limpeza dos olhos e aguardar o resultado do swab para prescrever colírio antibiótico específico.","D":"Conjuntivite gonocócica; iniciar, mesmo sem o resultado do swab, o tratamento com colírio antibiótico e com ceftriaxona IM, já que há risco de perda da visão."},"answer":"D","area":"Pediatria","assunto":"Neonatologia","topico":"Cuidados neonatais","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Cuidados pós-natais"},{"id":"revalida-2024-1-088","number":88,"stem":"Um lactente com 5 meses é levado à emergência por seus pais com quadro de rinorreia hialina, tosse leve e febre baixa (37,9 °C) de início há 24 horas. Eles relatam que, há algumas horas, o bebê passou a apresentar rouquidão, tosse persistente e ruídos inspiratórios mesmo em repouso.\n\nAo exame físico, constata-se que a criança está agitada, com desconforto respiratório, com tiragem intercostal discreta e com estridor inspiratório. Sua frequência cardíaca é de 110 bpm, sua frequência respiratória é de 42 irpm e sua saturação de O2 é de 96% em ar ambiente. Durante a ausculta, nota-se boa entrada de ar bilateralmente. A expansibilidade torácica está preservada. Observa-se, entretanto, cianose quando a criança fica muito agitada.\n\nDiante dessas informações, a conduta médica adequada é prescrever","options":{"A":"corticoide oral e nebulização com agonistas beta-2 e realizar internação hospitalar do paciente.","B":"corticoide parenteral e nebulização com adrenalina e realizar internação hospitalar do paciente.","C":"corticoide parenteral, realizar intubação orotraqueal no paciente e proceder à internação hospitalar.","D":"corticoide inalatório, dar alta ao paciente e orientar seu retorno caso não melhore em 48 horas ou piore."},"answer":"B","area":"Pediatria","assunto":"Emergências Pediátricas","topico":"Corpo Estranho/Engasgo","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Tratamento"},{"id":"revalida-2024-1-089","number":89,"stem":"Uma mulher com 26 anos obteve o diagnóstico citológico de lesão intraepitelial de baixo grau (LSIL) no exame de Papanicolaou. Constata-se que a paciente tomou apenas uma dose da vacina contra o HPV na adolescência e iniciou a atividade sexual há 6 meses com parceiro único e sem uso de preservativo.\n\nPara melhor condução do caso, de acordo com o estabelecido pelo Ministério da Saúde/INCA, o profissional deve","options":{"A":"fazerespesquisadeDNA-HPV.","B":"repetir a citologia em 6 meses.","C":"indicar biópsia do colo uterino.","D":"solicitar colposcopia e \"ver e tratar\"."},"answer":"B","area":"Ginecologia","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Diretrizes para o rastreamento"},{"id":"revalida-2024-1-053","number":53,"stem":"Um paciente com Trissomia do 21 (T21) é atendido na unidade básica de saúde para realizar puericultura no 7.º mês de vida. Sua genitora apresenta alguns exames que são registrados no prontuário: ecocardiograma realizado ao nascimento sem qualquer alteração; e hemograma e dosagem dos hormônios tireoidianos solicitados na consulta do 6.º mês, que apresentam valores dentro das referências para a idade.\nAo exame físico, observa-se, além das características fenotípicas do paciente, apenas hipotonia global e instabilidade do quadril.\nNesse caso, de acordo com o que as diretrizes de acompanhamento ao paciente com T21 recomendam, qual é a conduta médica adequada?","options":{"A":"Repetir o ecocardiograma e realizar consulta com um cardiologista pediátrico.","B":"Fazer ultrassonografia do quadril e orientar acompanhamento com ortopedista pediátrico.","C":"Realizar ultrassonografia da tireoide e fazer acompanhamento com endocrinologista pediátrico.","D":"Coletar hemograma mensalmente e realizar acompanhamento com um hematologista pediátrico."},"answer":"B","area":"Pediatria","assunto":"Neonatologia","topico":"Principais síndromes genéticas e neonatais","annulled":false,"images":[],"source":"Revalida INEP 2024.1","examId":"revalida-2024-1","examName":"Revalida INEP: 2024.1","subtopico":"Síndrome de Down"},{"id":"revalida-2023-2-003","number":3,"stem":"Um menino de 9 anos, com peso de 29 kg e altura de 1,36 m, recém-adotado, comparece à primeira consulta de rotina com a família atual. Seus pais questionam o médico sobre a forma mais segura de transportar o filho na parte central do banco traseiro do automóvel, a fim de zelar por sua integridade física em caso de acidente.\n\nEm resposta ao questionamento dos pais, o médico deve orientar que a forma mais segura de transportar a criança é de frente para o painel do veículo,","options":{"A":"no banco, utilizando o cinto de segurança de três pontos do veículo.","B":"na cadeirinha, utilizando o cinto de segurança da própria cadeirinha.","C":"na cadeirinha, utilizando o cinto de segurança de três pontos do veículo.","D":"no assento de elevação, utilizando o cinto de segurança de três pontos do veículo."},"answer":"D","area":"Pediatria","assunto":"Puericultura ","topico":"Segurança das crianças e adolescentes","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Segurança no transporte"},{"id":"revalida-2023-2-007","number":7,"stem":"Os plantonistas do serviço de atendimento pré-hospitalar socorrem um rapaz de 18 anos, que foi atropelado por carro ao atravessar uma rodovia, e o levam até a emergência hospitalar para continuidade do atendimento. Após estabilização hemodinâmica e realização de exames complementares, é diagnosticada fratura de pelve anterior e posterior e, no exame físico, observa-se hematoma perineal e sangue no óstio externo da uretra.\nNesse caso, para confirmar o diagnóstico de lesão uretral total associada, é indicado realizar uma","options":{"A":"uretrocistografia retrógrada.","B":"cateterização suprapúbica.","C":"cateterização uretral.","D":"tomografia pélvica."},"answer":"A","area":"Cirurgia Geral","assunto":"Trauma","topico":"Trauma Abdominal e Pélvico","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Traumatismo Urológico"},{"id":"revalida-2023-2-011","number":11,"stem":"Um médico é chamado para avaliar um homem internado por pancreatite aguda biliar. Ao chegar ao posto de enfermagem, a técnica narra que o paciente começou a se queixar de “uma cãibra” na mão, enquanto ela estava começando a desinflar o manguito do esfignomanômetro. O paciente queixa-se de parestesias periorais e nas extremidades. Ao exame, o paciente está angustiado e sudorético, com os sinais vitais inalterados e com glicemia capilar de 138 mg/dL. O médico, então, pede um manguito, infla a bolsa durante 3 minutos acima da pressão sistólica e observa a mão contraturada. Depois, percute o nervo facial e observa contração dos músculos perilabiais ipsilateralmente. Diante disso, ele solicita um eletrocardiograma e constata que o intervalo QTc está aumentado.\n\nConsiderando o caso clínico apresentado, assinale a opção que descreve a hipótese clínica correta para explicar o cenário e as alterações descritos.","options":{"A":"Hipocalemia.","B":"Hiperglicemia.","C":"Hipocalcemia.","D":"Hipercalcemia."},"answer":"C","area":"Nefrologia","assunto":"Controle da água corporal total","topico":"Osmolaridade","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-020","number":20,"stem":"O prefeito de um município brasileiro deseja implantar as Práticas Integrativas e Complementares (PICS) em sua cidade, para que os cidadãos tenham acesso a sessões de auriculoterapia, musicoterapia, entre outras PICS.\n\nSobre as orientações expressas no referido programa do Sistema Único de Saúde (SUS), é correto afirmar que","options":{"A":"a acupuntura deve ser ofertada pela atenção especializada, com a acesso regulado para pacientes atendidos pela atenção primária.","B":"as PICS são recomendadas pela Organização Mundial da Saúde (OMS), que regula quais destas práticas integrativas podem ser implementadas.","C":"as ações das PICS devem ter caráter multiprofissional, com a adoção de práticas que se adequem ao nível de atenção no qual estejam implementadas.","D":"a auriculoterapia deve ser inserida em todos os níveis de atenção em saúde, com ênfase na atenção terciária, pois nesta, apresenta melhores resultados."},"answer":"C","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Políticas de Saúde do Sistema Único de Saúde","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Política Nacional de Práticas Integrativas e Complementares "},{"id":"revalida-2023-2-023","number":23,"stem":"A redução da mortalidade infantil é ainda um desafio para os serviços de saúde e para a sociedade como um todo. Ela faz parte das metas do desenvolvimento do milênio, as quais representam um compromisso assumido pelos países integrantes da Organização das Nações Unidas (ONU), do qual o Brasil é signatário. A respeito dos indicadores da mortalidade infantil no Brasil, as causas dos óbitos são classificadas em: evitáveis, não evitáveis, mal definidas e não classificadas.\nAcerca desse assunto, assinale a opção que apresenta apenas causas consideradas evitáveis.","options":{"A":"Sífilis congênita; desnutrição; asfixia ao nascer.","B":"Sarampo; desnutrição; malformações congênitas do sistema nervoso.","C":"Tuberculose; anemias carenciais; síndrome da morte súbita do recém-nascido.","D":"Síndrome da rubéola congênita; traumatismo de parto; doenças desmielinizantes."},"answer":"A","area":"Medicina Preventiva","assunto":"Epidemiologia","topico":"Medidas de saúde coletiva","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Indicadores especiais de mortalidade"},{"id":"revalida-2023-2-027","number":27,"stem":"Um homem de 58 anos, trabalhador na construção civil, procura o ambulatório com história clínica de lesão na face há, aproximadamente, 4 anos, com crescimento há 2 meses, conforme figura a seguir. Ele nega outras lesões cutâneas ou outras comorbidades. O exame físico se mostrou sem alterações. Figura — Lesão cutânea. A partir dessas informações, qual é a hipótese diagnóstica mais provável?","options":{"A":"Melanoma.","B":"Nevo melanocítico.","C":"Ceratose seborrérica.","D":"Carcinoma espinocelular."},"answer":"D","area":"Dermatologia","assunto":"Câncer de pele","topico":"Carcinoma espinocelular e lesões pré-malignas","annulled":false,"images":["assets/revalida/img/revalida-2023-2-027-1.png"],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-028","number":28,"stem":"Um lactente de 3 meses e 3 semanas, nascido a termo, previamente hígido e sem intercorrências no pré-natal, encontra-se em consulta de rotina em unidade básica de saúde e sua mãe refere que retornará ao trabalho em uma semana. Em função disso, o paciente ficará sem receber o leite materno das 8 às 20 horas a partir da semana seguinte. Considerando a impossibilidade de armazenamento de leite materno pela mãe e a Lei n. 11 265/2006, que regulamenta a comercialização de alimentos para lactentes e para crianças de primeira infância e os produtos de puericultura correlatos, assinale a opção que apresenta a alimentação que satisfará corretamente as necessidades nutricionais desse paciente a partir da ausência materna.","options":{"A":"Fórmula infantil para lactentes, sem introdução de alimentação complementar.","B":"Fórmula infantil de seguimento para lactentes, sem introdução de alimentação complementar.","C":"Fórmula infantil para lactentes, com introdução, também, de papas de fruta, de legumes e de carne.","D":"Fórmula infantil de seguimento para lactentes, com introdução, também, de papas de fruta, de legumes e de carne."},"answer":"A","area":"Pediatria","assunto":"Puericultura ","topico":"Amamentação/ Aleitamento Materno","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Tipos de aleitamento materno"},{"id":"revalida-2023-2-034","number":34,"stem":"Uma mulher de 28 anos comparece à consulta médica para apresentar o resultado de colpocitologia oncótica colhida há 10 dias. Relata que faz o exame regularmente e nega alterações em resultados anteriores. Apresenta história de dois partos vaginais anteriores e de laqueadura tubária. O laudo de seu exame descreve amostra satisfatória, flora com Lactobacillus sp, achados de coilocitose e conclusão de lesão intraepitelial de baixo grau.\n\nNesse caso, a conduta médica correta é realizar","options":{"A":"coleta de colpocitologia oncótica após 6 meses.","B":"colposcopia e biópsia do colo do útero.","C":"exérese da zona de transformação.","D":"coleta para o teste de DNA-HPV."},"answer":"A","area":"Ginecologia","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Diretrizes para o rastreamento"},{"id":"revalida-2023-2-046","number":46,"stem":"Uma adolescente de 14 anos procura uma unidade básica de saúde com queixa de cefaleia. Ela conta que, durante a prova de matemática, apresentou dificuldade para enxergar os enunciados; ela descreve que via “imagens brilhantes” e que, a seguir, a visão dela ficou como uma mancha escura e passou a ter dor de cabeça. Depois de 30 minutos, a visão se normalizou. A menina tentou continuar a prova, mas a dor na lateral da cabeça começou a latejar e piorou. Em seguida, teve vontade de vomitar e precisou sair da sala às pressas. Ela diz que nunca teve isso antes e que os sons mais fortes estão muito desconfortáveis. A paciente nega o uso de anticoncepcional oral. Ao exame físico, está pálida, sudoréica, nauseada e com dor. Com relação aos sinais vitais, apresenta pressão arterial de 110 × 70 mmHg; frequência cardíaca de 90 batimentos por minuto; frequência respiratória de 14 incursões respiratórias por minuto; e temperatura axilar de 36,9 °C. Não há sinais neurológicos focais, nem sinais meníngeos, e o exame de fundo de olho revela pulso venoso espontâneo presente.\n\nEm relação ao quadro clínico apresentado, a hipótese mais provável é de cefaleia causada por","options":{"A":"tumor cerebral, havendo indicação de exame de imagem com urgência.","B":"hemicrania com aura, havendo indicação de tratamento sintomático e acompanhamento.","C":"hemorragia subaracnóidea, havendo indicação de acionar o serviço médico de emergência.","D":"hipertensão intracraniana, havendo indicação de encaminhamento urgente para serviço de emergência."},"answer":"B","area":"Neurologia","assunto":"Cefaleias","topico":"Cefaleias Primárias","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-047","number":47,"stem":"Uma paciente de 40 anos, cosmetologista, is trazida ao pronto-socorro com relato de exposição acidental de olho esquerdo a ácido tricloroacético durante a realização de procedimento dermatológico ambulatorial, há 1 hora.\n\nA conduta terapêutica inicial adequada para essa paciente é realizar","options":{"A":"oclusão do olho esquerdo com gaze umedecida.","B":"aplicação de pomada de corticoide no olho afetado.","C":"instilação do olho afetado como lidocaína líquida a 2%.","D":"irrigação abundante do olho afetado com solução cristaloide."},"answer":"D","area":"Oftalmologia","assunto":"Traumatismos Oculares","topico":"Queimaduras Químicas Oculares","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-048","number":48,"stem":"Um menino de 9 anos, sem comorbidades, é levado pela mãe à consulta ambulatorial por apresentar baixa estatura. A mãe refere que seu filho é o mais baixo entre os colegas da sala de aula. Na avaliação antropométrica, evidencia-se que o paciente apresenta mais de 3 desvios-padrão (escore Z: -3) da curva de altura/idade e escore Z=0 para peso/altura da Organização Mundial de Saúde. Demais aspectos do exame físico sem alterações. Foram realizados dois testes provocativos da secreção de hormônio de crescimento (GH), com resultados de 4,2 e 4,3 mcg/dL respectivamente (Valor de referência de GH > 5mcg/L).\n\nCom base nesse achado, o diagnóstico etiológico mais provável da baixa estatura, é","options":{"A":"hipotireoidismo.","B":"deficiência de GH.","C":"má absorção de nutrientes.","D":"baixa estatura constitucional."},"answer":"B","area":"Pediatria","assunto":"Puericultura ","topico":"Crescimento","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Crescimento  Anormal"},{"id":"revalida-2023-2-055","number":55,"stem":"Observe a imagem a seguir.\n\n[Charge retratando uma longa fila de pacientes aguardando atendimento em uma unidade de saúde com cartazes do SUS, onde um paciente reclama que vai ser atendido e prova que está doente, enquanto outro aponta que nem tem nada e está na fila do SUS]\n\nEm relação aos pressupostos e às características do Sistema Único de Saúde (SUS) e da Atenção Primária em Saúde (APS), a charge apresentada está relacionada a problemas de\n\nA descentralização e de hierarquização, uma vez que muitas pessoas gostariam de ser atendidas ao mesmo tempo, em um só lugar.\nB acessibilidade e de gestão, uma vez que o subfinanciamento e o subgerenciamento podem explicar as longas filas para acesso ao sistema.\nC resolubilidade e de integralidade, uma vez que os pacientes a serem atendidos primeiro terão maior chance de terem seus problemas resolvidos.\nD universalidade e de coordenação do cuidado, uma vez que o paciente “menos doente” ou com menores necessidades de cuidados está no final da fila.","options":{"A":"descentralização e de hierarquização, uma vez que muitas pessoas gostariam de ser atendidas ao mesmo tempo, em um só lugar.","B":"acessibilidade e de gestão, uma vez que o subfinanciamento e o subgerenciamento podem explicar as longas filas para acesso ao sistema.","C":"resolubilidade e de integralidade, uma vez que os pacientes a serem atendidos primeiro terão maior chance de terem seus problemas resolvidos.","D":"universalidade e de coordenação do cuidado, uma vez que o paciente “menos doente” ou com menores necessidades de cuidados está no final da fila."},"answer":"D","area":"Medicina Preventiva","assunto":"Sistema Único de Saúde (SUS)","topico":"Princípios e Diretrizes do Sistema Único de Saúde (SUS)","annulled":false,"images":["assets/revalida/img/revalida-2023-2-055-1.png"],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Princípios e Diretrizes do SUS na Lei nº 8.080/1990"},{"id":"revalida-2023-2-058","number":58,"stem":"Um neonato de 48 horas de vida, do sexo masculino, nascido com peso de 2 870 g, estatura de 47 cm e Apgar de 7/8, recebendo aleitamento materno exclusivo, encontra-se no alojamento conjunto, onde toda a equipe é capaz de verificar as seguintes alterações: pregas palpebrais oblíquas para cima, epicanto, protrusão lingual, palato ogival, retrognatia, pavilhão auricular pequeno de implantação baixa, braquidactilia, prega palmar única transversa, discreta hipotonia, frouxidão ligamentar, excesso de tecido adiposo no dorso do pescoço e diástase dos músculos dos retos abdominais.\n\nNesse caso, a conduta médica a ser empregada imediatamente é solicitar","options":{"A":"seriografia de esófago gastroduodenal para excluir anomalias congênitas do arco duodenal.","B":"radiografia de tórax, eletrocardiograma e ecocardiograma, devido ao risco aumentado de cardiopatias congênitas.","C":"teste do pezinho para investigação de hipertireoidismo, que é a patologia tireoidiana encontrada com mais frequência.","D":"radiografia de coluna cervical nas incidências em perfil, com flexão e extensão, para pesquisa de instabilidade atlantoaxial."},"answer":"B","area":"Pediatria","assunto":"Neonatologia","topico":"Principais síndromes genéticas e neonatais","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Síndrome de Down"},{"id":"revalida-2023-2-067","number":67,"stem":"Um paciente de 16 anos, vítima de acidente automobilístico, chega ao pronto-socorro com escoriação extensa em parede torácica anterior, murmúrio vesicular fisiológico e simétrico, bulhas cardíacas hipofonéticas, frequência cardíaca de 48 batimentos por minuto, pressão arterial de 80 × 40 mmHg e turgência bilateral de jugulares. O paciente sofre uma parada cardiorrespiratória logo após a admissão.\n\nCom relação ao quadro desse paciente, a conduta médica adequada é realizar","options":{"A":"toracotomia e massagem cardíaca interna.","B":"massagem cardíaca externa.","C":"toracostomia bilateral.","D":"pericardiocentese."},"answer":"A","area":"Cirurgia Geral","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Trauma Torácico"},{"id":"revalida-2023-2-071","number":71,"stem":"Um homem de 68 anos retorna do ambulatório de referência devido a dores em coluna torácica e em lombar, de intensidade progressivamente maior nos últimos 3 meses. Os exames realizados apresentaram os seguintes resultados: Hemoglobina 7,5 g/dL; Hematócrito 23%; Leucócitos totais 8.000 mm3; Proteínas totais 9,4 g/dL; Albumina 2,2 g/dL; Cálcio sérico 12,3 mg/dL; Creatinina 1,4 mg/dL; Imunoeletroforese de proteínas – banda monoclonal de imunoglobulina (Ig): IgA 5.200 mg/dL, IgG 180 mg/dL, IgM 100 mg/dL. A radiografia de coluna vertebral mostrou lesões osteolíticas e fraturas vertebrais em T11, T12, L1 e L2. Nas últimas 2 semanas, o paciente apresenta-se excessivamente sonolento. Considerando essas informações, a hipótese diagnóstica e o exame mais adequado para confirmá-la são, respectivamente,","options":{"A":"anemia falciforme; eletroforese de hemoglobina.","B":"linfoma; biópsia de linfonodos abdominais.","C":"hiperparatireoidismo; paratormônio (PTH).","D":"mieloma múltiplo; mielograma."},"answer":"D","area":"Hematologia","assunto":"Gamopatias monoclonais","topico":"Mieloma múltiplo (MM)","annulled":false,"images":["assets/revalida/img/revalida-2023-2-071-1.png"],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-2-073","number":73,"stem":"Um menino de 9 anos sofre atropelamento enquanto andava de bicicleta pela rua e é trazido, por pessoas que estavam presentes no momento do acidente, à emergência do hospital. À admissão, o menino encontra-se em parada cardiorrespiratória em assistolia. Ao perceber o quadro do paciente, os médicos de plantão iniciam medidas de suporte avançado de vida para essa criança, instituindo, inicialmente, via aérea avançada com sucesso. Diante dessa situação, quais medidas devem ser tomadas imediatamente?","options":{"A":"Manter as compressões torácicas e realizar uma ventilação a cada 2 a 3 segundos.","B":"Manter compressões torácicas na frequência de 15 compressões e de 2 ventilações.","C":"Administrar cristaloides para o paciente, visto que se trata de um choque hemorrágico.","D":"Administrar epinefrina para o paciente, visto que não houve retorno da circulação espontânea."},"answer":"D","area":"Pediatria","assunto":"Emergências Pediátricas","topico":"Emergências Pediátricas: Parada Cardiorrespiratória (PCR) e Arritmias na Emergência","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Suporte Avançado de Vida"},{"id":"revalida-2023-2-078","number":78,"stem":"Um recém-nascido a termo, adequado para a idade gestacional, evoluiu sem eliminação de mecônio nas primeiras 48 horas de vida. Depois, desenvolveu quadro de vômitos, apresentando hipoatividade, com recusa ao seio materno e distensão abdominal. Ao exame físico, encontra-se desidratado, descorado, com abdome distendido e doloroso, com ruídos hidroaéreos diminuídos. Ao toque retal, nota-se ânus sem alterações, com eliminação de mecônio em grande quantidade. Foi realizada radiografia de abdome, exibida a seguir.\n\nCom base no caso apresentado e na imagem radiológica, assinale a propedêutica correta.","options":{"A":"A colonoscopia sem biópsia de urgência é indicada para confirmação diagnóstica.","B":"O sinal da dupla bolha presente na radiografia simples de abdome sugere o diagnóstico.","C":"O exame clínico detalhado, associado à ultrassonografia abdominal confirma o diagnóstico.","D":"O enema opaco com retenção do bário, de 24 a 36 horas após o exame, sugere o diagnóstico."},"answer":"D","area":"Cirurgia Geral","assunto":"Cirurgia Infantil","topico":"Doença de Hirschsprung","annulled":false,"images":["assets/revalida/img/revalida-2023-2-078-1.png"],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2","subtopico":"Diagnóstico"},{"id":"revalida-2023-2-090","number":90,"stem":"Uma mulher de 46 anos, trabalhadora doméstica, apresenta-se ao médico com queixa de lombalgia há 1 semana, com intensidade de 5 em 10 na escala numérica da dor, de caráter contínuo e não irradiado. Ela já apresentou quadro semelhante antes e possui indicação de uso de relaxante muscular. Diante desse quadro, quais são, respectivamente, a hipótese diagnóstica mais provável e a conduta médica adequada?","options":{"A":"Lombalgia de origem mecânico-postural; iniciar tratamento conservador.","B":"Lombalgia inespecífica; dispensar investigação com exames complementares.","C":"Lombalgia com sinais de alerta; solicitar ressonância magnética da coluna lombossacra.","D":"Lombalgia inespecífica; indicar repouso e prescrever paracetamol ou anti-inflamatório não esteroidal."},"answer":"A","area":"Ortopedia","assunto":"Ortopedia Geral","topico":"Doenças da coluna vertebral","annulled":false,"images":[],"source":"Revalida INEP 2023.2","examId":"revalida-2023-2","examName":"Revalida INEP: 2023.2"},{"id":"revalida-2023-1-007","number":7,"stem":"Um paciente de 55 anos, obeso, tabagista, foi internado no serviço de urologia. Apresentava hematúria franca, tendo sido submetido a cistoscopia com ressecção transuretral de lesões. O laudo anatomopatológico revelou a ressecção de 3 lesões tumorais superficiais, limitadas ao revestimento da bexiga, compatíveis com carcinoma de células transicionais de alto grau, além de ausência de invasão muscular. A pesquisa realizada por meio de ultrassonografia não demonstrou acometimento de linfonodos locais.\n\nNessa situação, qual conduta deve ser adotada para o caso?","options":{"A":"Solicitar cistectomia total.","B":"Indicar tratamento intravesical com BCG.","C":"Indicar tratamento com dose única de mitomicina.","D":"Solicitar cistoscopia com nova ressecção trimestral."},"answer":"B","area":"Cirurgia Geral","assunto":"Urologia","topico":"Neoplasias Urológicas","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Câncer de Bexiga"},{"id":"revalida-2023-1-008","number":8,"stem":"Um recém-nascido a termo recebeu alta com orientações gerais, mas retornou para avaliação após 72 horas. A mãe relata que, embora ele estivesse bem, estava preocupada, pois achava que o “amarelão” estava ficando cada vez mais acentuado. Na avaliação médica, observou-se icterícia (3+/4+), Zona 4 de Kramer. A criança foi internada e foram solicitados exames laboratoriais. A bilirrubina total era de 25,6 mg/dL às custas da fração de bilirrubina indireta. Não havia histórico de incompatibilidade ABO ou Rh.\n\nConsiderando o caso clínico, assinale a opção que apresenta, corretamente, a causa de hiperbilirrubinemia indireta neonatal associada à sua fisiopatologia, a avaliação complementar de diagnóstico e a conduta imediata, respectivamente.","options":{"A":"Alfatalassemia (doença hemolítica); teste do pezinho; fototerapia.","B":"Hipotireoidismo (policitemia); dosagem de hormônio tireoidiano; exsanguíneo transfusão.","C":"Síndrome de Crigler Najjar (doença hemolítica); teste do pezinho; exsanguíneo transfusão.","D":"Estenose hipertrófica de piloro (coleção sanguínea extravascular); ultrassonografia abdominal; fototerapia."},"answer":"A","area":"Pediatria","assunto":"Neonatologia","topico":"Icterícia nenonatal e distúrbios hematológicos no RN","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Icterícia neonatal"},{"id":"revalida-2023-1-013","number":13,"stem":"Um recém-nascido de 12 dias de vida foi levado à unidade de pronto-socorro por apresentar vômitos, anorexia, irritabilidade, desconforto respiratório e convulsões. O hemograma completo mostrou anemia. A análise do líquido cefalorraquidiano mostrou pleocitose discreta com predomínio de células mononucleares, hiperproteinorraquia e glicorraquia normal. Na admissão, ainda em crise convulsiva, foi medicado com fenobarbital, com dose de ataque de 20 mg/kg, porém permaneceu com crises epilépticas subentrantes.\nConsiderando-se como a principal etiologia uma infecção do sistema nervoso central, para o manejo da condição apresentada pelo paciente deverá ser administrado","options":{"A":"diazepam, fenitoína, tiopental.","B":"fenitoína, midazolam, tiopental.","C":"fenitoína, lorazepam, piridoxina.","D":"nitrazepam, fenitoína, piridoxina."},"answer":"C","area":"Pediatria","assunto":"Emergências Pediátricas","topico":"Convulsão febril ","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Abordagem da Crise Febril"},{"id":"revalida-2023-1-016","number":16,"stem":"Uma paciente com 40 anos, branca, encaminhada da unidade básica de saúde, é atendida para investigação de trombose venosa profunda (TVP). Conta que apresentou um segundo episódio de TVP do membro inferior esquerdo há 3 dias. Informa que faz uso de anticoncepcional oral desde os 18 anos e que a primeira TVP ocorreu aos 36 anos, quando foi tratada com varfarina por 6 meses, sem intercorrências. Conta que teve 3 gestações, a primeira delas, aos 22 anos, resultou em um aborto espontâneo, as outras 2 foram a termo. Ela informa ainda que sua mãe também já apresentou TVP. Relata também que atualmente vem fazendo uso de rivaroxabana.\n\nPara investigação de TVP na paciente nesse momento, deve-se solicitar","options":{"A":"anticorpos anti-beta-2 glicoproteina 1 IgG e IgM.","B":"anticorpos anticardiolipina IgG e IgM.","C":"proteína C e proteína S livre.","D":"PCR para fator V Leiden."},"answer":"D","area":"Hematologia","assunto":"Hemostasia","topico":"Trombofilia","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1"},{"id":"revalida-2023-1-024","number":24,"stem":"Uma paciente com 29 anos, nuligesta, sexualmente ativa, foi submetida a exame citopatológico em uma unidade básica de saúde. Exame anterior realizado há 1 ano não apresentava alterações. O exame atual apresentou o seguinte resultado: metaplasia escamosa, alterações inflamatórias moderadas, presença de bacilos de Doderlein.\n\nNesse caso, a paciente deve ser orientada a","options":{"A":"cauterizar colo uterino.","B":"repetir citologia em 3 anos.","C":"repetir citologia em 6 meses.","D":"usar creme vaginal com metronidazol."},"answer":"B","area":"Ginecologia","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Diretrizes para o rastreamento"},{"id":"revalida-2023-1-035","number":35,"stem":"Um paciente com 68 anos, branco, previamente hígido, é atendido em consulta agendada na atenção primária, com diagnóstico recente de hipertensão arterial estágio 2, sem comorbidades. Seus exames físico e laboratoriais não mostram lesões de órgãos-alvo. O paciente relata não fazer uso de medicamentos e foi classificado como portador de fragilidade leve pela escala de fragilidade clínica, apresentando risco cardiovascular baixo pelo escore global de risco. No projeto terapêutico para esse paciente, além da mudança de estilo de vida, incluem-se terapêutica medicamentosa e metas da pressão arterial (PA) e de seguimento mais adequadas.\n\nNesse contexto, a conduta recomendada é iniciar","options":{"A":"tratamento não medicamentoso, para se atingir a meta pressórica (pressão arterial sistólica de 130 a 139 mmHg e pressão arterial diastólica de 70 a 79 mmHg) por um período de 3 a 6 meses.","B":"terapia medicamentosa com bloqueador do canal de cálcio associado a inibidor da enzima conversora da angiotensina em doses baixas e marcar retorno em até 30 dias, para aferir se a meta pressórica (PA menor que 140 × 90 mmHg) foi atingida.","C":"monoterapia com espironolactona, metildopa ou clonidina, marcando retorno em até 30 dias, para aferir se a meta pressórica (pressão arterial sistólica de 130 a 139 mmHg e pressão arterial diastólica de 70 a 79 mmHg) foi atingida.","D":"uso de betabloqueador, em monoterapia ou associado a diurético em baixa dose, reforçando mudança de estilo de vida e recomendando consultas anuais no caso de a meta pressórica (PA menor que 140 × 90 mmHg) ter sido atingida."},"answer":"B","area":"Cardiologia","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Diagnóstico e classificação ","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1"},{"id":"revalida-2023-1-038","number":38,"stem":"Retorna a maternidade um recém-nascido com 3 dias, conforme sua ficha, ele nasceu com 37 semanas de gestação por parto cesáreo devido à restrição de crescimento intrauterino e centralização fetal, pesando 1.950 gramas, Apgar 8/9 e com bolsa rota no ato. A mãe relata ter 34 anos, que não houve intercorrências na gestação, que as sorologias do pré-natal apresentaram-se não reagentes, que foi feito o teste da orelhinha no recém-nascido e que os olhos e o coração dele se apresentaram sem alterações. Acrescenta que seu filho recebeu alta da maternidade com 24 horas de vida. Ao exame físico, a criança apresenta um peso de 1.850 gramas, estatura de 44 cm, perímetro cefálico de 27 cm e mostra-se ativo, reativo, algo irritado, ictérico, notando-se a presença de petéquias na pele; abdome com fígado palpável a 5 cm e baço a 2 cm do rebordo costal, não havendo alterações no restante do exame. O hemograma apresenta anemia, leucopenia e plaquetopenia; também hiperbilirrubinemia às custas principalmente de elevação de bilirrubinas diretas; transaminases 4 vezes acima dos valores de referência e ultrassom de crânio com leucomalácia periventricular e calcificações periventriculares. \n\nConsiderando-se esses dados, quais são, respectivamente, a hipótese diagnóstica e o manejo adequado para o caso?","options":{"A":"Sífilis congênita; uso de penicilina cristalina por 10 dias, avaliação neurológica, oftalmológica e fonoaudiológica.","B":"Citomegalovirose; uso de aciclovir por 2 meses, acompanhamento mensal com pediatra na unidade básica de saúde.","C":"Sífilis congênita; uso de penicilina procaína por 10 dias, seguimento mensal com pediatria na unidade básica de saúde.","D":"Citomegalovirose; uso de ganciclovir por 6 meses, acompanhamento auditivo com fonoaudiólogo e otorrinolaringologista."},"answer":"D","area":"Pediatria","assunto":"Neonatologia","topico":"Infecções congênitas","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Citomegalovírus"},{"id":"revalida-2023-1-039","number":39,"stem":"Uma paciente secundigesta, com 27 anos, foi encaminhada pela atenção primária de saúde ao ambulatório de gestação de alto risco para iniciar pré-natal, devido à história obstétrica anterior de pré-eclâmpsia leve e descolamento prematuro de placenta intraparto. Durante a consulta, evidenciou-se que a gestante se encontrava com 16 semanas de gestação, apresentando pressão arterial de 135 × 83 mmHg. Foi realizada a avaliação de proteinúria com fita, cujo resultado foi negativo.\n\nA conduta a ser imediatamente adotada, a fim de melhorar o prognóstico materno e perinatal dessa gestação, é a prescrição de","options":{"A":"hidralazina 25 mg, duas vezes ao dia, via oral.","B":"metildopa 250 mg, duas vezes ao dia, via oral.","C":"ácido acetilsalicílico 100 mg, uma vez ao dia, via oral.","D":"enoxparina 1 mg/kg, duas vezes ao dia, via subcutânea."},"answer":"C","area":"Obstetrícia","assunto":"Doenças associadas à gestação","topico":"Síndromes Hipertensivas da Gestação","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Predição e prevenção"},{"id":"revalida-2023-1-042","number":42,"stem":"Uma paciente com 30 anos, grávida de 34 semanas, sofreu colisão frontal auto vs anteparo (muro), sentada no banco do passageiro e sem uso de cinto de segurança. Foi atendida por equipe de emergência pré-hospitalar, com relato de parada cardíaca e manobras de reanimação por cerca de 5 minutos, sem sucesso, durante sua remoção até o pronto-socorro de um hospital. Foi admitida pelo cirurgião geral, em parada cardiorrespiratória e midríase paralítica bilateral, com hematoma volumoso em região frontal.\n\nNesse caso, qual deve ser a conduta do profissional que realiza o atendimento?","options":{"A":"Considerar morte materno-fetal.","B":"Realizar cirurgia cesariana de urgência.","C":"Encaminhar a paciente para a gineco-obstetra.","D":"Solicitar ultrassonografia, para a avaliação do feto."},"answer":"B","area":"Cardiologia","assunto":"Arritmias Cardíacas","topico":"Abordagem do paciente em parada cardiorrespiratória (PCR)","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1"},{"id":"revalida-2023-1-047","number":47,"stem":"Uma paciente com 40 anos, índice de massa corpórea de 38kg/m2, com história de colelitíase sintomática há 2 anos, apresenta-se para cirurgia de colecistectomia videolaparoscópica. Os resultados de seus exames laboratoriais são normais e a ultrassonografia de abdome mostra múltiplos cálculos em vesícula biliar. É realizada a operação, descrita como tecnicamente difícil em razão da obesidade e das aderências inflamatórias no leito vesicular. A paciente foi encaminhada à enfermaria, acordada e sem queixas. Foram reiniciadas dieta e deambulação nas primeiras 24 horas de pós-operatório. Após 36 horas de pós-operatório, apresentou pico febril de 39 °C, dor abdominal e discreta icterícia. Novos exames laboratoriais mostraram leucograma de 20.500 leucócitos com 8% bastões, bilirrubina direta 2,0 mg/dL, bilirrubina indireta 1,0 mg/dL, aspartatoaminotransferase 60 U/L, alanina aminotransferase 80 U/L, fosfatase alcalina 230 U/L e gamaglutamiltransferase 450 U/L. A paciente evoluiu, em 4 horas, com hipotensão, prostração e queda do estado geral. \nAcerca desse quadro clínico, assinale a opção correta.","options":{"A":"A incidência de lesão de via biliar na via videolaparoscópica é menor que na cirurgia aberta, por ser procedimento menos invasivo e proporcionar melhor e mais rápida recuperação; a complicação em curso pode ser sepse de origem pulmonar, pois a obesidade e a dor no pós-operatório facilitam restrição respiratória e infecção, devendo-se, portanto, iniciar antibioticoterapia de amplo espectro imediatamente.","B":"A colecistectomia aberta é a técnica recomendada para pacientes obesos, dado o risco de complicações; o quadro de possível fístula biliar deve ser tratado imediatamente com antibióticos e drenagem percutânea guiada por ultrassonografia, evitando-se nova abordagem e a possibilidade de ocorrência de danos secundários.","C":"A possibilidade de lesão de via biliar como complicação precisa ser informada à paciente e à sua família, devendo ser solicitada a transferência para um centro com unidade de terapia intensiva, tendo em vista suporte e antibioticoterapia de largo espectro, aguardando-se o esfriamento do processo para planejar a reabordagem.","D":"A possibilidade de lesão de via biliar como complicação precisa ser informada à paciente e à sua família, devendo ser solicitada a transferência para um centro com unidade de terapia intensiva e acesso a equipe especializada e a métodos diagnósticos, como a colangiorressonância magnética."},"answer":"D","area":"Cirurgia Geral","assunto":"Vesícula e Vias Biliares","topico":"Lesão da Via Biliar","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Tratamento"},{"id":"revalida-2023-1-048","number":48,"stem":"Ao fazer o histórico alimentar de uma criança de 12 meses com alergia ao leite de vaca, a pediatra ouve o seguinte relato da mãe da criança: “ao acordar ofereço um suco; no lanche do meio da manhã, dou fruta e castanhas; no almoço, ela come diariamente folhas, legumes cozidos e crus e, eventualmente, arroz e feijão; à tarde, ofereço um lanche com fruta, bolo ou biscoito; à noite, sopa de legumes acrescido de macarrão e azeite; e, antes de dormir, suco”.\nConsiderando-se o relato da mãe, qual grupo de nutrientes está deficiente na alimentação dessa lactente?","options":{"A":"Vitaminas.","B":"Gorduras.","C":"Carboidratos.","D":"Aminoácidos essenciais."},"answer":"D","area":"Pediatria","assunto":"Gastrologia Pediátrica","topico":"Alergia alimentar","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Alergia  à proteína do leite de vaca"},{"id":"revalida-2023-1-049","number":49,"stem":"A restrição de crescimento fetal intrauterino ocorre quando o feto não atinge o potencial de crescimento e desenvolvimento em decorrência de uma disfunção placentária. Isso ocorre em 5% a 10% das gestações e é a segunda causa mais frequente de mortalidade perinatal, responsável por cerca de 30% dos natimortos.\nCom relação ao rastreio, diagnóstico e manejo do crescimento fetal restrito, assinale a opção correta.","options":{"A":"O crescimento fetal restrito pode ser classificado como precoce quando ocorre antes de 35 semanas de gestação, e tardio, após esse período.","B":"A medida do fundo uterino entre a 24ª e a 38ª semanas de gestação tem sensibilidade e especificidade que permitem a detecção do crescimento intrauterino fetal restrito.","C":"Na avaliação do crescimento fetal restrito com dopplervelocimetria normal e líquido amniótico dentro do estimado para a idade gestacional, a resolução da gestação deve ser programada após a 40ª semana.","D":"O estágio 2 é quando o doppler das artérias uterinas apresenta diástole zero, havendo risco de óbito fetal, o que requer avaliação semanal do peso fetal e controle quinzenal da vitalidade até a 36ª semana."},"answer":null,"area":"Obstetrícia","assunto":"Medicina fetal","topico":"Restrição de crescimento fetal (RCF)","annulled":true,"annulledSource":"Gabarito definitivo Revalida 2023.1, questão 49 — https://download.inep.gov.br/revalida/provas_e_gabaritos/2023_1_GB_objetiva_definitivo.pdf","images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Classificação"},{"id":"revalida-2023-1-052","number":52,"stem":"Uma paciente com 70 anos, diabética, com dor em flanco esquerdo, de início insidioso e piora progressiva há 72 horas, chega ao pronto-socorro acompanhada de familiares. Eles relatam que, nos últimos 3 meses, observaram a ocorrência de episódios de sangramento retal vermelho-vivo, anorexia e perda ponderal de 10 Kg. Ao exame físico, a paciente apresenta-se em mau estado geral, torporosa, com frequência respiratória de 24 incursões respiratórias por minuto, frequência cardíaca de 116 batimentos por minuto, pressão arterial de 90 × 50 mmHg, abdome globoso, doloroso à palpação, com sinais de irritação peritoneal difusa. O resultado de radiografia simples evidencia pneumoperitôneo volumoso.\n\nApós discussão do caso com a família, deve ser proposto pelo cirurgião geral plantonista a realização de uma laparotomia, de uma","options":{"A":"enterectomia segmentar e de uma ileostomia.","B":"colectomia segmentar e de uma coloanastomose.","C":"limpeza e de uma drenagem da cavidade abdominal.","D":"colectomia segmentar e de uma colostomia de Hartmann."},"answer":"D","area":"Cirurgia Geral","assunto":"Urgências Abdominais","topico":"Abdome Agudo Perfurativo","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Outras Causas de Abdome Agudo Perfurativo"},{"id":"revalida-2023-1-080","number":80,"stem":"Uma criança com 8 anos chega, com sua mãe, à unidade de saúde da família com queixa de dispneia e sibilância há cerca de 2 horas. A criança tem histórico de asma, em acompanhamento na unidade, fazendo uso de beclometasona 200 mcg por dia. Quando questionada sobre o controle das crises da criança, a mãe refere que vinha usando salbutamol 100 mcg, 3 a 4 vezes por semana, devido a quadros de tosse seca e discreto desconforto respiratório. Relata que, hoje, porém, mesmo após 2 puffs de salbutamol, os sintomas apresentados pela criança estavam mais intensos e persistentes. A criança demonstra desconforto e agitação, com fala entrecortada, frequência respiratória de 32 incursões respiratórias por minuto, frequência cardíaca de 110 batimentos por minuto, saturação de O2 de 89% em ar ambiente, sibilos difusos e tiragem intercostal.","options":{"A":"indicar máscara de oxigênio, para manter saturação entre 93 e 95%, beta-2 agonista de curta duração inalatório 6 puffs, que poderá ser repetido a cada 20 minutos e, se necessário, brometo de ipratrópio e prednisolona 2-4 mg/kg, enquanto aguarda a remoção da criança para internação; e aumentar Beclometasona para 200 mcg 12/12h, mantendo o corticoide oral por 5 a 7 dias.","B":"indicar máscara de oxigênio, para manter saturação entre 94 e 98%, beta-2 agonista de curta duração inalatório 2 puffs, que poderá ser repetido a cada 20 minutos, brometo de ipratrópio e, se necessário, prednisolona 1-2 mg/kg, enquanto aguarda a remoção da criança para internação; e aumentar Beclometasona para 200 mcg 12/12h, mantendo o corticoide oral por 3 a 5 dias.","C":"indicar máscara de oxigênio, para manter saturação entre 94 e 98%, beta-2 agonista de curta duração inalatório 6 puffs, que poderá ser repetido a cada 20 minutos, brometo de ipratrópio e prednisolona 1-2 mg/kg, enquanto aguarda a remoção da criança para internação; e aumentar Beclometasona para 200 mcg 12/12h, associar agonista beta-2 de longa duração, mantendo o corticoide oral por 3 a 5 dias.","D":"indicar máscara de oxigênio, para manter saturação entre 93 e 95%, beta-2 agonista de curta duração inalatório 2 puffs, que poderá ser repetido a cada 20 minutos, brometo de ipratrópio e, se necessário, prednisolona 1-2 mg/kg, enquanto mantém a criança em observação na unidade de saúde; e manter Beclometasona 200 mcg por dia, associar agonista beta-2 de longa duração, mantendo o corticoide oral por 5 a 7 dias."},"answer":"C","area":"Pediatria","assunto":"Pneumologia Pediátrica","topico":"Asma ","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Classificação e Tratamento da Crise"},{"id":"revalida-2023-1-092","number":92,"stem":"Em visita domiciliar da estratégia de saúde da família, é atendido um homem com 53 anos, ex-tabagista (consumo de 20 cigarros/dia) que parou de fumar há 15 anos. Ele relata que foi submetido a colonoscopia há 3 meses, em razão de diarreia prolongada, quando se evidenciou uma lesão polipoide com 0,5 cm no reto, tendo sido realizada polipectomia, cujo laudo anatomopatológico revelou um pólipo hiperplásico. Afirma não haver história de câncer colorretal na família.\n\nA classificação de risco para câncer colorretal nesse paciente e a estratégia de acompanhamento, visando o rastreamento desse tipo de neoplasia conforme as diretrizes brasileiras, são, respectivamente,","options":{"A":"risco baixo; colonoscopia anual.","B":"risco moderado; colonoscopia anual.","C":"risco baixo; pesquisa anual de sangue oculto nas fezes.","D":"risco moderado; pesquisa anual de sangue oculto nas fezes."},"answer":"D","area":"Medicina Preventiva","assunto":"Epidemiologia","topico":"Processo saúde-doença","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":" Prevenção em Saúde"},{"id":"revalida-2023-1-094","number":94,"stem":"Uma mulher de 19 anos comparece a uma unidade de emergência com dor em fossa ilíaca esquerda há 3 dias, mais intensa nesta dia. Nega febre e afirma ter relação sexual heterossexual, utilizando-se de condon como meio de anticoncepção, de forma irregular. Refere que a última menstruação ocorreu há 45 dias. Ao exame físico, apresenta pressão arterial de 90 × 50 mmHg, frequência cardíaca de 110 batimentos por minuto, temperatura axilar de 36,7 °C, abdome doloroso em andar inferior, principalmente em fossa ilíaca esquerda, com descompressão dolorosa. Ao exame especular, nota-se sangramento discreto pelo orifício externo do colo; toque com dor a palpação de região anexial esquerda, útero intrapélvico, colo fechado.\n\nConsiderando-se o quadro descrito e os dados apresentados, o principal diagnóstico e a conduta adequada são, respectivamente,","options":{"A":"gravidez ectópica esquerda; solicitar Beta HCG e ultrassonografia transvaginal.","B":"torção anexial esquerda; solicitar ultrassonografia de abdome total e hemograma.","C":"doença inflamatória pélvica; solicitar hemograma e PCR para pesquisa de clamídia.","D":"cisto roto de ovário esquerdo; solicitar hemograma e tomografia de abdome e pelve."},"answer":"A","area":"Obstetrícia","assunto":"Intercorrências obstétricas /obstetrícia patológica","topico":"Sangramento primeira metade ","annulled":false,"images":[],"source":"Revalida INEP 2023.1","examId":"revalida-2023-1","examName":"Revalida INEP: 2023.1","subtopico":"Gestação ectópica"},{"id":"revalida-2022-2-012","number":12,"stem":"Homem de 33 anos procurou atendimento por dor em cólica, de forte intensidade, em hipocôndrio direito, iniciada havia 3 meses, com irradiação para abdome superior e dorso. Informou que alguns episódios melhoravam com o uso de analgésicos orais. Em diversas ocasiões, havia sido atendido em unidade de emergência, sendo submetido a analgesia intravenosa, devido à intensidade da dor. Relatou, ainda, que as crises dolorosas são associadas a náuseas e vômitos e desencadeadas pela ingestão de alimentos gordurosos. Negou icterícia, colúria e acolia fecal. Apresenta ritmo intestinal e aspecto das fezes normais. No exame físico, estava em bom estado geral, consciente, contactuante, orientado no tempo e no espaço, normocorado, hidratado, anictérico, acianótico, afebril, com frequência cardíaca de 64 batimentos por minuto, frequência respiratória de 16 incursões respiratórias por minuto, pressão arterial de 120 × 80 mmHg, abdome plano, ruídos hidroaéreos presentes e normais, timpânico, flácido, indolor à palpação superficial e profunda, sem sinais de irritação peritoneal, ausência de visceromegalias ou massas, sinal de Murphy negativo.\n\nRealizou exames laboratoriais, cujos resultados foram os seguintes:\n• Hemograma: hemoglobina = 16,1 g/dL; hematócrito = 49,8%; leucócitos = 5.800 mm³; segmentados = 48,5%; linfócitos = 41,5%; plaquetas = 155.000/mm³; coagulação: TP = 13,3 segundos; RNI = 1,09.\n• Urina: tipo 1 sem alterações.\n• Bioquímica: glicemia de jejum = 83 mg/dL; AST = 35 UI/L (valor de referência [VR] de 17-59); ALT = 46 UI/L (VR: 21-72); amilase = 100 UI/L (VR: 20-160); bilirrubina total = 0,8 mg/dL; bilirrubina direta = 0,5 mg/dL; bilirrubina indireta = 0,3 mg/dL.\n\nCom base no caso descrito, assinale a opção que apresenta o diagnóstico mais provável e a conduta mais apropriada, respectivamente.","options":{"A":"Coledocolitíase; colangiografia endoscópica.","B":"Colecistite aguda calculosa; ultrassonografia.","C":"Pólipo da vesícular biliar; colangiorressonância.","D":"Colelitíase sintomática; colecistectomia videolaparoscópica."},"answer":"D","area":"Cirurgia Geral","assunto":"Vesícula e Vias Biliares","topico":"Colelitíase","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"História Natural da Doença"},{"id":"revalida-2022-2-016","number":16,"stem":"Uma paciente obesa grau III, portadora de síndrome metabólica, compareceu a consulta no ambulatório de endocrinologia do hospital terciário onde faz acompanhamento, queixando-se de mialgias e fraqueza muscular generalizada há 1 semana. Segundo informado pela paciente, o quadro começou alguns dias após ela ter iniciado tratamento com fármaco para baixar seus níveis de triglicerídeos, que continuavam muito elevados a despeito do tratamento previamente em curso com rosuvastatina. Ela informou ter observado também sua urina avermelhada. O exame físico da paciente revelou leve redução de força muscular difusamente, ao passo que os exames laboratoriais, solicitados em caráter de urgência, mostraram elevados níveis séricos (superiores a 10.000 U/L) de CK-total (valor de referência: 30-200 U/L). Exame simples de urina não apresentou hematúria, mas a fita do exame mostrou um falso-positivo para hemoglobinúria. Assinale a opção que indica o fármaco hipolipemiante que foi recentemente introduzido no esquema terapêutico dessa paciente e que provavelmente levou à precipitação do quadro atual.","options":{"A":"Ezetimibe.","B":"Genfibrozil.","C":"Ácido nicotínico.","D":"Ácidos graxos ômega 3."},"answer":"B","area":"Cardiologia","assunto":"Aterosclerose e Doença Arterial Coronariana","topico":"Abordagem das dislipidemias e estratificação de risco cardiovascular","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-017","number":17,"stem":"Homem de 45 anos, sem comorbidades, procurou o pronto-socorro por apresentar dor em região anal havia 5 dias, acompanhada por prostração e calafrios. No exame físico, encontrava-se em regular estado geral, consciente, contactuante, corado, hidratado, subfebril (temperatura axilar de 37,5 °C), com frequência cardíaca de 105 batimentos por minuto, frequência respiratória de 20 incursões respiratórias por minuto, pressão arterial de 120 × 80 mmHg. Inspeção da região perianal evidenciou abaulamento à direita, sem ponto de flutuação, aumento de temperatura e vermelhidão. Toque retal com dor à palpação em quadrante posterior direito. Com base no quadro apresentado, qual é a conduta mais adequada?","options":{"A":"Antibioticoterapia venosa.","B":"Drenagem cirúrgica imediata.","C":"Termoterapia local e observação.","D":"Tomografia computadorizada da pelve."},"answer":"B","area":"Cirurgia Geral","assunto":"Proctologia","topico":"Doenças Orificiais","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Abscessos Anorretais"},{"id":"revalida-2022-2-030","number":30,"stem":"Paciente do sexo feminino, 24 anos, trabalha como técnica de enfermagem há um ano e refere surgimento de vesículas, eritema e fissuras nas mãos há seis meses, acompanhado de episódios de prurido. Relata que houve melhora do quadro no seu período de férias. A partir da história clínica dessa paciente, assinale a opção correta.","options":{"A":"Devido à localização das lesões em área descoberta do corpo da paciente é possível concluir que o diagnóstico correto é fotodermatite.","B":"A paciente apresenta ceratoses actínicas, pela cronificação do quadro, que pode ter relação direta com detergentes e exposição solar.","C":"O diagnóstico correto é dermatite de contato, irritante ou alérgica, que pode ser causada pelo látex.","D":"Diagnósticos de quadro alérgico são afastados pelo fato de o quadro melhorar no período de férias da paciente."},"answer":"C","area":"Dermatologia","assunto":"Dermatoses eczematosas","topico":"Dermatite de contato","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-034","number":34,"stem":"Uma mulher de 70 anos de idade compareceu ao ambulatório de ginecologia, queixando-se de prurido vulvar crônico e queimação local. No exame físico, apresentava apagamento de pequenos lábios, uma área hipocrômica na face interna dos grandes lábios e região perineal, além de uma pequena lesão ulcerada em grande lábio direito, próximo ao clitóris.\nAssinale a opção que indica a hipótese diagnóstica desse caso e a conduta adequada, respectivamente.","options":{"A":"Cancroide; prescrever doxiciclina.","B":"Doença de Behçet; tratar com corticoide.","C":"Câncer de vulva; realizar biópsia da lesão.","D":"Neoplasia intravaginal (NIV) usual ou lesão intraepitelial de alto grau; exérese ampla da lesão."},"answer":"C","area":"Ginecologia","assunto":"Oncologia ginecológica","topico":"Doenças de vulva e vagina","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Patologias vulvares"},{"id":"revalida-2022-2-037","number":37,"stem":"Ambulância de suporte básico de vida foi acionada para atender vítima de colisão de automóvel contra motocicleta em autoestrada. Chegando ao local, o socorrista encontrou o motorista da moto, que estava com capacete fechado, em decúbito ventral e imóvel no acostamento.\n\nEm relação à estabilização da coluna vertebral da vítima no local do acidente, qual é a melhor ordem de procedimentos a ser adotada?","options":{"A":"Retirada do capacete, colocação do colar cervical e rolamento em bloco do paciente em 180 graus.","B":"Rolamento em bloco do paciente em 180 graus, colocação do colar cervical e retirada do capacete.","C":"Retirada do capacete, rolamento em bloco do paciente em 180 graus e colocação do colar cervical.","D":"Colocação do colar cervical, retirada do capacete e rolamento em bloco do paciente em 180 graus."},"answer":"B","area":"Cirurgia Geral","assunto":"Trauma","topico":" Avaliação Inicial: Vias aéreas, Ventilação e Choque","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Avaliação Inicial"},{"id":"revalida-2022-2-050","number":50,"stem":"Uma mulher previamente hígida, de 72 anos, compareceu a unidade básica de saúde, apresentando pressão arterial (PA) de 162 × 90 mmHg, já confirmada em outras duas medidas. Não apresentava sintomas nem comorbidades.\n\nA melhor opção terapêutica e a meta de PA para essa paciente são, respectivamente","options":{"A":"diurético tiazídico; PA < 150 × 90 mmHg.","B":"mudança de estilo de vida; PA < 140 × 90 mmHg.","C":"monitorização ambulatorial da pressão arterial; PA < 120 × 80 mmHg.","D":"combinação de bloqueador de canal de cálcio e bloqueador do sistema renina-angiotensina-aldosterona; PA < 130 × 80 mmHg."},"answer":"D","area":"Cardiologia","assunto":"Hipertensão Arterial Sistêmica (HAS)","topico":"Diagnóstico e classificação ","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-060","number":60,"stem":"Joana, branca, 36 anos, G2P1A0, passou pelo acolhimento da unidade básica de saúde um dia após ter descoberto que estava grávida. Logo depois do acolhimento, o enfermeiro realizou os devidos testes rápidos para diagnóstico de infecções sexualmente transmissíveis. Todos tiveram o resultado não reagente. Apesar disso, Joana possui critérios que podem indicar o seu encaminhamento para o pré-natal de alto risco.\n\nQual das alternativas corresponde a esses critérios?","options":{"A":"Cirurgia uterina anterior e IMC de 33 kg/m2, além de sua idade corresponder a um critério de alto risco.","B":"IMC de 19 kg/m2 e não aceitação da gravidez atual, apesar de sua idade corresponder a um critério de baixo risco.","C":"Cirurgia uterina anterior e situação conjugal insegura, além de sua idade corresponder a um critério de alto risco.","D":"Dependência de drogas lícitas e índice de massa corporal (IMC) de 33 kg/m2, apesar de sua idade corresponder a um critério de baixo risco."},"answer":"A","area":"Obstetrícia","assunto":"Pré-natal","topico":"Assistência pré-natal","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Avaliação do risco gestacional"},{"id":"revalida-2022-2-066","number":66,"stem":"Paciente do sexo feminino, de 22 anos, estudante de medicina, foi levada à emergência hospitalar pelos pais, que a encontraram desacordada ao lado de cartelas vazias de clonazepam. A estudante faz acompanhamento em serviço de psiquiatria da universidade, mas os pais desconhecem diagnóstico psiquiátrico. No exame físico, a paciente encontrava-se com intensa sonolência e relaxamento muscular, diminuição dos reflexos e confusão mental.\n\nNo atendimento inicial dessa paciente, deve-se","options":{"A":"colocá-la em observação, monitorando-se seus dados vitais, pois o clonazepam tem meia-vida curta, e esperar a sua recuperação espontânea.","B":"proceder ao esvaziamento gástrico ainda na sala de emergência e prescrever naloxana endovenosa.","C":"fazer suporte clínico (hidratação e manutenção de vias aéreas) e prescrever flumazenil endovenoso.","D":"mantê-la na sala de emergência, fazer a lavagem gástrica e, em seguida, prescrever metadona via sonda nasoenteral."},"answer":"A","area":"Psiquiatria","assunto":"Intoxicações Exógenas","topico":"Síndrome Hipnossedativa","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-070","number":70,"stem":"Ao orientar uma paciente sobre a importância do preventivo de câncer de colo de útero, um profissional de enfermagem enfatizou que, conforme orientações do Ministério da Saúde, esse exame deve ser realizado por todas as mulheres com vida sexual ativa que se encontrem em determinado intervalo de idade. Essa mesma paciente apresentou seu exame, cujo resultado acusou infecção pelo HPV ou lesão de baixo grau.\n\nConsiderando o caso, assinale a opção que indica, respectivamente, o intervalo de idade recomendado pelo Manual do Ministério da Saúde para coleta do exame preventivo e a orientação que deve ser dada para a paciente em questão.","options":{"A":"15 a 35 anos; realizar colposcopia.","B":"25 a 64 anos; repetir o exame após um ano.","C":"25 a 64 anos; repetir o exame após três anos.","D":"15 a 35 anos; iniciar o tratamento imediatamente."},"answer":"B","area":"Ginecologia","assunto":"Oncologia ginecológica","topico":"Rastreamento do câncer de colo do útero","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Diretrizes para o rastreamento"},{"id":"revalida-2022-2-073","number":73,"stem":"Lactente de 30 dias, portadora de síndrome de Down, apresenta sucção fraca e dificuldade de ganho de peso. Ela necessita ser encaminhada para acompanhamento de equipe multidisciplinar.\n\nNessa situação, a orientação inicial a ser dada à mãe é","options":{"A":"oferecer o seio, realizar ordenha de 3 em 3 horas e iniciar fórmula de partida à noite.","B":"estimular a região perioral da criança e iniciar fórmula de partida exclusiva, para evitar broncoaspiração.","C":"evitar oferecer o seio, mesmo que a criança estabeleça coordenação entre sucção, deglutição e respiração.","D":"contraindicar amamentação, pois a hipotonia dificulta o aleitamento materno."},"answer":"A","area":"Pediatria","assunto":"Puericultura ","topico":"Amamentação/ Aleitamento Materno","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Prevenção e manejo dos principais problemas relacionados à amamentação"},{"id":"revalida-2022-2-074","number":74,"stem":"Primigesta de 17 anos de idade, na 32ª semana de gestação, com quadro de pré-eclâmpsia leve, foi encaminhada do ambulatório de pré-natal de alto risco diretamente para a maternidade.\n\nQual situação clínica determinou acertadamente essa conduta?","options":{"A":"Proteinúria de 5 g.","B":"Creatinina sérica de 0,9 mg/dL.","C":"Desidrogenase láctica de 490 UI.","D":"Nível tensional de 150 × 110 mmHg, mantido por 4 horas."},"answer":"A","area":"Obstetrícia","assunto":"Doenças associadas à gestação","topico":"Síndromes Hipertensivas da Gestação","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Pré-Eclâmpsia"},{"id":"revalida-2022-2-087","number":87,"stem":"Mulher de 25 anos apresentou edema, rubor e dor na pálpebra superior direita, com resolução espontânea do quadro em 48 horas. No momento, apresenta nodulação de 0,3 cm, indolor, localizada na face interna do terço médio da pálpebra superior direita. Nega febre ou que outro sintoma.\nNesse caso, qual é o diagnóstico mais provável?","options":{"A":"Calázio.","B":"Hordéolo.","C":"Canaliculite.","D":"Dacriocistite."},"answer":"A","area":"Oftalmologia","assunto":"Síndrome do Olho Vermelho","topico":"Patologias Palpebrais","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-078","number":78,"stem":"Recém-nascido de 4 horas de vida foi levado ao pronto-socorro por equipe do serviço de atendimento móvel de urgência após parto domiciliar de paciente sem histórico de realização de pré-natal. Foram prestados os primeiros atendimentos à mãe e ao bebê. Teste rápido da mãe para HIV, hepatite B e hepatite C resultaram negativos, mas, para sífilis, o resultado foi positivo. Coletado, então, teste não treponêmico, o VDRL da mãe foi de 1:8, e o da criança VDRL resultou não reagente. O recém-nascido fez os exames de hemograma completo, glicemia e radiografia de ossos longos e liquor, além de exame físico; todos resultaram normais.\n\nNesse caso, a conduta adequada para a mãe é","options":{"A":"observação clínica e programação de nova sorologia em 1 mês.","B":"penicilina benzatina 50.000 UI/kg, dose única, intramuscular.","C":"penicilina cristalina 50.000 UI/kg, intravenosa, de 12/12h, por 10 dias.","D":"penicilina procaína 50.000 UI/kg, intramuscular, uma vez ao dia, por 10 dias."},"answer":"B","area":"Pediatria","assunto":"Neonatologia","topico":"Infecções congênitas","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Sífilis congênita"},{"id":"revalida-2022-2-023","number":23,"stem":"Uma adolescente de 13 anos foi levada pela mãe à unidade básica de saúde, por apresentar desvio na coluna. Segundo informações maternas, a adolescente tem o hábito de usar uma mochila pesada só de um lado do ombro e, com o passar do tempo, tem ficado “mais torta”. A mãe informou que, quando jovem, também era assim, mas, em sua opinião, o caso da filha é pior. Negou outras queixas. No exame físico, observou-se assimetria dos ombros, escápula bastante proeminente à direita. O teste de Adams mostrou assimetria da caixa torácica.\nNo caso em questão, a hipótese diagnóstica é de","options":{"A":"escoliose familiar, sendo dispensada a investigação com exames complementares.","B":"lordose familiar, indica-se uma investigação com exame radiológico da coluna.","C":"escoliose, sendo necessária a determinação do ângulo de Cobb para indicar o tratamento clínico ou cirúrgico.","D":"lordose associada à espinha bífida, uma vez que o teste de Adams foi positivo."},"answer":"C","area":"Ortopedia","assunto":"Ortopedia Pediátrica","topico":"Coluna Pediátrica","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-042","number":42,"stem":"Paciente de 30 anos, do sexo masculino, foi atendido na emergência, com queixa de prurido nos olhos e lacrimejamento havia dois dias. No exame físico, apresentava hiperemia conjuntival, com as pálpebras edemaciadas e bordas ulceradas e crostosas, conforme a imagem apresentada a seguir.\nConsiderando-se a principal hipótese diagnóstica, qual é o agente etiológico mais comum?","options":{"A":"Adenovírus.","B":"Herpes simples.","C":"Staphylococcus aureus.","D":"Chlamydia trachomatis."},"answer":"C","area":"Oftalmologia","assunto":"Síndrome do Olho Vermelho","topico":"Patologias Palpebrais","annulled":false,"images":["assets/revalida/img/revalida-2022-2-042-1.png"],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2"},{"id":"revalida-2022-2-043","number":43,"stem":"Criança de 4 anos de idade, sexo feminino, foi levada ao pronto-socorro (PS) devido a quadro de crise convulsiva tônico-clônica generalizada, iniciada havia aproximadamente 10 minutos, associada a febre. Ao chegar ao PS, a criança encontrava-se no colo do pai, acordada, com temperatura axilar de 37 °C. Na história clínica, a mãe relatou que a crise tinha sido rápida e que ocorreu logo após ela ter administrado à criança medicação para febre, que se encontrava em 38,5 °C. Negou doença neurológica e outros sinais e sintomas. A criança tinha apresentado crise semelhante com 18 meses de idade. As crises eram sempre com febre. A criança ficou em observação por 12 horas, sem novas crises, sem alterações metabólicas.\nA partir do prontuário da família, o plantonista observou que a família estava em vulnerabilidade social e que, havia 2 anos, um filho do casal, de 1 mês de idade, tivera morte súbita.\nConsiderando o acompanhamento dessa família, assinale a opção que explicita um projeto terapêutico adequado ao caso.","options":{"A":"O acompanhamento da criança deve ser feito por especialista, o que é mais indicado para descartar trauma e violência infantil.","B":"A criança deve realizar exames complementares, como tomografia cerebral, na própria emergência, devido ao passado de morte súbita do irmão.","C":"É necessário tranquilizar os pais e garantir um acompanhamento longitudinal da criança, com observação de novas crises.","D":"A criança deve ser mantida internada para investigação, porque não é comum crise tônico-clônica generalizada com febre."},"answer":"C","area":"Pediatria","assunto":"Emergências Pediátricas","topico":"Convulsão febril ","annulled":false,"images":[],"source":"Revalida INEP 2022.2","examId":"revalida-2022-2","examName":"Revalida INEP: 2022.2","subtopico":"Abordagem da Crise Febril"}]);
